def _ffmpeg_bin():
    return shutil.which("ffmpeg") or "ffmpeg"

def parse_audio_meta(text):
    """Достаём метаданные из команды: имя "X" исполнитель "Y" описание "Z".
    Кавычки любые (" « » “ ” ' ), опечатки терпим (исполнительнь, описани...)."""
    Q = r'["«»“”‘’«»\']'
    NQ = r'["«»“”‘’«»\'\n]'
    def grab(keys):
        m = re.search(r'(?:' + '|'.join(keys) + r')\s*[:=]?\s*' + Q + r'([^' + NQ[1:-1] + r']{1,150})', text, re.IGNORECASE)
        return m.group(1).strip() if m else ""
    title   = grab(['имя', 'назван\\w*', 'тайтл', 'title'])
    artist  = grab(['исполнител\\w*', 'артист', 'автор', 'performer', 'artist'])
    comment = grab(['описани\\w*', 'коммент\\w*', 'desc\\w*', 'comment'])
    return title, artist, comment

# ⚙️ Формула ВЫВЕРЕНА ffmpeg-замерами против эталона «нейро/Auphonic» (10.06.2026, черновик↔нейро):
#   Цель эталона: I≈-16 LUFS, TP≈-1.5, LRA≈3 (выровненная громкость для долгого прослушивания).
#   highpass(гул) → afftdn(мягкий шумодав) → acompressor r2.5 (МЯГКИЙ выравниватель: LRA→~3, НЕ давит в кашу
#   как прежний r4=LRA 0.9) → loudnorm dynamic I=-16:LRA=4 (адаптивно выравнивает) → alimiter.
#   Итог на лекции: I=-15.8, TP=-1.6, LRA=3.2 (= нейро). На коротком войсе не крушит (LRA 4.1). 192k/44.1k.
_ENH_PRE = ("highpass=f=70,"
            "afftdn=nf=-25:nr=10,"
            "acompressor=threshold=-18dB:ratio=2.5:attack=20:release=250")

def enhance_audio(input_path, output_path, artist="", title="", comment="", enhance=True):
    """Конвертация (+опц. студийное улучшение «как нейро/Auphonic») в mp3 через ffmpeg.
    Цепочка выверена замерами (см. _ENH_PRE): шумодав + мягкое выравнивание громкости (LRA≈3) +
    нормализация к -16 LUFS, пик -1.5. Теги пишем метаданными."""
    try:
        cmd = [_ffmpeg_bin(), "-y", "-i", input_path]
        if enhance:
            af = _ENH_PRE + ",loudnorm=I=-16:TP=-1.5:LRA=4,alimiter=level_in=1:level_out=1:limit=0.98"
            cmd += ["-af", af, "-ar", "44100", "-ac", "2", "-b:a", "192k"]
        else:
            cmd += ["-ar", "44100", "-ac", "2", "-b:a", "160k"]
        if title:   cmd += ["-metadata", "title=" + title]
        if artist:  cmd += ["-metadata", "artist=" + artist]
        if comment: cmd += ["-metadata", "comment=" + comment]
        cmd += [output_path]
        r = subprocess.run(cmd, capture_output=True, timeout=300)
        if r.returncode != 0:
            print("ffmpeg error:", (r.stderr or b"").decode("utf-8", "ignore")[-600:])
            return False
        return os.path.exists(output_path) and os.path.getsize(output_path) > 100
    except Exception as e:
        print(f"enhance_audio error: {e}")
        return False

def convert_to_mp3(input_path, output_path, artist="", title="", comment=""):
    """Простая конвертация в mp3 (без улучшения). Сначала ffmpeg, при сбое — pydub."""
    if enhance_audio(input_path, output_path, artist=artist, title=title, comment=comment, enhance=False):
        return True
    try:
        from pydub import AudioSegment
        sound = AudioSegment.from_file(input_path)
        sound.export(output_path, format="mp3", bitrate="160k", tags={
            "artist": artist or "Unknown",
            "title": title or "Без названия",
            "comment": comment or ""
        })
        return True
    except Exception as e:
        print(f"Convert error: {e}")
        return False

async def _зов_сети(метод, *а, **к):
    """Сетевой запрос ИЗ ПОТОКА, а не из событийного цикла.

    🔴 03.09.2026. Синхронный requests внутри async-функции держит весь бот: пока запрос
    идёт, не отвечает никто — ни чат, ни двери приложения, ни сторожа. Разбор кода нашёл
    таких мест 37; самое горячее (потоковый ответ помощника) уже вынесено, эта обёртка —
    для остальных. Пишется одинаково с обычным вызовом, только через await:
        _r = await _зов_сети('get', адрес, timeout=15)
    """
    _ф = getattr(requests, метод)
    return await asyncio.get_event_loop().run_in_executor(None, lambda: _ф(*а, **к))


def transcribe_audio(path):
    """Расшифровка речи. Сначала Groq (бесплатно), потом OpenAI. Текст или None.

    🔴 03.09.2026, заявка №630. Владелец просил: «обеспечь, чтобы он мог читать аудио и
    находить оригинал». Дверь была ОДНА — OpenAI Whisper, а на его счёте кончились деньги:
    прямой запрос отвечает `credit_balance_exhausted`. То есть бот молча не понимал НИ ОДНОГО
    голосового, а в справке у него написано «расшифрую речь и найду оригинал хадиса».
    Обещание без исполнения хуже отсутствия обещания.

    У Groq тот же whisper есть бесплатно, и он ЖИВ: проверено 03.09 — обе модели отвечают за
    0,1–0,2 с. Ставим его первым, OpenAI оставляем запасным: деньги на счёт могут вернуться,
    и тогда путь снова заработает сам, без правок.
    """
    _файл = os.path.basename(path) or "audio.ogg"

    # ① Groq — бесплатный и быстрый. turbo сначала: он вдвое шустрее при том же качестве.
    if GROQ_API_KEY:
        for _м in ("whisper-large-v3-turbo", "whisper-large-v3"):
            try:
                with open(path, "rb") as fh:
                    r = requests.post(
                        "https://api.groq.com/openai/v1/audio/transcriptions",
                        headers={"Authorization": "Bearer " + GROQ_API_KEY,
                                 "User-Agent": "Mozilla/5.0"},
                        files={"file": (_файл, fh, "application/octet-stream")},
                        data={"model": _м},
                        timeout=300)
                if r.status_code == 200:
                    _т = ((r.json() or {}).get("text") or "").strip()
                    if _т:
                        return _т
                else:
                    print("groq whisper %s: код %d %s" % (_м, r.status_code, r.text[:150]))
            except Exception as e:
                print("groq whisper %s: %s" % (_м, str(e)[:150]))

    # ② OpenAI — запасной путь.
    if not OPENAI_API_KEY:
        return None
    try:
        with open(path, "rb") as fh:
            r = requests.post(
                "https://api.openai.com/v1/audio/transcriptions",
                headers={"Authorization": "Bearer " + OPENAI_API_KEY},
                files={"file": (_файл, fh, "application/octet-stream")},
                data={"model": "whisper-1"},
                timeout=300)
        if r.status_code == 200:
            return (r.json() or {}).get("text", "").strip()
        print("whisper error:", r.status_code, r.text[:200])
        return None
    except Exception as e:
        print(f"transcribe error: {e}")
        return None

def is_owner(update: Update) -> bool:
    user_id = update.effective_user.id if update.effective_user else 0
    sender_chat_id = 0
    if update.message and update.message.sender_chat:
        sender_chat_id = update.message.sender_chat.id
    # 🔴 19.08.2026, ОКОНЧАТЕЛЬНАЯ причина, по которой команда владельца не работала в чате.
    # Он пишет от имени своего канала — такие сообщения приходят как channel_post, и
    # update.message у них ПУСТ. Значит подпись канала здесь не читалась вовсе, и владелец,
    # писавший от Муслимуна, для бота был чужим. Правило про его канал существовало и не
    # работало: смотрели не туда, где лежит ответ.
    # Беру подпись из любого вида сообщения, а не только из обычного.
    if not sender_chat_id:
        for _вид in (getattr(update, 'channel_post', None),
                     getattr(update, 'edited_message', None),
                     getattr(update, 'edited_channel_post', None)):
            _sc = getattr(_вид, 'sender_chat', None) or getattr(_вид, 'chat', None)
            if _sc and getattr(_sc, 'id', 0):
                sender_chat_id = _sc.id
                break

    if user_id == OWNER_ID:
        return True

    # 🔴 07.08.2026. У владельца ДВА личных аккаунта, и он об этом напоминал не раз. Переменная
    # OWNER_ID2 в проекте была заведена и даже читалась в пяти местах — но НЕ ЗДЕСЬ, в самой
    # главной проверке, через которую проходит всё: помощник, зов технадзора, ИИ в личке,
    # заявки, доступ к разбору. То есть со второго аккаунта владелец переставал быть владельцем
    # везде, где это по-настоящему важно, и оставался им в мелочах.
    # Такую дыру невозможно заметить по поведению: с основного аккаунта всё работает.
    if OWNER_ID2 and user_id == OWNER_ID2:
        return True

    # Канал MUSLIMOON — его вторая подпись, он им пользуется постоянно.
    if sender_chat_id == OWNER_CHANNEL_ID:
        return True

    # 🔴 10.08.2026, обращение #304: «у меня есть также чат MUSLIM CHAT, и я от его имени ему
    # написал. Но следи, чтобы он по ошибке не добавил запросы от ВСЕХ каналов опять — строго
    # меня».
    # Оговорка «опять» — про дыру, которую он сам закрыл 07.08: тогда владельцем считался
    # ЛЮБОЙ, кто пишет анонимно от лица группы, и чужой админ мог говорить со мной его
    # голосом. Поэтому добавляю РОВНО ОДИН чат по номеру, а не правило «от лица группы».
    # Список закрытый и виден целиком: третьего адреса без его слова тут не появится.
    if sender_chat_id == MUSLIM_CHAT_ID:
        return True

    # 🔴 07.08.2026, 21:10. Дальше — НИКОГО. Раньше владельцем считался ещё и всякий, кто
    # пишет анонимно от имени чата (правило жило в _хозяин). Оно было нужным: без него его
    # анонимные сообщения не доходили. Но признавало владельцем ЛЮБОГО админа джамаата —
    # для бота они неотличимы, и чужой мог бы обратиться ко мне ОТ ЕГО ИМЕНИ.
    # Я назвал ему дыру, он закрыл её приказом: «впиши ид Муслимун только и две лички мои».
    # Владелец — это три подписи и ни одной больше.
    return False

# ============ ПАРСЕРЫ ============
def parse_hadith_query(text):
    text = text.lower().strip()
    # аль-Мухаймин: "мухэймин 145" / "мухаймин 145" / "муршид 145"
    for trigger in ("мухэймин ", "мухаймин ", "муршид "):
        if text.startswith(trigger):
            num = text[len(trigger):].strip()
            if num.isdigit():
                return "riwayat", int(num)

    if text == "случайный": return "random", None
    if text == "случайный бухари": return "random_bukhari", None
    if text == "случайный муслим": return "random_muslim", None
    if text == "случайный коран": return "random_quran", None
    # 📚 ОПРЕДЕЛЁННЫЙ АРТИКЛЬ — ВСЕ ЕГО ВИДЫ, А НЕ ОДИН (обращение #453, 11.08.2026).
    # Владелец: «Тирмизи и ат-Тирмизи — одно и то же», и показал, как на «ат-Тирмизи 89» бот
    # выдал «العرف الشذي شرح سنن الترمذي» — ТОЛКОВАНИЕ Тирмизи вместо самого сборника.
    #
    # Корень был здесь и был в одну строку: срезалось только «аль». Арабский артикль «ال»
    # перед «солнечными» буквами читается по следующей букве — ат-, ас-, аш-, ад-, аз-, ан-,
    # ар-, — и все эти виды до сих пор не срезались. «ат-тирмизи 89» не совпадал ни с одним
    # ключом COLLECTIONS, проваливался ниже, доходил до каталога Мактабы (8 589 книг) — а там
    # имя «الترمذي» стоит и в названии толкований. Шарх выигрывал случайно, по месту в списке.
    #
    # Остаток требуем не короче трёх букв: иначе «ан 5» или «ад 7» начнут срезаться в пустоту.
    _tc = re.sub(r"^(?:аль|ал|ат|ас|аш|ад|аз|ан|ар)[\s\-]+(?=\S{3})", "", text)
    for ru, en in COLLECTIONS.items():
        for _t in (text, _tc):
            if _t.startswith(ru):
                num = _t.replace(ru, "", 1).strip()
                if num.isdigit(): return en, int(num)
            if _t.endswith(" " + ru):
                num = _t[:-len(ru)].strip()
                if num.isdigit(): return en, int(num)
    # #448: то же для Мухаймина: «145 мухаймин»
    for trigger in ("мухэймин", "мухаймин", "муршид"):
        if text.endswith(" " + trigger):
            num = text[:-len(trigger)].strip()
            if num.isdigit(): return "riwayat", int(num)
    return None, None

def parse_quran_query(text):
    text = text.lower().strip()
    if text.startswith("коран"):
        ref = text.replace("коран", "").strip()
        if ":" in ref:
            parts = ref.split(":")
        elif " " in ref:
            parts = ref.split()
        else:
            return None, None
        if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
            return int(parts[0]), int(parts[1])
    return None, None

def parse_search_query(text):
    t = text.lower().strip()
    if t.startswith("искать "): return t[7:].strip()
    if t.startswith("поиск "): return t[6:].strip()
    return None

def parse_translate(text):
    t = text.lower().strip()
    if t.startswith("переведи "): return t[9:].strip()
    if t == "переведи": return "REPLY"
    return None

def parse_botyara(text):
    t = text.lower().strip()
    for p in ["ботяра ", "botyara "]:
        if t.startswith(p): return t[len(p):].strip()
    if t in ["ботяра", "botyara"]: return ""
    return None


# ═══════════════════════════════════════════════════════════════════════════════════════
#  🟩 DSOC: разбор обращения, память разговора, расход
# ═══════════════════════════════════════════════════════════════════════════════════════
DSOC_ПАМЯТЬ = {}          # chat_id → список реплик [{role, content}]
DSOC_ЗАЯВКА_ЖДЁТ = {}     # chat_id → предложение, ждущее «да» от владельца
def dsoc_чистые(реплики):
    """Модели уходит только role и content: служебные метки — наше дело, не её."""
    return [{"role": р.get("role"), "content": р.get("content")} for р in (реплики or [])]


def dsoc_когда_отвечал(chat_id):
    """Когда помощник отвечал в этом чате в последний раз.

    🔴 Метка живёт ВНУТРИ переписки, а не в отдельном словаре в памяти процесса. Прежний
    вариант обнулялся каждой выкаткой, и через минуту после деплоя бот уже не помнил, что
    разговор идёт с помощником, — реплику подхватывал старый путь на Groq. Третий случай
    одного класса за час; чиню класс: метка едет вместе с тем, к чему относится."""
    try:
        for р in reversed(dsoc_память(chat_id) or []):
            if р.get("role") == "assistant" and р.get("t"):
                return float(р["t"])
    except Exception:
        pass
    return 0
DSOC_РАСХОД = []          # (когда, стоимость) — для остатка лимитов
DSOC_ФАЙЛ = "dsoc_context.json"


DSOC_БЕЛЫЙ_ФАЙЛ = "dsoc_dostup.json"
# Кому и когда уже сказали «пока только владельцу». Отказ по смыслу одноразовый: человек
# услышал — повторять на каждую его реплику незачем. Час молчания на человека (см. заслон).
DSOC_ОТКАЗ_СКАЗАН = {}
DSOC_ОТКАЗ_МОЛЧАТЬ = 3600
_DSOC_ДОСТУП = {"кэш": None, "т": 0.0}


def dsoc_доступ():
    """Кто допущен к помощнику. Живёт в ветке data — выкатка не стирает."""
    if _DSOC_ДОСТУП["кэш"] is not None and time.time() - _DSOC_ДОСТУП["т"] < 120:
        return _DSOC_ДОСТУП["кэш"]
    д = _data_get(DSOC_БЕЛЫЙ_ФАЙЛ, None)
    if not isinstance(д, dict):
        д = {"белый": [], "чёрный": [], "чаты": []}
    _DSOC_ДОСТУП["кэш"] = д
    _DSOC_ДОСТУП["т"] = time.time()
    return д


def dsoc_доступ_записать(д, зачем):
    _DSOC_ДОСТУП["кэш"] = д
    _DSOC_ДОСТУП["т"] = time.time()
    try:
        _data_put(DSOC_БЕЛЫЙ_ФАЙЛ, д, зачем)
    except Exception:
        pass


def dsoc_рубильник():
    """Включён ли помощник вообще. Хранится в ветке data — переживает выкатку."""
    д = dsoc_доступ()
    return not bool(д.get("выключен"))


def dsoc_рубильник_поставить(выкл, кто="владелец", почему=""):
    д = dsoc_доступ()
    д["выключен"] = bool(выкл)
    д["выключен_когда"] = datetime.now().strftime("%d.%m.%Y %H:%M")
    д["выключен_кем"] = кто
    д["выключен_почему"] = почему[:300]
    dsoc_доступ_записать(д, ("ВЫКЛЮЧЕН помощник: " if выкл else "включён помощник: ") + (почему or кто))
    return д


def dsoc_можно(update):
    """Пускать ли этого человека к помощнику. Возвращает (можно, почему_нет)."""
    try:
        _п = update.effective_user
        _ид = _п.id if _п else 0
        _чат = update.effective_chat.id if update.effective_chat else 0
    except Exception:
        return False, "не понял, кто спрашивает"
    if is_owner(update) or _ид == OWNER_ID or (OWNER_ID2 and _ид == OWNER_ID2):
        return True, ""
    д = dsoc_доступ()
    if _ид in (д.get("чёрный") or []):
        return False, "чёрный список"
    if _ид in (д.get("белый") or []):
        return True, ""
    if _чат in (д.get("чаты") or []):
        return True, ""
    return False, "не в белом списке"


def dsoc_белый_добавить(ид, имя, чей="владелец"):
    д = dsoc_доступ()
    б = list(д.get("белый") or [])
    if ид not in б:
        б.append(ид)
    д["белый"] = б
    д["чёрный"] = [x for x in (д.get("чёрный") or []) if x != ид]
    д.setdefault("имена", {})[str(ид)] = имя
    dsoc_доступ_записать(д, "белый список +%s (%s), решение: %s" % (ид, имя, чей))
    return len(б)


def dsoc_чёрный_добавить(ид, имя, чей="владелец"):
    д = dsoc_доступ()
    ч = list(д.get("чёрный") or [])
    if ид not in ч:
        ч.append(ид)
    д["чёрный"] = ч
    д["белый"] = [x for x in (д.get("белый") or []) if x != ид]
    д.setdefault("имена", {})[str(ид)] = имя
    dsoc_доступ_записать(д, "чёрный список +%s (%s), решение: %s" % (ид, имя, чей))
    return len(ч)


def _это_команда_бота(text):
    """Названа ли ПРЯМАЯ команда бота — «бухари 5590», «коран 2:255», «карточка …» и прочие.

    Одна мерка на два места: её спрашивает старый путь в личке и она же решает, брать ли
    реплику помощнику (обращения #53/#58 — «раздвоение личности»). Раньше список стоял
    развёрнутым в одном месте; вторая копия неизбежно разошлась бы с первой, и вышло бы, что
    одно и то же слово в двух ветках считается то командой, то разговором.
    Человек назвал инструмент прямо — подменять его выбор нельзя, даже помощником.
    """
    try:
        if parse_hadith_query(text)[0]: return True
        if parse_browse(text)[0]: return True
        if parse_source_query(text)[0] in SOURCE_ONLY_CODES: return True
        if parse_quran_query(text)[0]: return True
        if parse_search_query(text): return True
        if parse_sunnah(text): return True
        if parse_smart_sunnah(text): return True
        if parse_transmitter(text): return True
        if parse_translate(text): return True
        if parse_tafsir_query(text)[0]: return True
        if parse_registry_command(text): return True
        if (text or '').lower() in ("память", "помощь", "справка", "команды"): return True
        if (text or '').lower().startswith(("запомни", "удали память", "исправь память",
                                            "очистить память", "бахни mp3", "корень ")): return True
        if parse_botyara(text) is not None: return True
    except Exception:
        # Разбор споткнулся — считаем разговором, а не командой: помощник хотя бы ответит
        # по-человечески, а молчание команды выглядит как поломка.
        return False
    return False


def parse_dsoc(text):
    """«DSOC переведи» → «переведи». Не к нему обращаются → None.

    Пишется как угодно: DSOC, dsoc, ДСОС — владелец печатает быстро и с телефона,
    придираться к регистру и раскладке значит ломать ему работу на ровном месте.
    """
    t = (text or "").strip()
    for p in ("dsoc", "дсос", "дсок"):
        н = t.lower()
        if н.startswith(p):
            хвост = t[len(p):].lstrip(" ,:—-")
            return хвост.strip()
    return None


def dsoc_память(chat_id):
    """Память разговора. 🔴 05.08.2026: лежала в файле на диске контейнера Railway, а он
    стирается КАЖДЫМ деплоем — и разговор молча начинался заново. Владелец увидел это как
    «контекст был 4282, стал меньше — куда исчез?». Не исчез: его стёрли выкаткой.
    Тот же класс, что и у счётчика трат (Н-176), — и я тогда починил частный случай вместо
    класса. Теперь память в ветке data: деплой ей не страшен."""
    if chat_id not in DSOC_ПАМЯТЬ:
        вся = None
        try:
            вся = _data_get(DSOC_ФАЙЛ, None)
        except Exception:
            вся = None
        if вся is None:                       # запасной путь: старый локальный файл
            try:
                вся = json.load(open(DSOC_ФАЙЛ, encoding="utf-8"))
            except Exception:
                вся = {}
        DSOC_ПАМЯТЬ[chat_id] = (вся or {}).get(str(chat_id), [])
    return DSOC_ПАМЯТЬ[chat_id]


_ДСОС_ПАМ_ГРЯЗНО = [0, 0.0]


def dsoc_сохранить(силой=False):
    """Пишем пачкой: запись в ветку — коммит, и делать его на каждое сообщение незачем.
    Но первую запись после старта — сразу, иначе короткая жизнь процесса всё потеряет."""
    # 🔴 05.08.2026: писал пачкой — раз в три сообщения. В обычный день это разумно, а
    # сегодня деплои идут каждые пять минут, и каждый уносил незаписанный хвост разговора.
    # Владелец: «пять минут назад обсуждали, а ты не помнишь». Пишем СРАЗУ: лишний коммит
    # дешевле потерянного разговора.
    _ДСОС_ПАМ_ГРЯЗНО[0] += 1
    try:
        _data_put(DSOC_ФАЙЛ, {str(k): v[-120:] for k, v in DSOC_ПАМЯТЬ.items()},
                  "память разговоров DSOC")
        _ДСОС_ПАМ_ГРЯЗНО[0] = 0
        _ДСОС_ПАМ_ГРЯЗНО[1] = time.time()
    except Exception:
        pass


def dsoc_размер(реплики):
    """Грубая, но честная оценка в токенах: для русского с арабским ≈ 3 знака на токен."""
    return sum(len(r.get("content") or "") for r in реплики) // 3


def dsoc_ужать(реплики):
    """Разговор дорос до потолка — ужимаем СЕРЕДИНУ, а не хвост.

    Начало держит уговор о том, как работать; конец — то, о чём говорим сейчас. Резать надо
    середину: там пересказ уже случившегося, и его не жалко свернуть в краткую выжимку.
    """
    if len(реплики) < 12:
        return реплики
    голова, хвост = реплики[:4], реплики[-8:]
    середина = реплики[4:-8]
    свод = " · ".join((r.get("content") or "")[:120] for r in середина[-40:])
    return голова + [{"role": "system",
                      "content": "Кратко о том, что обсуждалось раньше: " + свод[:6000]}] + хвост


def dsoc_стоимость(вх, вых):
    цв, цо, цк = DSOC_ЦЕНА
    return round((вх * 0.05 * цв + вх * 0.95 * цк + вых * цо) / 1e6, 6)


