def автор_запомнить(chat_id, message_id, кто):
    """Записать, чьё это сообщение. Дёшево: в памяти, на диск — раз в 5 минут."""
    try:
        c, m = int(chat_id), int(message_id)
    except Exception:
        return
    _ПОСЛЕДНИЙ_ГОЛОС[str(c)] = (кто, time.time())
    д = КТО_СКАЗАЛ.setdefault(str(c), {})
    д[str(m)] = кто
    if len(д) > 600:       # держим только свежее: отвечают на недавнее
        for к in sorted(д, key=lambda x: int(x))[:len(д) - 600]:
            д.pop(к, None)
    _АВТОРЫ_ГРЯЗНО[0] = 1


def автор_чей(chat_id, message_id, текст=''):
    """Кто написал это сообщение. Реестр — главный, текст — запасной путь.

    Запасной нужен для сообщений, отправленных ДО появления реестра, и для тех, что
    ушли мимо точки входа. Возвращает ключ сессии или '' (значит — помощник)."""
    try:
        к = (КТО_СКАЗАЛ.get(str(int(chat_id))) or {}).get(str(int(message_id)))
        if к:
            return к
    except Exception:
        pass
    for ключ, (_, _, примета) in ПОДПИСИ_СЕССИЙ.items():
        if примета and re.search(примета, текст or ''):
            return ключ
    return ''


