# ---- Муслим: нумерация Абд аль-Баки (как в приложении и у учёных), а НЕ fawazahmed0 (M197) ----
_MUSLIM_BAQI = None
def _load_muslim_baqi():
    """Карта Муслима Абд аль-Баки {num: {ar, fw}} (docs/muslim_baqi.json), грузим один раз."""
    global _MUSLIM_BAQI
    if _MUSLIM_BAQI is not None:
        return _MUSLIM_BAQI
    _MUSLIM_BAQI = {}
    for u in (f"https://cdn.jsdelivr.net/gh/{GITHUB_REPO}@main/docs/muslim_baqi.json",
              f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/docs/muslim_baqi.json"):
        try:
            r = requests.get(u, timeout=20)
            if r.status_code == 200:
                _MUSLIM_BAQI = {int(x["num"]): x for x in r.json() if "num" in x}
                break
        except: pass
    return _MUSLIM_BAQI

def _norm_ar(s):
    return re.sub(r"[^ء-ي]", "", s or "")

_MUSLIM_ЧИСТ = {}


def _муслим_чистый(number):
    """Риваяты Муслима НАШИМ текстом: docs/muslim_chist/<номер//200>.json → [текст, текст, …].

    🔴 21.08.2026, обращение владельца #1086: «направил запрос Муслим 2769 — ответ пришёл
    несколько постов, вся книга Муслима наверное». Причина была в источнике: помощник брал
    текст из docs/muslim_baqi.json, издания Абд аль-Баки, где у 2769 арабского 15 326 знаков —
    в тело хадиса вклеен шарх ан-Навави. Телеграм режет по 3900, отсюда четыре поста подряд.
    И это не редкость: длиннее 4000 знаков там 180 записей из 2976 (6,0%), самая большая
    54 343 знака — четырнадцать сообщений на один запрос.

    А главное — от издания Баки проект УШЁЛ ещё по заявке #690 («мы ушли от издания баки,
    Муслим не баки»). Приложение тогда перевели, помощник остался: правило лежало в журнале
    обновлений, а не в правилах, и до второго исполнителя не дошло. Теперь это R60.

    Берём из того же потока, по которому Муслима показывает приложение (miniapp/reader/
    muslim.json → шарды muslim_chist). Там у 2769 два риваята, 1007 и 817 знаков.
    """
    try:
        б = int(number) // 200
        if б not in _MUSLIM_ЧИСТ:
            куски = {}
            for u in (f"https://cdn.jsdelivr.net/gh/{GITHUB_REPO}@main/docs/muslim_chist/{б}.json",
                      f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/docs/muslim_chist/{б}.json"):
                try:
                    r = requests.get(u, timeout=20)
                    if r.status_code == 200:
                        куски = r.json()
                        break
                except Exception:
                    pass
            _MUSLIM_ЧИСТ[б] = куски
        сп = (_MUSLIM_ЧИСТ.get(б) or {}).get(str(int(number)))
        return [t for t in (сп or []) if str(t or "").strip()]
    except Exception:
        return []


# Ни один ответ не должен разъезжаться на несколько сообщений: предел Телеграма 4096, send_long
# режет по 3900. Оставляем запас на шапку, ссылки и тахкик — арабского берём не больше этого.
МУСЛИМ_ПРЕДЕЛ = 2600


def get_muslim_baqi_hadith(number):
    """Муслим НАШИМ текстом (см. _муслим_чистый) + готовый русский из fawazahmed0.

    Имя оставлено прежним намеренно: его зовут из get_hadith, и переименование ради красоты
    развело бы одно поведение по двум местам. Изменился ИСТОЧНИК арабского, а не роль функции.
    Русский по-прежнему берём по карте fw и только если арабский у fawaz совпал с нашим (поле
    fw местами битое — без сверки вернули бы чужой перевод, баг M197).
    None → номера нет ни у нас, ни в карте (общий путь через CDN)."""
    try:
        риваяты = _муслим_чистый(number)
        e = _load_muslim_baqi().get(int(number))
        if not риваяты and not e:
            return None
        if риваяты:
            # Каждый риваят своей строкой с подписью — закон R54: версия не склеивается с версией.
            куски, всего = [], 0
            for i, т in enumerate(риваяты, 1):
                г = "▫️ Риваят %d/%d\n%s" % (i, len(риваяты), т) if len(риваяты) > 1 else т
                if всего + len(г) > МУСЛИМ_ПРЕДЕЛ:
                    остаток = МУСЛИМ_ПРЕДЕЛ - всего
                    if остаток > 400:
                        куски.append(г[:остаток] + " …")
                        всего = МУСЛИМ_ПРЕДЕЛ
                    куски.append("…показан не весь текст: он длиннее одного сообщения. "
                                 "Целиком — в приложении, ссылка ниже.")
                    break
                куски.append(г)
                всего += len(г)
            arabic = "\n\n".join(куски).strip()
        else:
            arabic = (e.get("ar") or "").replace("\n", " ").strip()
        russian = grade = ""
        fw = (e or {}).get("fw")
        # Сверять перевод есть смысл только с ОДИНОЧНЫМ риваятом: у склейки нескольких первые
        # сорок знаков принадлежат первому, и совпадение ничего не доказывает.
        if fw and arabic and len(риваяты) <= 1:
            try:
                ra = requests.get(f"https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/ara-muslim/{fw}.min.json", timeout=10)
                ok = False
                if ra.status_code == 200:
                    ha = ra.json().get("hadiths", [])
                    if ha:
                        ok = _norm_ar(ha[0].get("text", ""))[:40] == _norm_ar(arabic)[:40]
                if ok:
                    rr = requests.get(f"https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/rus-muslim/{fw}.min.json", timeout=10)
                    if rr.status_code == 200:
                        hr = rr.json().get("hadiths", [])
                        if hr:
                            russian = re.sub(r"\[\d+\]", "", hr[0].get("text", "").replace("\\n", " "))
            except: pass
        return arabic, russian, ("рус" if russian else "араб"), grade
    except:
        return None

def get_hadith(collection, number):
    if collection == "muslim":
        res = get_muslim_baqi_hadith(number)
        if res is not None:
            return res
    try:
        ua = f"https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/ara-{collection}/{number}.min.json"
        ur = f"https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/rus-{collection}/{number}.min.json"
        ue = f"https://cdn.jsdelivr.net/gh/fawazahmed0/hadith-api@1/editions/eng-{collection}/{number}.min.json"
        arabic = russian = english = grade = ""
        # арабский — главное; берём с повтором и фолбэк-CDN (бывают таймауты)
        ua_fallback = f"https://raw.githubusercontent.com/fawazahmed0/hadith-api/1/editions/ara-{collection}/{number}.min.json"
        for u in (ua, ua, ua_fallback):
            try:
                r = requests.get(u, timeout=15)
                if r.status_code == 200:
                    h = r.json().get("hadiths", [])
                    if h and h[0].get("text", "").strip():
                        arabic = h[0].get("text", "").replace("\n", " ")
                        break
            except: pass
        try:
            r = requests.get(ur, timeout=10)
            if r.status_code == 200:
                h = r.json().get("hadiths", [])
                if h:
                    t = h[0].get("text", "").replace("\\n", " ")
                    russian = re.sub(r"\[\d+\]", "", t)
                    g = h[0].get("grades", [])
                    if g: grade = GRADE_MAP.get(g[0].get("grade", ""), "")
        except: pass
        if not russian:
            try:
                r = requests.get(ue, timeout=10)
                if r.status_code == 200:
                    h = r.json().get("hadiths", [])
                    if h:
                        english = h[0].get("text", "")
                        if not grade:
                            g = h[0].get("grades", [])
                            if g: grade = GRADE_MAP.get(g[0].get("grade", ""), "")
            except: pass
        translation = russian or english
        lang = "рус" if russian else "англ"
        if arabic or translation: return arabic, translation, lang, grade
    except: pass
    return "", "", "", ""

def get_ahmad_hadith(number):
    try:
        if number <= 561:
            url = f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/ahmad_1.json"
        elif number <= 1380:
            url = f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/ahmad_2.json"
        elif number <= 14600:
            url = f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/ahmad_3a.json"
        else:
            url = f"https://raw.githubusercontent.com/{GITHUB_REPO}/main/ahmad_3b.json"
        r = requests.get(url, timeout=10)
        if r.status_code == 200:
            data = r.json()
            for h in data:
                if h["number"] == number:
                    grade_map = {"صحيح": "Сахих ✅", "حسن": "Хасан 🟡", "ضعيف": "Да'иф ⚠️"}
                    grade = grade_map.get(h.get("grade", ""), h.get("grade", ""))
                    return h["arabic"], "", "араб", grade
    except: pass
    return "", "", "", ""


def get_random_hadith(collection=None):
    if collection is None: collection = random.choice(["bukhari", "muslim"])
    for _ in range(10):
        num = random.randint(1, MAX_HADITH.get(collection, 1000))
        a, t, l, g = get_hadith(collection, num)
        if a or t: return collection, num, a, t, l, g
    return None, None, "", "", "", ""

def get_quran_ayah(surah, ayah):
    try:
        ua = f"https://cdn.jsdelivr.net/gh/fawazahmed0/quran-api@1/editions/ara-quranindopak/{surah}/{ayah}.min.json"
        ur = f"https://cdn.jsdelivr.net/gh/fawazahmed0/quran-api@1/editions/rus-elmirkuliev/{surah}/{ayah}.min.json"
        a = r = ""
        ra = requests.get(ua, timeout=10)
        if ra.status_code == 200: a = ra.json().get("text", "")
        rr = requests.get(ur, timeout=10)
        if rr.status_code == 200: r = rr.json().get("text", "")
        return a, r
    except: return "", ""

