def _новичок_ли(uid, chat_id):
    """Вошёл ли человек в ЭТОТ чат меньше трёх дней назад. Нет записи — не новичок.

    Дату входа мы записываем с 08.08.2026 (обращение #177). О тех, кто зашёл раньше, у нас
    записи нет, и назвать их новичками нельзя — молчание не улика.
    """
    try:
        _сп = _data_get('chat_members.json', []) or []
    except Exception:
        return None
    _мои = [z for z in _сп
            if str(z.get('id')) == str(uid) and str(z.get('чат')) == str(chat_id)
            and z.get('что') == 'вошёл']
    if not _мои:
        return None
    _к = _мои[-1].get('когда') or ''
    try:
        _д = datetime.strptime(str(_к)[:16], '%d.%m.%Y %H:%M')
    except Exception:
        return None
    _возраст = (datetime.now() - _д).total_seconds() / 86400.0
    return _возраст if 0 <= _возраст <= ПРИСМОТР_ДНЕЙ else None


