def _ru_ar_terms(q):
    """Рус-запрос → классич. арабские слова из лексикона (детерминированно). [] если не нашлось.
    Матчинг по НАЧАЛУ слова (музыке→музык ✅, но терпение↛пение); фразы — подстрокой; короткие — точным словом."""
    low = (q or '').lower().replace('ё', 'е')
    words = re.findall(r'[а-я]+', low)
    out, seen = [], set()
    for keys, terms in _RAG_LEX.items():
        hit = False
        for k in keys:
            kk = k.strip()
            if not kk:
                continue
            if ' ' in kk:                       # фраза → подстрока
                hit = kk in low
            elif len(kk) <= 2:                  # очень короткий (ад) → точное слово
                hit = kk in words
            else:                               # обычный стем → слово начинается со стема
                hit = any(w.startswith(kk) for w in words)
            if hit:
                break
        if hit:
            for t in terms:
                if t not in seen:
                    seen.add(t); out.append(t)
    return out

def _в_арабские_слова(q, owner=False):
    """Русский вопрос → арабские слова, которыми его можно искать в текстах хадисов.

    🔴 02.09.2026, найдено пробой через /api/vyzov. «ВЫЗОВ: смысл» описан в промте помощника
    как поиск «человеческими словами», и там же стоит пример «что делать при затмении». Проба
    ровно этим примером вернула НОЛЬ; проба тем же вопросом по-арабски — нужный хадис первым.
    То есть по-русски поиск не искал вовсе, а помощник, следуя нашей же инструкции, спрашивал
    по-русски и честно докладывал владельцу «в базе не нашлось».

    Машинка перевода вопроса в арабские слова существовала — но ЖИЛА ВНУТРИ ветки команды
    «раг» и никому больше не была доступна. Тот же класс, что «формула, не поставленная в
    боевой конфиг»: работа сделана, а до второй двери не доведена. Выношу её сюда, чтобы обе
    двери пользовались ОДНОЙ (З-33), а не завели по своей копии, которые завтра разойдутся.
    """
    if not q or re.search(r'[؀-ۿ]', q):
        return [q] if q else []
    слова = list(_ru_ar_terms(q))            # лексикон — надёжно и без денег
    # ИИ добавляем, а не подменяем им лексикон: длинный пересказ несёт несколько ключевых
    # слов, лексикон ловит лишь часть, и главный хадис теряется.
    if len(re.findall(r'[а-яё]+', q.lower())) >= 3 or len(слова) < 2:
        try:
            _кв = ask_ai(
                "Тема/вопрос про хадис. Выдай 4-7 ОДИНОЧНЫХ классических арабских СЛОВ "
                "(по одному слову, НЕ фразы), как они звучат в самих хадисах, каждое с новой "
                "строки. Без огласовок, без пояснений.\nТема: " + q,
                "Ты знаток текстов хадисов. Только арабские одиночные слова, по одному на строку.",
                порядок='сначала_бесплатные',
                owner=owner)
            _кв = re.sub(r"\n*⚡ \*Модель:.*$", "", _кв or "", flags=re.S)
            _кв = re.sub(r"[^؀-ۿ\s]", " ", _кв)
            for _с in _кв.split():
                if len(_с) > 2 and _с not in слова:
                    слова.append(_с)
        except Exception:
            pass
    return слова or [q]


async def _rag_query(q, source=None, narrator=None, n=5):
    import aiohttp
    if not RAG_HF_TOKEN:
        raise RuntimeError('HF_TOKEN пуст в окружении бота — Railway не подхватил переменную. Открой Railway → сервис → ⋮ → Redeploy.')
    params = {'q': q or '', 'n': str(n)}
    if source: params['in'] = source
    if narrator: params['by'] = narrator
    headers = {'Authorization': 'Bearer ' + RAG_HF_TOKEN} if RAG_HF_TOKEN else {}
    async with aiohttp.ClientSession() as s:
        async with s.get(RAG_SPACE_URL + '/search', params=params, headers=headers,
                         timeout=aiohttp.ClientTimeout(total=35)) as r:
            ctype = r.headers.get('content-type', '')
            if r.status != 200 or 'json' not in ctype:
                body = (await r.text())[:120]
                hint = ' — нет доступа к Space (проверь HF_TOKEN в Railway Variables)' if r.status in (401, 403, 404) else ''
                raise RuntimeError('HTTP %s%s' % (r.status, hint))
            return await r.json()

async def _hf_keepalive(application):
    """Пинг Space /health каждые 5 мин — чтобы НИКОГДА не засыпал (указ владельца)."""
    import aiohttp
    headers = {'Authorization': 'Bearer ' + RAG_HF_TOKEN} if RAG_HF_TOKEN else {}
    await asyncio.sleep(50)
    while True:
        try:
            async with aiohttp.ClientSession() as s:
                async with s.get(RAG_SPACE_URL + '/health', headers=headers,
                                 timeout=aiohttp.ClientTimeout(total=20)) as r:
                    await r.read()
        except Exception:
            pass
        await asyncio.sleep(300)

def _rag_parse(text):
    """'раг|найди [в <источник>:] <запрос>' → (source, query). Скоуп — после 'в' до ':'."""
    t = text.strip()
    low = t.lower()
    for pref in ('найди', 'раг', 'rag'):
        if low.startswith(pref):
            t = t[len(pref):].strip(); low = t.lower(); break
    source = None
    if low.startswith('в ') and ':' in t:
        head, q = t[2:].split(':', 1)
        source = head.strip(); t = q.strip()
    return source, t.strip()

# коллекции с нумерацией sunnah (ara-* издания) — точный текст+перевод по номеру + рабочая ссылка sunnah.com.
# (Ахмад/мусаннафы и пр. НЕ сюда: у них num=страница Мактабы, не номер хадиса.)
_FAWAZ_COLS = {'bukhari', 'muslim', 'abudawud', 'tirmidhi', 'nasai', 'ibnmajah', 'malik'}
_HRK = '[ً-ْٰـ]*'   # огласовки + тантвин + татвиль (для толерантного поиска)
_LETCLS = {'ا': '[اأإآ]', 'أ': '[اأإآ]', 'إ': '[اأإآ]', 'آ': '[اأإآ]',
           'ه': '[هة]', 'ة': '[هة]', 'ي': '[يى]', 'ى': '[يى]', 'و': '[وؤ]'}
def esc(s):
    """HTML-экранирование для parse_mode=HTML (модульный — RAG-карточки/_hl_arabic зовут его вне функции, где был только вложенный esc → NameError, фикс С46)."""
    return (s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def _hl_arabic(text, terms):
    """Выделить искомые слова в арабском тексте жирным+подчёркиванием (толерантно к огласовкам/хамзам)."""
    if not text:
        return ''
    out = esc(text)
    for t in sorted({(x or '').strip() for x in terms}, key=len, reverse=True):
        if len(t) < 3:
            continue
        chars = [_LETCLS.get(c, re.escape(c)) for c in t if c.strip()]
        if not chars:
            continue
        pat = _HRK.join(chars)
        try:
            out = re.sub('(' + pat + ')', r'<b><u>\1</u></b>', out, count=4)
        except re.error:
            pass
    return out

def _rag_cards(hits, terms, limit=4):
    """Карточки хадисов: целый хадис (выделено искомое) + перевод + источник·№ + рабочая ссылка."""
    cards = []
    for h in hits[:limit]:
        tok = h.get('app_token') or ''
        m = re.match(r'r_(.+)_(\d+)$', tok)
        slug = m.group(1) if m else None
        num = m.group(2) if m else str(h.get('num', ''))
        name = h.get('name', ''); ar = h.get('arabic') or h.get('snippet') or ''; ru = ''
        if slug in _FAWAZ_COLS and num:
            try:
                a2, tr, _lang, _gr = get_hadith(slug, num)
                if a2: ar = a2
                if tr: ru = tr
            except Exception:
                pass
        # язык (владелец: «зачем на английском пишет»): у Муслима и др. готового русского нет → get_hadith
        # отдаёт английский. Если перевод без кириллицы — переводим арабский на русский (кэшируется).
        if ru and not re.search(r'[А-Яа-я]', ru) and ar:
            try:
                _r2 = translate_matn(ar[:1400], owner=True)
                if _r2 and re.search(r'[А-Яа-я]', _r2): ru = _r2
            except Exception:
                pass
        block = ['%s <b>%s</b> · №%s' % (h.get('tier_label', ''), name, num)]
        block.append('<blockquote>%s</blockquote>' % _hl_arabic(ar[:1400], terms))
        if ru:
            block.append('🌍 ' + esc(ru[:600]))
        link = []
        if slug in _FAWAZ_COLS and num:
            link.append('🔗 <a href="https://sunnah.com/%s:%s">sunnah.com</a>' % (slug, num))
        if h.get('app_url'):
            link.append('📱 <a href="%s">в аппе</a>' % h['app_url'])
        if link:
            block.append(' · '.join(link))
        cards.append('\n'.join(block))
    return cards

def _rag_synth(question, hits, owner=False):
    """NotebookLM-стиль: связный ответ по нашим источникам с цитатами [N]. Не выдумывает."""
    if not hits:
        return None
    ctx = []
    for i, h in enumerate(hits, 1):
        ctx.append('[%d] (%s) %s — %s №%s\n%s' % (i, h.get('tier_label', ''), h.get('name', ''),
                   h.get('author', ''), h.get('num', ''), (h.get('arabic') or h.get('snippet') or '')[:900]))
    try:
        ans = ask_ai(
            'Вопрос: %s\n\nОтрывки из НАШИХ первоисточников:\n%s' % (question, '\n\n'.join(ctx)),
            'Ты — ассистент Муслимун. Ответь по-русски КРАТКО и по делу ТОЛЬКО на основе отрывков, ссылайся на источники в виде [N]. '
            'Соблюдай приоритет: Коран > первоисточник хадиса (Бухари/Муслим/сунан) > сборники > тафсир. '
            'Если в отрывках нет ответа — честно скажи. Не выдумывай. Хукм о достоверности сам не выноси.',
            owner=owner)
        ans = re.sub(r"\n*⚡ \*Модель:.*$", "", ans or "", flags=re.S).strip()
        ans = re.sub(r"\n*📊.*$", "", ans, flags=re.S).strip()
        return ans or None
    except Exception:
        return None

def _rag_fmt(data, answer=None):
    res = (data or {}).get('results', [])
    if not res:
        return '🔎 Ничего не нашёл. Попробуй точную арабскую фразу (2-4 слова) или укажи источник: «раг в бухари: <фраза>».'
    src = data.get('in'); by = data.get('by')
    lines = []
    if answer:
        lines += ['🧠 ' + answer, '']
    head = '📚 <b>Источники</b> (найдено: %d' % data.get('count', len(res))
    if src: head += ', в «%s»' % src
    if by: head += ', передатчик «%s»' % by
    head += '):'
    lines.append(head)
    for i, h in enumerate(res, 1):
        lines.append('%s [%d] <b>%s — %s</b> №%s' % (h.get('tier_label', ''), i, h.get('name', ''), h.get('author', ''), h.get('num', '')))
        if not answer:
            sn = (h.get('snippet') or '')[:220]
            if sn: lines.append(sn)
        links = []
        if h.get('maktaba_url'): links.append('📖 <a href="%s">Мактаба</a>' % h['maktaba_url'])
        if h.get('app_url'): links.append('📱 <a href="%s">В аппе</a>' % h['app_url'])
        if links: lines.append(' · '.join(links))
    lines.append('')
    lines.append('🔎 <b>Ответил:</b> RAG (наша база: первоисточники + риджаль)')
    return '\n'.join(lines)[:4090]

# 🔐 ДОСТУП к RAG (указ владельца): пока только владелец; рубильник «всем» + белый/чёрный списки.
# ⚠️ Railway ephemeral — список сбрасывается при редеплое (владелец перевыставляет; владелец доступен ВСЕГДА).
_RAG_ACCESS_FILE = 'rag_access.json'
_RAG_ACCESS = {'all': False, 'white': [], 'black': []}
def _rag_access_load():
    global _RAG_ACCESS
    try:
        _RAG_ACCESS = json.load(open(_RAG_ACCESS_FILE, encoding='utf-8'))
    except Exception:
        _RAG_ACCESS = {'all': False, 'white': [], 'black': []}
    return _RAG_ACCESS
def _rag_access_save():
    try:
        json.dump(_RAG_ACCESS, open(_RAG_ACCESS_FILE, 'w', encoding='utf-8'))
    except Exception:
        pass
def _rag_allowed(uid):
    try:
        uid = int(uid)
    except Exception:
        return False
    if uid == OWNER_ID:
        return True
    a = _rag_access_load()
    if uid in a.get('black', []):
        return False
    if a.get('all'):
        return True
    return uid in a.get('white', [])
# ── #667: «раг» — команда или разговор ПРО раг? ───────────────────────────────────────
# Триггером было ЛЮБОЕ сообщение, начинающееся на «раг ». Живой случай из @jamaat_ru
# (1 077 участников, скрин владельца 26.07.2026): владелец пояснял соседям по чату
# «Раг пока только Бухари сделал я» — это реплика ПРО раг, а не вопрос К нему. Бот принял
# «пока только Бухари сделал я» за вопрос, ответил «🧠 Ищу по смыслу…» и ушёл искать.
# На глазах у всего чата, и вдобавок съел квоту нейронов Cloudflare.
#
# Отличаем дёшево и без потерь: смотрим ТОЛЬКО ПЕРВОЕ слово после «раг». Настоящий вопрос
# начинается с темы или вопросительного слова («раг можно ли пить стоя», «раг бухари
# хариджиты», «раг что говорится о посте») и НИКОГДА — с «я / пока / уже / опять / сделал».
# Именно поэтому проверяется первое слово, а не всё сообщение: в «раг что делать, если я
# забыл намаз» местоимение «я» стоит внутри вопроса и мешать не должно.
_РАГ_НЕ_ВОПРОС = frozenset("""
я мы мне нам меня нас ты тебе тебя вы вам
пока уже ещё еще тоже опять снова вроде кажется наверное походу короче кстати слушай
значит теперь вообще получается похоже блин ладно
сделал сделала сделали сделаю сделай настроил настроила настроили настрой настроим
включил включила включи выключил выключи добавил добавила добавь запустил запусти
починил почини доделал доделаю доделай прикрутил обновил переделал проверил проверю
проверь работает заработал сломался сломан глючит висит молчит тупит отвечает
спасибо супер класс отлично круто плохо хорошо норм ок окей
""".split())
# Отдельно жалобы вида «раг не работает» — «не» само по себе в список не годится
# (может начинать настоящий вопрос), поэтому ловим его только в связке с глаголом.
_РАГ_ЖАЛОБА = re.compile(
    r'^(?:не|нe)\s+(работает|ищет|отвечает|находит|пашет|видит|грузит|включается|запускается|пишет)\b',
    re.I)


def _раг_это_реплика(text):
    """True — сообщение ГОВОРИТ про раг, а не спрашивает у него. Тогда молчим и пропускаем
    сообщение дальше обычным путём: реплика в общем чате ответа бота не требует."""
    try:
        остаток = re.sub(r'^\s*(раг|rag)\b[\s,:—-]*', '', text or '', flags=re.I).strip()
        if not остаток:
            return False                       # голое «раг» — это просьба о помощи, обрабатываем
        if _РАГ_ЖАЛОБА.match(остаток):
            return True
        первое = re.split(r'[\s,.!?;:]+', остаток.lower(), maxsplit=1)[0]
        return первое in _РАГ_НЕ_ВОПРОС
    except Exception:
        return False                           # сомневаешься — веди себя как раньше


def _rag_access_cmd(text):
    """Команды владельца управления доступом RAG. Возвращает текст-ответ или None (не команда)."""
    t = text.lower().strip()
    a = _rag_access_load()
    if t in ('раг доступ', 'rag доступ', 'раг статус', 'раг лимиты'):
        # #673: «установи мне в кабинете разработчика» — вот он, кабинет: одной командой видно
        # и правило (кому открыто, сколько на человека), и живой расход за сегодня поимённо.
        # Раньше команда показывала только списки, а сам ЛИМИТ был зашит в код — увидеть его
        # и тем более поменять без редеплоя Railway было нельзя.
        import time as _t
        _день = _t.strftime('%Y-%m-%d')
        _рас = sorted([(k, int(v.get('сколько') or 0)) for k, v in _RAG_КВОТА.items()
                       if v.get('день') == _день], key=lambda z: -z[1])[:10]
        _н = _rag_нейроны_кратко()
        return ('🔐 Доступ RAG:\n• всем: %s\n• белый список: %s\n• чёрный список: %s\n'
                '• лимит на человека: %d запросов в сутки (общий счёт для чата и приложения)\n'
                '• кошелёк Cloudflare: %s\n'
                '• израсходовали сегодня: %s\n\n'
                'Команды: «раг всем вкл/выкл» · «раг лимит <N>» · «раг белый +<id>» / «раг белый -<id>» · «раг чёрный +<id>» / «раг чёрный -<id>»'
                % ('ВКЛ' if a.get('all') else 'выкл (только владелец+белый)',
                   a.get('white', []) or '—', a.get('black', []) or '—', _rag_лимит(),
                   ('осталось %s из %d нейронов' % (_н['нейронов_осталось'], _CF_СУТКИ))
                   if _н.get('нейронов_осталось') is not None else 'остаток не отдаёт',
                   ', '.join('%s — %d' % (k, n) for k, n in _рас) or 'никто'))
    m = re.match(r'^раг\s+лимит\s+(\d+)$', t)
    if m:
        a['лимит'] = max(1, int(m.group(1)))
        _rag_access_save()
        return '✅ Лимит РАГ: %d запросов в сутки на человека (чат + приложение вместе).' % a['лимит']
    if t.startswith('раг всем'):
        a['all'] = ('вкл' in t or 'on' in t)
        _rag_access_save()
        return '✅ RAG для всех: %s' % ('ВКЛЮЧЁН' if a['all'] else 'выключен (только владелец + белый список)')
    m = re.match(r'раг\s+(бел|чёрн|черн)\w*\s+([+\-]?)(\d+)', t)
    if m:
        lst = 'white' if m.group(1) == 'бел' else 'black'
        rm = m.group(2) == '-'
        uid = int(m.group(3))
        arr = a.setdefault(lst, [])
        if rm:
            if uid in arr: arr.remove(uid)
        else:
            if uid not in arr: arr.append(uid)
        _rag_access_save()
        return '✅ %s список: %s id %d → %s' % ('Белый' if lst == 'white' else 'Чёрный',
                'убрал' if rm else 'добавил', uid, arr or '—')
    return None

# ===== 🛡 ФИЛЬТР РЕКЛАМЫ ОТ НОВИЧКОВ (заявка #178) =====
# Владелец: «настроим с тобой фильтр спама рекламы; для этого надо будет следить за людьми,
# которые зашли, и дня три следить за тем, что они пишут, вычислять и удалять. Механизм предложи».
#
# Три решения, за которые отвечаю отдельно:
#
# ① Трое суток считаем НЕ от входа в чат, а ОТ ПЕРВОГО НАПИСАННОГО СЛОВА. Спамер часто входит
#    и молчит неделю; по дате входа он бы вышел из-под наблюдения, не написав ни строчки.
#
# ② Не одно правило, а СУММА примет с весами. Одно правило либо пропускает половину, либо
#    режет своих. Слабые приметы (слова про заработок, латиница в имени) сами по себе НЕ
#    срабатывают никогда — порог им недостижим в одиночку. В общинном чате «работа», «доход»,
#    «помощь» — обычные слова живого разговора, и ловить по ним значит бить по своим.
#
# ③ БОТ НЕ УДАЛЯЕТ САМ. Удаление необратимо, а цена ошибки — человек, выгнанный из общины ни
#    за что. Владельцу уходит само сообщение, кто (имя·ник·нажимаемый номер), когда зашёл,
#    какие приметы сошлись — и кнопки. Одно касание вместо необратимой самодеятельности.
СПАМ_ОКНО_ДНЕЙ = 3
СПАМ_ПОРОГ = 3                     # сумма весов, при которой зовём владельца
СПАМ_ФАЙЛ = "spam_watch.json"      # {чат:{человек:{первое: ISO, было: n}}}
СПАМ_РЕШЕНИЯ = "spam_resolve.json"  # что владелец решил — по этому и считаем точность
_СПАМ_ЭХО = {}                     # нормализованный текст -> [id новичков], кто это уже писал
_СПАМ_СЛАБЫЕ = re.compile(
    r'заработ|инвест|крипт|ставк|казино|доход\s*от|подработ|трейд|букмекер', re.I)
# 🔴 10.08.2026, обращение #294. Владелец показал пропущенное: «Дам пару заданий оплата 20к
# + в лс». Мой сторож это НЕ ЗАСЁК, и причина ясна: он был выстроен вокруг ССЫЛКИ. А тут
# ссылки нет вовсе — и не нужно: работает связка «деньги» + «пишите в личку». Ссылка
# появится потом, в переписке один на один, где её никто не увидит.
# Значит примета не «ссылка», а СВЯЗКА. Каждая половина по отдельности безобидна: про деньги
# в чате говорят, и в личку зовут по-человечески. Вместе, да от новичка — это объявление.
_СПАМ_ДЕНЬГИ = re.compile(
    r'\bоплат\w*|\bзаплач\w*|\bзарплат\w*|\bгонорар|\d{1,3}\s*[кk]\b|\d{4,}\s*(?:руб|₽|\$)|'
    r'\bставка\s*\d|\bплачу\b|\bдоплат', re.I)
_СПАМ_В_ЛИЧКУ = re.compile(
    r'\bв\s*лс\b|\bв\s*личк\w*|\bпиш\w*\s+(?:в\s+)?(?:лс|личк\w*|директ)|'
    r'\bнапиш\w*\s+(?:мне|в\s+лс|в\s+личк\w*)|\bдирект\b|\bпо\s+всем\s+вопросам\s+пиш', re.I)
_СПАМ_НАБОР = re.compile(
    r'\bищу\s+(?:людей|человек|исполнит|помощник)|\bнабира\w+|\bтребуют\w*\s|\bнужны\s+люди|'
    r'\bдам\s+(?:пару\s+)?задани|\bесть\s+работа|\bудал[её]нн\w*\s+работ', re.I)
_СПАМ_ССЫЛКА = re.compile(r'(https?://|t\.me/|@[A-Za-z]\w{3,}|wa\.me/|\+7\s*9\d{2})')
# 🟢 СВОИ ССЫЛКИ. Поймано собственным самотестом до выкатки: новичок, чьё ПЕРВОЕ сообщение —
# ссылка на наш же канал («вот тут разбор t.me/muslimoonapp»), набирал ровно порог и попадал
# под подозрение. То есть человека, который привёл к нам людей, фильтр встречал как спамера.
# Сюда же — источники, которыми в общинном чате делятся каждый день: они не улика.
_СПАМ_СВОИ = re.compile(
    r'(muslimoonapp|jamaat_ru|germanyalfurqan-eng\.github\.io|sunnah\.(com|one)|dorar\.net|'
    r'shamela\.ws|islamweb\.net|quran\.com|turath\.io|hadith-bot)', re.I)


def _спам_ключ(т):
    """Текст без украшений: спам рассылают одним и тем же, меняя эмодзи и пробелы."""
    return re.sub(r'\W+', ' ', (т or '').lower()).strip()[:200]


_СПАМ_СОСТ = None      # состояние в ПАМЯТИ; ветка data — только долгая полка
_СПАМ_ГРЯЗНО = False
_СПАМ_СЛИТО = 0.0
СПАМ_СЛИВ_СЕК = 300


def _спам_состояние():
    global _СПАМ_СОСТ
    if _СПАМ_СОСТ is None:
        try:
            _СПАМ_СОСТ = _data_get(СПАМ_ФАЙЛ, {}) or {}
        except Exception:
            _СПАМ_СОСТ = {}
    return _СПАМ_СОСТ


def _спам_сохранить(силой=False):
    """Сложить состояние в ветку data — но НЕ на каждое сообщение.

    ⚠️ _data_put — это два запроса к GitHub и КОММИТ. Писать им на каждую реплику в группе
    значило бы тысячи коммитов в сутки и лишнюю секунду задержки у каждого сообщения.
    Держим в памяти, сливаем раз в пять минут. Потеря последних минут при перезапуске не
    страшна: худшее последствие — человек ещё день побудет «новичком».
    """
    global _СПАМ_ГРЯЗНО, _СПАМ_СЛИТО
    if not _СПАМ_ГРЯЗНО:
        return
    if not силой and (time.time() - _СПАМ_СЛИТО) < СПАМ_СЛИВ_СЕК:
        return
    try:
        _data_put(СПАМ_ФАЙЛ, _спам_состояние(), "наблюдение за новичками")
        _СПАМ_ГРЯЗНО = False
        _СПАМ_СЛИТО = time.time()
    except Exception:
        pass


def спам_приметы(update, текст):
    """Какие приметы сошлись и на сколько тянут. Пусто — значит смотреть не на что."""
    global _СПАМ_ГРЯЗНО
    u = getattr(update, 'effective_user', None)
    ч = getattr(update, 'effective_chat', None)
    if not u or not ч or getattr(ч, 'type', '') == 'private' or u.id == OWNER_ID:
        return 0, [], None
    сп = _спам_состояние()
    к, л = str(ч.id), str(u.id)
    зап = (сп.get(к) or {}).get(л)
    сейчас = datetime.now()
    if not зап:
        сп.setdefault(к, {})[л] = {"первое": сейчас.isoformat(timespec='seconds'), "было": 1}
        первое, было = сейчас, 0
    else:
        try:
            первое = datetime.fromisoformat(зап.get("первое"))
        except Exception:
            первое = сейчас
        было = int(зап.get("было") or 0)
        зап["было"] = было + 1
    _СПАМ_ГРЯЗНО = True
    _спам_сохранить()
    if (сейчас - первое).days >= СПАМ_ОКНО_ДНЕЙ:
        return 0, [], первое                      # отнаблюдали, человек свой

    вес, приметы = 0, []
    есть_ссылка = bool(_СПАМ_ССЫЛКА.search(текст or '')) and not _СПАМ_СВОИ.search(текст or '')
    ключ = _спам_ключ(текст)
    # 🔴 самая надёжная примета: ровно этот текст уже писал ДРУГОЙ новичок. Спам всегда
    # рассылают пачкой, и совпадение по двум разным людям почти не бывает случайным.
    if ключ and len(ключ) > 25:
        кто_уже = _СПАМ_ЭХО.setdefault(ключ, [])
        if any(x != u.id for x in кто_уже):
            вес += 4
            приметы.append('этот же текст уже писал другой новичок')
        if u.id not in кто_уже:
            кто_уже.append(u.id)
        if len(_СПАМ_ЭХО) > 3000:
            for _k in list(_СПАМ_ЭХО)[:1000]:
                _СПАМ_ЭХО.pop(_k, None)
    if есть_ссылка and было == 0:
        вес += 3
        приметы.append('ПЕРВОЕ сообщение — и сразу со ссылкой')
    elif есть_ссылка:
        вес += 1
        приметы.append('ссылка от новичка')
    if есть_ссылка and not (u.username or '').strip():
        вес += 1
        приметы.append('ссылка при пустом профиле (нет ника)')
    # слабые: добавляют вес, но в одиночку порога не берут — так и задумано
    if _СПАМ_СЛАБЫЕ.search(текст or ''):
        вес += 1
        приметы.append('слова про заработок (слабая примета)')
    # 🔴 #294: объявление БЕЗ ссылки. Ссылка тут и не нужна — она появится в личке.
    # Считаем связкой: деньги + зов в личку, либо набор людей + зов в личку.
    _деньги = bool(_СПАМ_ДЕНЬГИ.search(текст or ''))
    _личка = bool(_СПАМ_В_ЛИЧКУ.search(текст or ''))
    _набор = bool(_СПАМ_НАБОР.search(текст or ''))
    if _личка and (_деньги or _набор):
        вес += 3 if было == 0 else 2
        приметы.append('предложение работы/денег со звонком в личку'
                       + (' — и это ПЕРВОЕ сообщение' if было == 0 else ''))
    elif _деньги and _набор:
        вес += 2
        приметы.append('набор людей с обещанием оплаты')
    return вес, приметы, первое


МОДЕРИРУЕМЫЕ_ФАЙЛ = 'moderaciya_chaty.json'
# Чаты, которые бот модерирует. Слово владельца, ОБР-819 (18.08.2026):
# «Клод, у нас две группы модерируется тобой — джамаат и Муслим чат».
МОДЕРИРУЕМЫЕ_ПО_УМОЛЧАНИЮ = [-1001925828112,     # JAMAAT MUSLIMIN · t.me/jamaat_ru
                             -1002244531194]     # MUSLIM CHAT · t.me/themuslim_chat


def под_модерацией(chat_id):
    """Наш ли это чат для надзора.

    🔴 ОБР-819. Владелец получил тревогу «похоже на рекламу» из группы «Купол Скалы |
    Обсуждение» и ответил, что модерируются у нас ДВЕ группы — джамаат и Муслим чат.
    Он прав, и вот как вышло: сторож рекламы стоял на КАЖДОМ текстовом сообщении, без
    единой проверки, чей это чат. А бот за неделю оказался в десяти чатах (реестр
    chats_registry.json: Купол Скалы, Islamic World News, TevhidveSunnet, Palestina и
    другие). Значит он молча надзирал за всеми и предлагал кнопки «удалить и забанить»
    в чужих группах — там, где нас об этом не просили.

    Список держим ФАЙЛОМ, а не только в коде: добавить чат должно быть можно словом
    владельца, а не выкладкой бота. Файла нет — работают две группы, которые он назвал.
    """
    try:
        сп = _data_get(МОДЕРИРУЕМЫЕ_ФАЙЛ, None)
        if not isinstance(сп, list) or not сп:
            сп = МОДЕРИРУЕМЫЕ_ПО_УМОЛЧАНИЮ
        return int(chat_id) in {int(x) for x in сп}
    except Exception:
        # Сомнение толкуем в пользу молчания: лишняя тревога в чужом чате хуже
        # пропущенной в своём — своё владелец и так видит.
        return False


async def спам_осмотр(update, context, текст):
    """Осмотреть сообщение новичка и, если приметы сошлись, позвать владельца.

    Ничего не удаляет и не молчит про свои сомнения: показывает, что именно насторожило.
    Любой сбой внутри не должен мешать обычной работе бота — потому всё в try.
    """
    try:
        if not (текст or '').strip():
            return
        # ⛔ ОБР-819: чужой чат — не наш надзор. Проверка стоит ПЕРВОЙ, до всякого счёта примет.
        try:
            _ч0 = update.effective_chat
            if _ч0 is None or not под_модерацией(_ч0.id):
                return
        except Exception:
            return
        # 🔴 ОБРАЩЕНИЕ ВЛАДЕЛЬЦА #395 (11.08.2026): «клод это какая-то дичь. я, Муслимун,
        # владелец, написал — он пишет, что я новичок».
        #
        # Он писал ОТ ИМЕНИ КАНАЛА, и Telegram в таком сообщении подставляет служебного
        # отправителя (@Channel_Bot, id 136817688) — человека там нет вовсе. Наш осмотр видел
        # незнакомый id, не находил его среди вошедших и делал единственный доступный ему
        # вывод: новичок. То есть подозревал владельца в рекламе в его же чате.
        #
        # Анонимного админа (GroupAnonymousBot) мы уже научились узнавать 06.08 — а «пишу как
        # канал» это ДРУГАЯ личина, и её правило не покрывало. Чиним классом: у сообщения от
        # чата или канала выставлено sender_chat. Кто пишет от имени чата — не новичок по
        # определению: новичками бывают люди, а не каналы. Права выдаёт Telegram, и подделать
        # это поле нельзя.
        if getattr(getattr(update, 'message', None), 'sender_chat', None):
            return
        вес, приметы, первое = спам_приметы(update, текст)
        if вес < СПАМ_ПОРОГ or not приметы:
            return
        from telegram import InlineKeyboardButton as _КБ, InlineKeyboardMarkup as _КЛ
        u, ч, м = update.effective_user, update.effective_chat, update.message
        _вх = ''
        try:
            _сп = _data_get('chat_members.json', []) or []
            _наш = [z for z in _сп if str(z.get('id')) == str(u.id) and z.get('что') == 'вошёл']
            if _наш:
                _вх = _наш[-1].get('когда') or ''
        except Exception:
            pass
        # чат:сообщение:человек — три числа, всё нужное для «удалить» и «забанить».
        # В callback_data Telegram даёт 64 байта; три числа с двоеточиями укладываются с запасом.
        _пм = '%d:%d:%d' % (ч.id, м.message_id, u.id)
        # 🔴 #472: «помоги в джамаат муслимин и муслим чат в этом вопросе». Тревога уходила
        # ТОЛЬКО владельцу — значит нажать «удалить и забанить» мог он один, и ночью спам
        # висел до утра. Ровно на это была старая жалоба про кнопки бана (#614: «две кнопки,
        # которые могут нажимать админы»).
        # Шлём вторым адресом в рабочий журнал, где сидят админы. ⚠️ В САМ ЧАТ не шлём
        # намеренно: подозрение в рекламе — не то, что вывешивают перед всеми. Ошибиться в
        # человеке при всех дороже, чем показать его админам.
        _кому = [OWNER_ID]
        try:
            if LOG_CHAT_ID and LOG_CHAT_ID != OWNER_ID:
                _кому.append(LOG_CHAT_ID)
        except Exception:
            pass
        _тело = (
            ('🛡 <b>Похоже на рекламу от новичка</b> (вес %d)' % вес) + chr(10) + chr(10) +
            '<b>Кто:</b> %s' % кто_с_id(u, вид='html') + chr(10) +
            ('<b>Зашёл:</b> %s' % html.escape(_вх) + chr(10) if _вх else '') +
            ('<b>Первое слово:</b> %s' % (первое.strftime('%d.%m.%Y, %H:%M') if первое else '—')) + chr(10) +
            '<b>Где:</b> %s' % html.escape((ч.title or str(ч.id))[:50]) + chr(10) + chr(10) +
            '<b>Сошлось:</b>' + chr(10) + chr(10).join('· ' + html.escape(п) for п in приметы) + chr(10) + chr(10) +
            '<blockquote>%s</blockquote>' % html.escape((текст or '')[:600]))
        _кнопки = _КЛ([[_КБ('🗑 удалить', callback_data='spam:del:' + _пм),
                        _КБ('🚫 удалить и забанить', callback_data='spam:ban:' + _пм)],
                       [_КБ('✅ свой, не трогать', callback_data='spam:ok:' + _пм)]])
        # ⚠️ Каждый адрес — в СВОЁМ try. Общий на двоих означал бы, что сбой на первом
        # (владелец закрыл личку, Telegram икнул) молча отменяет второй, и админы не узнают
        # о спаме вовсе. Тревога, которая не дошла до половины адресатов, — это полтревоги.
        for _адрес in _кому:
            try:
                await context.bot.send_message(
                    _адрес, _тело, parse_mode='HTML',
                    disable_web_page_preview=True, reply_markup=_кнопки)
            except Exception:
                pass
    except Exception:
        pass


async def on_spam(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Решение владельца по подозрению: удалить / удалить и забанить / свой.

    Каждое решение записывается — по ним и считается честная точность фильтра. Без этого
    сторож незаметно сползает в бесполезность, и заметить это будет нечем.
    """
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    try:
        if q.from_user.id != OWNER_ID:
            return
        _, что, хвост = q.data.split(':', 2)
        чат, смс, кто = [int(x) for x in хвост.split(':')]
        итог = []
        if что in ('del', 'ban'):
            try:
                await context.bot.delete_message(chat_id=чат, message_id=смс)
                итог.append('сообщение удалено')
            except Exception as e:
                итог.append('удалить не вышло: %s' % str(e)[:60])
        if что == 'ban':
            try:
                await context.bot.ban_chat_member(chat_id=чат, user_id=кто)
                итог.append('человек забанен')
            except Exception as e:
                итог.append('забанить не вышло: %s' % str(e)[:60])
        if что == 'ok':
            итог.append('оставлено — свой')
        try:
            def _зап(o):
                сп = o if isinstance(o, list) else []
                сп.append({'d': _now_msk(), 'чат': чат, 'смс': смс, 'кто': кто,
                           'решение': {'del': 'спам', 'ban': 'спам+бан', 'ok': 'свой'}[что]})
                return сп[-2000:]
            _data_atomic_mutate(СПАМ_РЕШЕНИЯ, _зап, 'решение по подозрению: %s' % что)
        except Exception:
            pass
        try:
            await q.edit_message_reply_markup(reply_markup=None)
            await q.message.reply_text('✅ ' + '; '.join(итог))
        except Exception:
            pass
    except Exception:
        pass


def _мсообщ(update):
    """Куда отвечать: у поста канала update.message пуст, а отвечать надо туда же, откуда
    пришло. Без этого команда сработала бы молча — сделала бы дело и не сказала о нём."""
    return update.message or update.channel_post


def _расст_имён(a, b):
    """Сколько правок между словами. Больше двух не считаем — дальше не нужно."""
    if abs(len(a) - len(b)) > 2:
        return 3
    пред = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        тек = [i]
        for j, cb in enumerate(b, 1):
            тек.append(min(пред[j] + 1, тек[j - 1] + 1, пред[j - 1] + (ca != cb)))
        пред = тек
    return пред[-1]


_ОКОНЧАНИЯ_РУ = ('ами', 'ями', 'ого', 'ему', 'ом', 'ой', 'ах', 'ям', 'ам',
                 'ы', 'и', 'а', 'у', 'е', 'ю', 'я')


def _без_окончания(с):
    """«орниза» → «орниз». Режем только когда основа остаётся длиной хотя бы в четыре буквы."""
    for о in _ОКОНЧАНИЯ_РУ:
        if len(с) - len(о) >= 4 and с.endswith(о):
            return с[:-len(о)]
    return с


_КИРИЛЛИЦА_В_ЛАТИНИЦУ = {
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ё': 'e', 'ж': 'zh',
    'з': 'z', 'и': 'i', 'й': 'y', 'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n', 'о': 'o',
    'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f', 'х': 'h', 'ц': 'c',
    'ч': 'ch', 'ш': 'sh', 'щ': 'sch', 'ъ': '', 'ы': 'y', 'ь': '', 'э': 'e',
    'ю': 'yu', 'я': 'ya'}


def _на_латиницу(с):
    """«гемма» → «gemma», «линг» → «ling». Только для сверки имён, наружу не показывается."""
    return ''.join(_КИРИЛЛИЦА_В_ЛАТИНИЦУ.get(ч, ч) for ч in (с or ''))


def _профиль_найти(имя, мест, _уже_латиницей=False):
    """Как назвали → какой профиль. Возвращает (имя_профиля | None, кандидаты).

    🔴 20.08.2026, обращение владельца #1020 («ДЫРА В УМЕНИИ»). Он написал «переключись на
    ornith 262» и получил «профиля в реестре нет». Профиль был — `ornith15-q4-262k`. Сверка
    шла ТОЧЬ-В-ТОЧЬ, и не совпало ни знаком.

    ⚠️ А копнув, нашёл больше: поля `другие_имена` в bot.py НЕ БЫЛО НИ РАЗУ. Реестр честно
    перечисляет около шестидесяти вторых имён — «орниз», «ling-262k», «35b», — и ни одно из
    них не читалось никогда. Мёртвый груз, который выглядел как работающая возможность:
    тот же класс, что «приёмника у строки не было ни одного».

    ПОЧЕМУ ЭТО НЕ ВОЗВРАЩАЕТ СТАРУЮ БЕДУ. Рядом стоит мой же зарок: «похожее не подставляем —
    владелец выбрал одного Линга, а говорил со старым и не заметил». Зарок верен, но был
    перегнут: он отказывал и там, где двусмысленности нет вовсе. Развязка простая — угадывать
    можно только тогда, когда подходит РОВНО ОДИН, и полное имя всегда произносится вслух.
    Подошло несколько — спрашиваем, какой; тихой подмены не возникает ни в одной ветке.
    """
    н = ' '.join((имя or '').strip().lower().split())
    if not н:
        return None, []
    for к in мест:                                   # ① полное имя профиля
        if к.lower() == н:
            return к, []
    # ② объявленное второе имя. Собираем ВСЕХ, кто его на себя записал, а не первого по
    # порядку: в реестре есть имена, объявленные дважды («35b» стоит и у 262k, и у 64k).
    # Первый попавшийся тут — это и есть тихая подмена, от которой мы бережёмся.
    _по_имени = [к for к, з in мест.items()
                 if any(' '.join(str(а).lower().split()) == н
                        for а in (з.get('другие_имена') or []))]
    if len(_по_имени) == 1:
        return _по_имени[0], []
    if _по_имени:
        return None, sorted(_по_имени)
    слова = [с for с in re.split(r'[\s,]+', н) if с]  # ③ по словам: нужны ВСЕ названные
    подошли = []
    for к, з in мест.items():
        поле = (к + ' ' + ' '.join(str(а) for а in (з.get('другие_имена') or []))).lower()
        if all(с in поле for с in слова):
            подошли.append(к)
    if len(подошли) == 1:
        return подошли[0], []
    if подошли:
        return None, sorted(подошли)

    # ④ ЖИВАЯ РЕЧЬ: падеж и опечатка. 🔴 20.08.2026, обращение владельца #1030: «Ты как
    # сообразил, что речь про орниз? Вот так же и он должен понять, а не тупить». Он прав.
    # Ступени ①–③ сверяют слово как машина: «орниз» они знают, а «орнизА» — уже нет, потому
    # что окончание сделало слово длиннее; «ониза» не узнаётся из-за одной пропущенной буквы.
    # Человек так не говорит: он склоняет и промахивается по клавише.
    #
    # ⚠️ ДВА ЗАСЛОНА, без которых эта ступень опасна.
    # ① Она включается ТОЛЬКО когда ①–③ не нашли НИЧЕГО. Иначе она размывает уже точный ответ:
    #    в пробе «орниз» стал двусмысленным, а «muse» цеплялся за ling-ad — то есть догадка
    #    портила там, где всё уже работало.
    # ② Сравниваем ЦЕЛУЮ сказанную строку с ЦЕЛЫМ вторым именем, а не по словам. У профиля
    #    64k второе имя «орниз 64», и его кусок «орниз» цеплял бы всё подряд — двусмысленность
    #    возникала бы на ровном месте.
    # Правило прежнее и главное остаётся: берём, только если подошёл РОВНО ОДИН, и полное имя
    # произносится вслух. Подошло несколько — спрашиваем, какой.
    if len(н) < 4:
        return None, []
    осн = _без_окончания(н)
    похожие = []
    for к, з in мест.items():
        for а in [к.lower()] + [str(а).lower() for а in (з.get('другие_имена') or [])]:
            if len(а) < 4:
                continue
            хвост = len(н) - len(а)
            if (н.startswith(а) and 0 < хвост <= 3) or осн == а \
               or _расст_имён(осн, а) <= 1 or _расст_имён(н, а) <= 1:
                похожие.append(к)
                break
    if len(похожие) == 1:
        return похожие[0], []
    if похожие:
        return None, sorted(похожие)

    # ⑤ РУССКОЕ ИМЯ ЛАТИНСКОЙ МОДЕЛИ. 🔴 20.08.2026, найдено проверкой злых случаев: «гемма»,
    # «линг», «муза» не находились НИЧЕМ. Профили названы латиницей (gemma-4-e4b, ling-ad-1m,
    # muse-glimmer-30b), а владелец пишет по-русски. «Орниз» работал только потому, что это
    # имя кто-то однажды вписал в реестр руками, — то есть держалось на людской памяти, а не
    # на устройстве: заведут завтра новую модель, и она снова будет «не найдена».
    # Реестр строится из чужого файла (01_router.py) и переписывается целиком — дописывать
    # русские имена туда бесполезно, их сотрёт следующей сборкой. Поэтому чиним у себя.
    # Тот же заслон, что у ступени ④: включаемся, лишь когда НЕ НАШЛОСЬ НИЧЕГО, и берём
    # только при РОВНО одном совпадении.
    if not _уже_латиницей:
        _лат = _на_латиницу(н)
        if _лат != н:
            return _профиль_найти(_лат, мест, _уже_латиницей=True)
    return None, []


def _профиль_понять(фраза, мест):
    """Четвёртый заход: спросить саму модель, что владелец имел в виду.

    Зовётся ТОЛЬКО когда сверка строк не нашла ничего. Модель выбирает из списка, который мы
    ей дали, и обязана вернуть ровно одно имя оттуда либо слово НЕТ. Ответ не из списка
    отбрасывается — угадывание за пределами реестра нам не нужно ни при каких условиях.

    Зачем вообще: владелец пишет живыми словами и с опечатками («переключись на ониза»), а
    сверка строк требует попадания буква в букву. Понимать смысл — работа модели, а не
    регулярного выражения.
    """
    имена = sorted(мест)
    if not имена or not (фраза or '').strip():
        return None
    список = '\n'.join('- ' + и for и in имена)
    вопрос = ('Хозяин компьютера просит переключить помощника на другую модель. Вот список '
              'доступных имён:\n' + список + '\n\nОн сказал: "' + фраза.strip()[:200] + '"\n\n'
              'Какое имя из списка он имел в виду? Учитывай опечатки, падежи и сокращения. '
              'Ответь РОВНО одним именем из списка и ничем больше. Если непонятно или '
              'подходит несколько — ответь одним словом: НЕТ')
    try:
        # только_облако: спрашивать о переключении ту модель, с которой уходим, — нелепо и
        # ненадёжно (см. разбор в ask_opencode). Этот вопрос обязан быть быстрым и живым.
        ответ = (ask_opencode(вопрос, 'Ты отвечаешь одним словом из данного списка.',
                              max_tokens=60, только_облако=True) or '').strip()
    except Exception:
        return None
    ответ = ответ.strip().strip('`"\'.,;:').split()[-1] if ответ else ''
    # 🔴 Заслон: принимаем ТОЛЬКО имя, которое есть в реестре. Без этого модель однажды
    # предложит несуществующее, и мы вернёмся к «сказали переключился, не переключившись».
    return ответ if ответ in мест else None


async def _модель_команда(update, имя):
    """Выбор модели помощника. Только владелец — проверка стоит у вызова (is_owner: две его
    лички и канал Муслимун).

    Вынесено отдельной функцией, потому что вызывается ПЕРВОЙ строкой обработчика: приказ
    владельца не должен ждать своей очереди среди трёх тысяч строк — на этом он четырежды
    писал команду впустую.
    """
    _р = _реестр_моделей()
    _мест = _р.get('местные') or {}
    _сейчас = _выбор_прочитать()
    if not имя:
        _стр = ['🎛 <b>Модель помощника</b>', '',
                'Сейчас: <b>%s</b>' % (_сейчас or (OPENCODE_MODEL + ' · облако')), '',
                '<b>Местные</b> (через твой ноутбук):']
        for _и in sorted(_мест):
            _стр.append('  • <code>%s</code>%s' % (_и, '  ← по умолчанию'
                                                   if _и == _р.get('по_умолчанию_местная') else ''))
        # Облако тоже перечисляем поимённо. Пока здесь стояла одна строка про
        # OPENCODE_MODEL, владелец не мог узнать, что в подписке есть gpt-5.6-luna, —
        # и просил её словами, а получал «готово» на прежней (jamaat_ru/734054).
        _обл_сп = []
        try:
            _обл_сп = _облачные_модели() or []
        except Exception:
            _обл_сп = []
        _стр += ['', '<b>Облако</b> (подписка OpenCode, умолчание <code>%s</code>):' % OPENCODE_MODEL]
        if _обл_сп:
            for _ом in _обл_сп:
                _стр.append('  • <code>%s</code>%s' % (_ом, '  ← сейчас' if _ом == _сейчас else ''))
        else:
            _стр.append('  • список не отдался — остаётся <code>%s</code>' % OPENCODE_MODEL)
        _стр += ['', 'Переключить: «модель gpt-5.6-luna» или «модель ling-q3-262k» · '
                     'вернуть умолчание: «модель облако»']
        await _мсообщ(update).reply_text('\n'.join(_стр)[:4000], parse_mode='HTML')
        return
    if имя.lower() in ('облако', 'обл', 'cloud'):
        _выбор_записать('')
        await _мсообщ(update).reply_text('☁️ Готово: отвечаю через облако (<b>%s</b>).'
                                        % OPENCODE_MODEL, parse_mode='HTML')
        return
    # Имя ищем СРАЗУ в двух реестрах — местном и облачном. Раньше искали только в
    # местном, и облачное имя обречённо доходило до «профиля в реестре нет», хотя модель
    # у провайдера есть и подписка за неё уплачена.
    _обл_сп = []
    try:
        _обл_сп = _облачные_модели() or []
    except Exception:
        _обл_сп = []
    _все = dict(_мест)
    for _ом in _обл_сп:
        _все.setdefault(_ом, {})
    if имя not in _все:
        _точное, _канд = _профиль_найти(имя, _все)
        if _точное:
            # Нашли ровно один — переключаем, но имя произносим ПОЛНОСТЬЮ и вслух: именно
            # его отсутствие когда-то и стоило владельцу разговора не с той моделью.
            имя = _точное
        elif _канд:
            await _мсообщ(update).reply_text(
                '🤔 «<code>%s</code>» подходит сразу нескольким — какой из них?\n%s\n\n'
                'Скажи полное имя, и переключу.'
                % (имя[:60], '\n'.join('  • <code>%s</code>' % к for к in _канд[:8])),
                parse_mode='HTML')
            return
        else:
            # ④ сверка строк не справилась — спрашиваем модель, что он имел в виду.
            # Владелец: «он нейросеть, он должен понять, а не ботом быть».
            _понято = await asyncio.get_event_loop().run_in_executor(
                None, lambda: _профиль_понять(имя, _все))
            if _понято:
                await _мсообщ(update).reply_text(
                    '🧠 Понял тебя как <b>%s</b> — проверяю её.' % _понято, parse_mode='HTML')
                имя = _понято
            else:
                await _мсообщ(update).reply_text(
                    '🤷 Профиля <code>%s</code> в реестре нет, и понять иначе не вышло. '
                    'Скажи «модель» — покажу список.' % имя[:60], parse_mode='HTML')
                return
    if имя in _обл_сп and имя not in _мест:
        # Облачную модель незачем гонять через ноутбук — спрашиваем её саму. Но спрашиваем
        # ОБЯЗАТЕЛЬНО: «переключился» без пробы и было тем самым словом на веру, за которое
        # владелец сказал «эту ересь мне не говори».
        await _мсообщ(update).reply_text(
            '⏳ Проверяю <b>%s</b> в облаке — спрашиваю её саму.\n'
            'Пока отвечает прежняя: <b>%s</b>.'
            % (имя, _сейчас or (OPENCODE_MODEL + ' · облако')), parse_mode='HTML')
        _ок, _что = await asyncio.get_event_loop().run_in_executor(
            None, lambda: _проба_облачной(имя))
        if not _ок:
            await _мсообщ(update).reply_text(
                '🔴 <b>%s</b> не отозвалась (%s). Остаюсь на прежней: <b>%s</b>.\n'
                'Ничего не переключил — чтобы ты не думал, что говоришь с ней.'
                % (имя, _что, _сейчас or OPENCODE_MODEL), parse_mode='HTML')
            return
        _выбор_записать(имя)
        await _мсообщ(update).reply_text(
            '☁️ Переключился на <b>%s</b> — это облако OpenCode, твоя подписка.\n'
            'Проверка живьём: «%s»' % (имя, _что), parse_mode='HTML')
        return
    await _мсообщ(update).reply_text(
        '⏳ Проверяю <b>%s</b> — задание уходит на твой ноутбук, это до полуминуты.\n'
        'Пока отвечает прежняя: <b>%s</b>.' % (имя, _сейчас or 'облако'), parse_mode='HTML')
    _жива, _сказала, _кто = await asyncio.get_event_loop().run_in_executor(
        None, lambda: dsoc_проверить_модель(имя, 120))
    if not _жива:
        # 🔴 «Не отозвалась» чаще значит НЕ ПОДНЯТА, а не «сломана»: из тридцати профилей
        # на карте живёт один. Просим ноутбук поднять её и проверяем снова. Раньше здесь
        # был честный, но бесполезный отказ: возможность есть на бумаге и нет в деле.
        await _мсообщ(update).reply_text(
            '⏳ <b>%s</b> не отозвалась (%s) — похоже, она просто не поднята.\n'
            'Прошу ноутбук поднять её. Это до нескольких минут; пока отвечает <b>%s</b>.'
            % (имя, _сказала, _сейчас or 'облако'), parse_mode='HTML')
        _вышло, _что = await asyncio.get_event_loop().run_in_executor(
            None, lambda: dsoc_попросить_поднять(имя))
        if _вышло:
            _жива, _сказала, _кто = await asyncio.get_event_loop().run_in_executor(
                None, lambda: dsoc_проверить_модель(имя, 120))
        if not _жива:
            # Молчаливого отката не бывает: владелец должен знать, с кем говорит.
            await _мсообщ(update).reply_text(
                '🔴 <b>%s</b> так и не отозвалась (%s). Остаюсь на прежней: <b>%s</b>.\n'
                'Ничего не переключил — чтобы ты не думал, что говоришь с ней.'
                % (имя, _что if not _вышло else _сказала, _сейчас or 'облако'),
                parse_mode='HTML')
            return
    _выбор_записать(имя)
    # Правду о том, кто ответил, говорит ответ, а не настройка.
    # 🔴 20.08.2026, поймано на живом посте в джамаате: модель представляется ПОЛНЫМ ПУТЁМ
    # к файлу на ноутбуке владельца, и этот путь ушёл в общий чат, где сидят люди (З-77:
    # в канал — только польза читателю, никаких путей и кухни). Оставляем имя файла без
    # дороги к нему: для «та ли модель ответила» имени достаточно.
    _кто_имя = (_кто or '').replace(chr(92), '/').rsplit('/', 1)[-1]
    _подп = ('\n🏷 представилась: <code>%s</code>' % _кто_имя[:70]) if _кто_имя else ''
    _разн = ('\n⚠️ просил <code>%s</code>, ответила <code>%s</code> — проверь'
             % (имя, _кто_имя[:50])) if (_кто and имя.split('-')[0] not in _кто.lower()) else ''
    await _мсообщ(update).reply_text(
        '✅ Переключился на <b>%s</b>.\nПроверка: «%s»%s%s'
        % (имя, _сказала[:120], _подп, _разн), parse_mode='HTML')



# ═══════════════════════════════════════════════════════════════════════════════════════════
# 🎬 СКАЧАТЬ ВИДЕО ПО ССЫЛКЕ И ОТДАТЬ С ОПИСАНИЕМ (владелец просил это 32 раза)
#
# Счёт не для красного словца: 23.08.2026 я пересчитал очередь его сообщений — «научи его /
# обеспечь, чтобы умел» встречается 32 раза, начиная с #258 (09.08). Последний раз, #1345,
# он прислал ссылку на ответ помощника в общем чате: «🤐 Ответа не вышло. Модель вернула
# пустоту». И спросил, сколько раз он это говорил.
#
# ПОЧЕМУ РАНЬШЕ НЕ РАБОТАЛО, честно. Никакого умения не было вовсе. Просьба «скачай видео»
# уходила ЯЗЫКОВОЙ МОДЕЛИ — а у модели нет ни сети, ни диска. Она возвращала пустоту, заслон
# на выходе честно писал «сбой на моей стороне», и со стороны это выглядело как поломка,
# хотя ломаться было нечему: инструмента не существовало.
#
# Видеомост рядом (`видеомост`) — НЕ ЭТО. Он перекладывает ссылку в @muslimlive, ждёт чужую
# качалку и возвращает её видео. Он выключен по умолчанию, зависит от третьей стороны и не
# знает x.com вовсе — а владелец присылал именно x.com. Здесь — своими руками, без посредника.
#
# ⚠️ ПОЧЕМУ ЭТО РАБОТАЕТ НА СЕРВЕРЕ, А НА НОУТБУКЕ НЕТ. С домашней сети прямой ход к x.com
# закрыт (проверено 22.08: TLS в таймаут, лечится только SOCKS-туннелем). У Railway дорога
# своя, и ей туннель не нужен. Поэтому умение живёт здесь, а не в местном скрипте.
_ВИДЕО_ССЫЛКА = re.compile(
    r'https?://(?:www\.|m\.|mobile\.)?(?:x\.com|twitter\.com|fxtwitter\.com|vxtwitter\.com|'
    r'youtube\.com|youtu\.be|youtube-nocookie\.com|instagram\.com|instagr\.am|'
    r'tiktok\.com|vm\.tiktok\.com|vt\.tiktok\.com|reddit\.com|v\.redd\.it|'
    r'vk\.com|vk\.ru|rutube\.ru|dzen\.ru|coub\.com|facebook\.com|fb\.watch)/\S+', re.I)
# Намерение: человек говорит по-человечески, а не заклинанием. «скачай», «скинь», «качни»,
# «достань», «сохрани», «залей» — всё это одно и то же. Ловим корни, а не точные слова
# (грабли #497: имя «ботяра» искали только в начале строки, и половина просьб не доходила).
_ВИДЕО_ПРОСЬБА = re.compile(
    r'скач|скин|качн|доста|сохран|зале[йж]|загруз|вытащ|вынь|принеси|дай\s+видео|'
    r'сюда\s+видео|видео\s+сюда', re.I)
_ВИДЕО_ПОТОЛОК = 45 * 1024 * 1024      # Telegram принимает от бота 50 МБ; берём с запасом


# 🎬 Кто из двух путей отработал ссылку. Видеомост (группа обработчиков 11) разбирает
# сообщения НЕЗАВИСИМО от основного обработчика, а тот с 23.08.2026 сам качает по ссылке.
# Без этой отметки на одну ссылку сработали бы оба: видео пришло бы дважды, и в публичный
# канал ушёл бы лишний перевалочный пост.
# Ставим отметку ТОЛЬКО при удачной отдаче — не «мы попробовали», а «человек получил видео».
# Иначе при неудаче запасной путь тоже промолчал бы, и вышла бы та самая тишина, ради
# которой всё это и чинится.
_НАШЕ_ВИДЕО_ОТДАНО = {}
_НАШЕ_ВИДЕО_СРОК = 900          # 15 минут: дольше держать незачем, видеомост решает сразу


def _отметить_наше_видео(чат, смс):
    try:
        сейчас = time.time()
        for к in [к for к, в in _НАШЕ_ВИДЕО_ОТДАНО.items()
                  if сейчас - float(в or 0) > _НАШЕ_ВИДЕО_СРОК]:
            _НАШЕ_ВИДЕО_ОТДАНО.pop(к, None)
        _НАШЕ_ВИДЕО_ОТДАНО[(int(чат or 0), int(смс or 0))] = сейчас
    except Exception:
        pass


def _наше_видео_уже_отдано(чат, смс):
    try:
        когда = _НАШЕ_ВИДЕО_ОТДАНО.get((int(чат or 0), int(смс or 0)))
        return bool(когда and (time.time() - float(когда)) <= _НАШЕ_ВИДЕО_СРОК)
    except Exception:
        return False


def _похоже_на_видео(путь):
    """Правда ли это видеофайл — по подписи в первых байтах, а не по расширению.

    Расширение подделывается само собой: качалка не смогла склеить дорожки и оставила
    обрывок с именем .mp4. Подпись контейнера не подделывается:
      mp4/mov — на 4-м байте слово ftyp;
      webm/mkv — файл начинается с 1A 45 DF A3.
    Обрывки .part отсекаем по имени: их качалка помечает сама.
    """
    try:
        if путь.endswith(('.part', '.ytdl', '.description', '.jpg', '.jpeg', '.png', '.webp')):
            return False
        if os.path.getsize(путь) < 10240:      # меньше 10 КБ — это не ролик
            return False
        with open(путь, 'rb') as ф:
            голова = ф.read(12)
        if len(голова) < 12:
            return False
        if голова[4:8] == b'ftyp':
            return True                        # mp4, mov, m4v
        if голова[:4] == b'\x1a\x45\xdf\xa3':
            return True                        # webm, mkv
        return False
    except Exception:
        return False

def _скачать_видео_по_ссылке(url, потолок=_ВИДЕО_ПОТОЛОК):
    """Скачать видео и вернуть (путь, описание, беда). Синхронно — звать из потока."""
    try:
        import yt_dlp
    except Exception as e:
        return None, '', ('yt-dlp не установлен в контейнере (%s). Добавь его в '
                          'requirements.txt и передеплой.' % str(e)[:60])
    import tempfile
    import glob as _glob
    папка = tempfile.mkdtemp(prefix='vid_')
    # Формат выбираем СРАЗУ с потолком по весу: иначе скачаем 200 МБ и упрёмся в отказ
    # Telegram уже ПОСЛЕ траты трафика и времени.
    # 🔴 #1460 (владелец): «видео странное, не воспроизводит у меня».
    # Прежний формат брал «любое до 720p», а merge_output_format:mp4 меняет только
    # КОНТЕЙНЕР, не кодек: VP9 или AV1 внутри mp4 останутся VP9 и AV1. Телеграм такое
    # показывает, но проигрывают не все клиенты — отсюда «странное видео».
    # Ставим H.264 + AAC ПЕРВЫМ: он играет везде. Прежние правила оставляем запасом —
    # если H.264 у ролика нет вовсе, лучше отдать хоть что-то, чем ничего.
    # 🔴 ПОРЯДОК ЗДЕСЬ И ЕСТЬ СМЫСЛ. Сперва я поставил H.264 выше потолка по весу — и
    # проверка на потоках показала: «H.264 на 200 МБ» побеждал «VP9 на 4 МБ». То есть мы
    # скачали бы 200 МБ, чтобы упереться в отказ Телеграма (предел 50 МБ от бота). Ровно
    # то, от чего предостерегал комментарий, стоявший тут до меня. Я его прочитал — и всё
    # равно сделал, потому что думал про кодек.
    # ПОТОЛОК ГЛАВНЕЕ КОДЕКА: неиграющее видео — досада, а видео, не дошедшее вовсе после
    # траты трафика, — хуже. Внутри каждого яруса H.264 остаётся первым.
    #   ярус 1 (под потолком): H.264+AAC → H.264 склеенный → любой
    #   ярус 2 (без потолка):  H.264 → любой
    формат = ('bv*[vcodec^=avc1][filesize<%(п)d][height<=720]+ba[acodec^=mp4a]/'
              'b[vcodec^=avc1][filesize<%(п)d][height<=720]/'
              'bv*[filesize<%(п)d][height<=720]+ba/b[filesize<%(п)d]/'
              'bv*[vcodec^=avc1][height<=720]+ba/b[vcodec^=avc1][height<=720]/'
              'bv*[height<=720]+ba/b[height<=720]/b') % {'п': потолок}
    настройки = {
        'outtmpl': os.path.join(папка, '%(id)s.%(ext)s'),
        'format': формат,
        'quiet': True, 'no_warnings': True, 'noprogress': True,
        'noplaylist': True,                 # ссылка на ролик из плейлиста — берём ролик
        'socket_timeout': 30,
        'retries': 2,
        'merge_output_format': 'mp4',
    }
    try:
        with yt_dlp.YoutubeDL(настройки) as ю:
            св = ю.extract_info(url, download=True)
        if св.get('entries'):
            св = св['entries'][0]
        файлы = [f for f in _glob.glob(os.path.join(папка, '*')) if os.path.isfile(f)]
        if not файлы:
            return None, '', 'скачалось пусто — видео по ссылке не нашлось'
        # 🔴 #1460. Раньше брали просто САМЫЙ БОЛЬШОЙ файл и отправляли его как видео,
        # ничем не проверив. А после неудачной или частичной закачки в папке остаются
        # обложка .jpg, обрывок .part, отдельная звуковая дорожка .m4a. Инстаграм как раз
        # таков: описание отдаёт, видео придерживает. Тогда самым большим оказывалась
        # обложка — и уходила владельцу «видеофайлом», который не играет.
        # Проверяем ПОДПИСЬ В БАЙТАХ, а не расширение: расширение подделывается само,
        # когда качалка не смогла склеить. Четыре байта прочитать дешевле, чем отправить
        # человеку непонятно что.
        файлы = [f for f in файлы if _похоже_на_видео(f)]
        if not файлы:
            return None, '', ('скачалось, но это не видео — сайт отдал только обложку или '
                              'обрывок. Обычно так бывает, когда пост закрытый или сайт '
                              'просит вход.')
        путь = max(файлы, key=os.path.getsize)
        вес = os.path.getsize(путь)
        if вес > 50 * 1024 * 1024:
            return None, '', ('видео весит %.1f МБ — Telegram больше 50 МБ от бота не берёт'
                              % (вес / 1048576.0))
        # Описание: у X это текст поста, у YouTube — описание ролика. Берём что есть.
        описание = (св.get('description') or св.get('title') or '').strip()
        return путь, описание, ''
    except Exception as e:
        беда = str(e)
        # Переводим самые частые отказы на человеческий: «ERROR: [twitter] …» ничего не говорит.
        if 'Unsupported URL' in беда:
            беда = 'этот сайт качалка не поддерживает'
        elif 'Private' in беда or 'login' in беда.lower():
            беда = 'пост закрытый — нужен вход в аккаунт, которого у меня нет'
        elif 'Video unavailable' in беда or '404' in беда:
            беда = 'видео по ссылке больше нет'
        elif 'timed out' in беда.lower() or 'timeout' in беда.lower():
            беда = 'сайт не ответил вовремя'
        else:
            беда = беда[:180]
        return None, '', беда


# 🔴 23.08.2026, #1379, дословно: «видео переводить лишний раз не надо. Я когда скажу
# перевести или субтитры, тогда только. Ссылку когда кидаю — тогда качай с описанием, а если
# "переведи", то и перевод».
# Днём (#1348) он же просил озвучку «сразу», и я поставил её в умолчание — прочитал «сразу»
# как «всегда», а он имел в виду «не прося второй раз». Вечером поправил. Последнее слово его.
# Ищем ТОЛЬКО в том сообщении, где ссылка: гадать по прошлым значит однажды озвучить то,
# чего не просили, и потратить платное распознавание впустую.
# ⚠️ С 25.08.2026 (ОБР-1524) НЕ ИСПОЛЬЗУЕТСЯ: текст описания переводится всегда, а не
# по просьбе. Оставлен намеренно — им ловится просьба о переводе ВИДЕО, которое, по
# слову владельца, осталось «по заявке». Удалять до того, как разберусь с дубляжом,
# значит потерять готовый признак и писать его заново.
_ПРОСЯТ_ПЕРЕВОД = re.compile(r'перевед|перевод|по-русски|на русск', re.I)
_ПРОСЯТ_ОЗВУЧКУ = re.compile(r'озвуч|дубляж|дублируй|переозвуч|субтитр', re.I)


def _похоже_на_русский(текст):
    """Доля кириллицы среди букв. Считаем по БУКВАМ, а не по всем знакам: в описании поста
    полно ссылок, значков и решёток, и они одинаково чужды обоим языкам."""
    # Сперва выбрасываем адреса, ники и метки: буквы в них есть (https, com, status), но это
    # буквы АДРЕСА, а не речи. Без этого описание из одних ссылок уходило бы на перевод.
    чистое = re.sub(r'https?://\S+|@\w+|#\w+', ' ', текст or '')
    буквы = [ч for ч in чистое if ч.isalpha()]
    if len(буквы) < 12:
        return True          # переводить нечего — не тревожим канал ради двух слов
    свои = sum(1 for ч in буквы if 'а' <= ч.lower() <= 'я' or ч.lower() == 'ё')
    return свои * 2 >= len(буквы)


async def _перевод_описания(update, context, описание, просьба=''):
    """Русский перевод описания поста — отдельным сообщением следом за роликом (#1367).

    🔴 25.08.2026, ОБР-1524. Владелец дословно: «если пост на Английском то тексту перевод
    ВСЕГДА добавляй, а в видео по заявке». Это отмена половины прежнего правила.

    БЫЛО (#1379, «переводить лишний раз не надо»): без слова «переведи» перевода не было
    вовсе. СТАЛО: текст описания переводится сам, как только он не русский. Дубляж видео
    правило не затронуло — он по-прежнему по заявке, это отдельный путь (`_дубляж_*`).

    Прежнее правило не стёрто, а оставлено здесь с датой отмены: иначе через месяц кто-нибудь
    прочтёт «только по просьбе» в старой записи и решит, что это сломали.

    Отдельным сообщением, а не подписью: подпись под видео у Telegram всего 1024 знака, и
    описание нередко занимает её целиком.
    """
    try:
        # Русское не переводим, короткое не трогаем — оба условия ниже, в `_похоже_на_русский`.
        # Условия «спросили ли перевод» больше нет: владелец велел добавлять всегда.
        текст = (описание or '').strip()
        if not текст or _похоже_на_русский(текст):
            return
        готово = await asyncio.get_event_loop().run_in_executor(
            None, lambda: ask_ai(
                'Переведи на русский:\n' + текст[:3000],
                'Ты профессиональный переводчик. Переведи текст на русский ПОЛНОСТЬЮ, до конца. '
                'Отдай ТОЛЬКО перевод — без пояснений, без исходника, без заголовков.',
                owner=is_owner(update), max_tokens=1200,
                порядок='сначала_бесплатные'))
        готово = re.sub(r'\n*⚡ \*Модель:.*$', '', готово or '', flags=re.S).strip()
        if not готово:
            return
        await _мсообщ(update).reply_text(
            '🇷🇺 <b>Перевод описания</b>\n\n' + готово[:3500],
            parse_mode='HTML', reply_to_message_id=update.message.message_id)
    except Exception as _е:
        # Перевод — ДОБАВКА к уже отданному ролику. Не вышло — говорим коротко и не портим
        # то, что удалось: молча глотать нельзя (закон #635), а рушить выдачу тем более.
        try:
            print('перевод описания: %s' % str(_е)[:200])
        except Exception:
            pass


async def _озвучить_скачанное(update, context, путь_видео, текст):
    """Русская озвучка к ролику, только что скачанному по ссылке (#1348).

    Ролик уже отдан человеку — здесь идёт ДОБАВКА, поэтому любая неудача сообщается словами
    и на этом кончается: портить уже удавшееся нельзя.
    """
    try:
        if not is_owner(update):
            return                       # платно; чужим — только по слову владельца
        # 🔴 #1379: озвучка ПЕРЕСТАЛА быть умолчанием. Раньше здесь стоял обратный заслон —
        # «делаем всегда, кроме случая, когда сказали „без озвучки“». Владелец поправил:
        # «я когда скажу перевести или субтитры, тогда только». Значит спрашиваем разрешения,
        # а не ищем запрет: молчание теперь значит «не надо», а не «надо».
        if not _ПРОСЯТ_ОЗВУЧКУ.search(текст or ''):
            return
        import shutil as _sh
        _ст = None
        try:
            _ст = await update.message.reply_text(
                '🎙 Ролик отдал, теперь делаю русскую озвучку — распознать речь, перевести, '
                'наговорить и свести. Это несколько минут, пришлю следом.')
        except Exception:
            pass

        async def _ход(т):
            try:
                if _ст:
                    await _ст.edit_text(т)
            except Exception:
                pass

        _папка = os.path.join(os.path.dirname(путь_видео), 'dub')
        os.makedirs(_папка, exist_ok=True)
        try:
            _гот, _отч, _срт = await дубляж_видео(путь_видео, _папка, _ход, 0.15)
        except Exception as _ед:
            await _ход('🔴 Озвучка сорвалась: %s' % str(_ед)[:200])
            return
        if not _гот:
            await _ход('🔴 Озвучка не собралась: %s' % (_отч or 'причина неизвестна'))
            # Перевод уже сделан и оплачен — отдать субтитрами честнее, чем выбросить.
            if _срт and os.path.exists(_срт):
                try:
                    with io.open(_срт, 'rb') as _фс:
                        await context.bot.send_document(
                            update.effective_chat.id, _фс, filename='perevod_ru.srt',
                            caption='📝 Русские субтитры к ролику — перевод собрался, '
                                    'подвела только сборка.',
                            reply_to_message_id=update.message.message_id)
                except Exception:
                    pass
            return
        try:
            with io.open(_гот, 'rb') as _фг:
                await context.bot.send_video(
                    update.effective_chat.id, _фг, caption=(_отч or '')[:1000],
                    parse_mode='HTML', reply_to_message_id=update.message.message_id,
                    supports_streaming=True,
                    read_timeout=180, write_timeout=180, connect_timeout=60)
            try:
                if _ст:
                    await _ст.delete()
            except Exception:
                pass
        except Exception as _ео:
            await _ход('🎙 Озвучил, а отправить не смог: %s' % str(_ео)[:180])
        finally:
            try:
                _sh.rmtree(_папка, ignore_errors=True)
            except Exception:
                pass
    except Exception as _е:
        try:
            print('озвучка скачанного: %s' % str(_е)[:200])
        except Exception:
            pass


def _ошибка_бота_в_журнал(суть, где='bot', след=''):
    """Записать поломку БОТА в общий журнал ошибок — тем же способом, что и _on_error.

    🔴 05.09.2026, смена 86. Разбор находки. Заслон «пустой ответ помощника» писал свою
    запись в errors.json РУКАМИ и в своей форме: ключи по-русски («где», «чат», «вопрос»),
    без `key`, `eid`, `count` и `fixed`. Последствий три, и все тихие:
      ① запись НЕВОЗМОЖНО закрыть — команда «ошибка решена B-NNN» ищет по `eid`, а его нет;
         `fixed` тоже нет, поэтому в отчёте она вечно числится открытой;
      ② нет дедупа — каждый случай ложился НОВОЙ строкой; на 05.09 таких строк 10 из 30
         «открытых», то есть треть журнала ошибок приложения — это одна и та же беда;
      ③ обрезка стояла `[-500:]`, а у обоих настоящих писателей `[-400:]`;два разных предела
         на один файл означают, что кто последний записал, тот и решил, сколько истории
         выбросить, — и настоящие A-/B-записи вытеснялись молча.
    Здесь форма ОДНА и общая. Старые две записи (errlog и _on_error) делают то же самое
    внутри себя; их сюда не переносил намеренно — это боевой путь, и трогать его ради
    красоты в ту же смену, когда чинишь другое, значит складывать два риска в один деплой.
    Следующая правка этих мест — повод перевести их на эту функцию (З-33).

    Возвращает номер записи (B-NNN) или пустую строку, если записать не вышло.
    ⚠️ Зовёт _data_put, а это поход в сеть: из асинхронного кода звать через executor.
    """
    try:
        cur = _data_get("errors.json", []) or []
        if not isinstance(cur, list):
            cur = []
        суть = (суть or '')[:500]
        key = ('bot|' + суть[:160])
        eid = ''
        for e in cur:
            if e.get('key') == key:
                e['count'] = e.get('count', 1) + 1
                e['last_t'] = _now_msk()
                eid = e.get('eid', '')
                break
        else:
            _seq = max([e.get('bseq', 0) for e in cur] or [0]) + 1
            eid = 'B-%03d' % _seq
            cur.append({'key': key, 'msg': суть, 'where': (где or 'bot')[:120],
                        'ver': 'bot', 'stack': (след or '')[:600], 'uid': '',
                        'count': 1, 'fixed': False, 'bseq': _seq, 'eid': eid,
                        't': _now_msk()})
            cur = cur[-400:]
        _data_put("errors.json", cur, "boterr: %s" % суть[:40])
        return eid
    except Exception:
        return ''


async def handle(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # 🔴 15.08.2026, ПЕРЕНЕСЕНО В НАЧАЛО handle. Это объявление стояло на 340 строк НИЖЕ,
    # а звали его выше — в ветке «запомнить видео, присланное владельцем». Вложенное
    # объявление связывает имя только когда до него дойдёт исполнение, поэтому там
    # каждый раз падало NameError, и падало МОЛЧА: ветка обёрнута в try. Владелец слал
    # видео, бот его не запоминал, и никто об этом не узнавал.
    # Нашлось разбором всего файла на неопределённые имена (pyflakes), а не глазами.

    # 🔴 06.08.2026. АНОНИМНЫЙ АДМИН — ЭТО ТОЖЕ ВЛАДЕЛЕЦ.
    # В чате джамаата владелец пишет от имени группы: у такого сообщения from_user — служебный
    # GroupAnonymousBot, а настоящий отправитель спрятан в sender_chat. Все мои проверки
    # «это владелец?» смотрели на from_user и для анонимных сообщений отвечали «нет».
    # Отсюда разом: и «почему отвечает Groq», и «почему зов не дошёл», и «почему ботяра не
    # ведёт к помощнику». Правила были верные — до них не доходило дело.
    # Чужой анонимом писать не может: право говорить от имени группы есть только у админов.
    def _хозяин(u):
        # 🔴 07.08.2026, 21:10, ПРИКАЗ ВЛАДЕЛЬЦА: «от имени канала Муслимун я пишу. Немедленно
        # впиши ид Муслимун только и две лички мои».
        # ЧТО БЫЛО. Здесь стояло правило «пишет от имени группы = владелец», заведённое 06.08,
        # чтобы его анонимные сообщения доходили. Но оно признаёт владельцем ЛЮБОГО админа
        # чата, написавшего анонимно: для бота они неотличимы. Я назвал ему эту дыру, и он
        # закрыл её одним словом — правильно, потому что через неё чужой человек мог бы
        # обратиться ко мне ОТ ЕГО ИМЕНИ, а я бы этого не заметил.
        # ЧТО СТАЛО. Владелец — только он сам: его канал MUSLIMOON и два его личных номера.
        # Больше никто, ни при каких подписях.
        return is_owner(u)

    # 🔴 15.08.2026. ЖИВАЯ ОШИБКА С ПРОДА: «cannot access local variable 'chat_id' where it
    # is not associated with a value» (журнал ошибок, чат джамаата).
    # Это ВТОРОЙ заход той же беды: первый раз (B-004) её закрыли одним присваиванием в
    # середине handle, и комментарий там честно предупреждает «обращаться к нему до этого
    # нельзя». Но ветка «вмешательства в диалог» читает chat_id из ДРУГОГО сучка, куда то
    # присваивание не попадает, — и падает. Чинили случай, а надо было класс (З-40).
    # Рождаем имя ОДИН РАЗ, в начале функции, до всякого ветвления. Присваивание ниже
    # остаётся: оно уточняет значение через update.message.chat, когда сообщение есть.
    # Здесь берём только effective_chat — он есть и у постов канала, где message is None.
    chat_id = getattr(getattr(update, 'effective_chat', None), 'id', 0) or 0

    if not update.message:
        # ⭐ НИШТЯЧОК прямо В КАНАЛЕ (Muslim Live и т.п.): это update.channel_post, а не update.message —
        # весь остальной handle() такие апдейты не видит вообще (падает на этой же строке). Постить в канал
        # может только админ, поэтому отдельная owner-проверка тут не нужна — сам факт поста уже доверенный.
        if update.channel_post:
            # 🔴 19.08.2026, ВОТ ГДЕ ОНА ТЕРЯЛАСЬ. Владелец пишет в чат от имени своего канала
            # Муслимун — такие сообщения приходят НЕ как update.message, а как channel_post, и
            # обработчик выходил отсюда, не дойдя ни до одной команды. Я четырежды переставлял
            # её всё выше внутри ветки, до которой сообщение вообще не добиралось.
            # Урок: прежде чем двигать своё правило, проверь, ПОПАДАЕТ ли сообщение в ту ветку,
            # где оно стоит. Я двигал вслепую и трижды назвал владельцу неверную причину.
            try:
                _чт = (update.channel_post.text or '').strip()
                if _чт.lower().startswith('модель') and is_owner(update):
                    _ч = _чт.split(None, 1)
                    if _ч[0].lower() == 'модель':
                        await _модель_команда(update, _ч[1].strip() if len(_ч) > 1 else '')
                        return
            except Exception as _e:
                print('команда модель (канал): %s' % str(_e)[:150])
            try:
                if await _nisht_dispatch(update, context):
                    return
                await _claude_deliver_replies(update, context)
                await _claude_dispatch(update, context)
            except Exception:
                pass
        return

    # 🔴 06.09.2026. Владелец: «я тебе скинул смс со скрином… а тебе не подаёт бот,
    # настрой нормально». Он прав, и корень ровно здесь.
    # У сообщения С КАРТИНКОЙ текста в `text` НЕТ — он лежит в `caption`. Здесь читалось
    # только `text`, дальше пустая строка расходилась по всему обработчику, и в очередь
    # технадзора (строка ниже, `dsoc_позвать_клода(..., text.strip(), ...)`) не попадало
    # ничего. Проверено по живой очереди: сообщение #2794 есть, #2804 есть, а то, что он
    # прислал между ними со скриншотом, — отсутствует.
    # Обиднее всего, что рядом, в `лента_запомнить`, подпись читается ПРАВИЛЬНО: там стоит
    # `text or caption`. То есть умение в файле было, а главный путь его не унаследовал —
    # тот же класс, что прецедент П-100.
    # Подпись к картинке — это и есть слова человека, и относиться к ним надо так же.
    text = (update.message.text or update.message.caption or "")
    text = text.strip()

    # 🔴 05.09.2026, смена 86. ЗАПИСЬ СКАЗАННОГО — ПЕРЕД ЛЮБЫМ РЕШЕНИЕМ, ЧТО С НИМ ДЕЛАТЬ.
    # Владелец: «я тебе написал в телеграм про сервер постоянный, посмотри обращения». Его
    # сообщения не было НИГДЕ: ни в очереди, ни в ленте. Причина оказалась не одна.
    # Этот вызов стоял на 750 строк ниже, а между началом обработчика и им — ДВАДЦАТЬ СЕМЬ
    # выходов с `return`. Двадцать семь способов для слова владельца исчезнуть бесследно.
    # Самый частый из них — ветка «скачай видео» сразу ниже: сообщение со ссылкой и словом
    # «достань/скинь/скачай» уходило в качалку и обработчик выходил, не записав ничего
    # (обращение О-0126, открыто 03.09 и провисело до сегодня).
    # Журнал не должен зависеть от того, КАК мы решили поступить с сообщением. Сперва
    # записываем, что человек сказал, потом решаем. Обратный порядок теряет тихо.
    try:
        лента_запомнить(update)
    except Exception:
        pass

    # ── 🧠 «МОЗГ …» — СВОЯ НЕЙРОНКА НА СЕРВЕРЕ (задача владельца 05.09.2026) ────────────
    # «сделай чтобы в оракл сервере всегда работала нейронка маленькая… и в том числе
    # как ассистента». Нейронка (gemma-4-E2B) и помощник живут на хосте Oracle службами
    # muslimoon-mozg и muslimoon-pomoshnik; отсюда до них — мост docker.
    #
    # Зовём ПОМОЩНИКА (8098), а не движок напрямую (8097). Разница принципиальная: помощник
    # сперва ищет в наших 26 сводах и велит модели отвечать ТОЛЬКО по найденному. Своей
    # головой она врёт уверенным тоном — на «что такое тахридж» ответила «это 40-й хадис,
    # один из самых известных». В проекте о достоверности такой помощник хуже, чем никакого.
    #
    # Стоит ВЫШЕ качалки видео и всего прочего: ниже по обработчику двадцать семь выходов
    # с return, и любая ветка съела бы команду раньше, чем до неё дошло дело.
    if text and text.lower().startswith(('мозг ', 'спроси ')):
        _вопрос = text.split(' ', 1)[1].strip() if ' ' in text else ''
        if not _вопрос:
            await update.message.reply_text('Напиши так: «мозг <вопрос>» — спрошу свою нейронку по нашей базе.')
            return
        await update.message.reply_text('🧠 Спрашиваю свою нейронку (ищет по нашим сводам, это 20–70 секунд)…')
        def _спросить_помощника():
            _тело = json.dumps({'q': _вопрос}, ensure_ascii=False).encode('utf-8')
            for _адрес in ('http://172.17.0.1:8098/sprosit', 'http://127.0.0.1:8098/sprosit'):
                try:
                    _о = requests.post(_адрес, data=_тело,
                                       headers={'Content-Type': 'application/json'}, timeout=600)
                    if _о.status_code == 200:
                        return _о.json()
                except Exception:
                    continue
            return None
        try:
            _от = await asyncio.get_event_loop().run_in_executor(None, _спросить_помощника)
        except Exception as _ем:
            _от = None
            print('мозг: помощник не ответил: %s' % str(_ем)[:120])
        if not _от:
            await update.message.reply_text(
                '🧠 Своя нейронка сейчас не отвечает. Это не поломка приложения — '
                'служба на сервере поднимается сама, попробуй через минуту.')
            return
        _текст = (_от.get('ответ') or '').strip() or 'Ответа не получилось.'
        _ист = _от.get('источники') or []
        _хвост = ('\n\n📖 смотрел: ' + ', '.join(_ист[:6])) if _ист else ''
        _сек = _от.get('секунд')
        _хвост += ('\n⏱ %s с · своя нейронка на нашем сервере, ключи не тратились'
                   % (round(_сек) if _сек else '?'))
        await update.message.reply_text((_текст[:3500] + _хвост))
        return

    # ── 🎬 «СКАЧАЙ ЭТО ВИДЕО» — ДЕЛОМ, А НЕ МОДЕЛЬЮ (владелец, 32 просьбы) ───────────────
    # Стоит В САМОМ НАЧАЛЕ, до всех прочих веток, и вот почему: раньше просьба доезжала до
    # языковой модели, у которой нет ни сети, ни диска, — та возвращала пустоту, а человек
    # видел «сбой на моей стороне». Между началом обработчика и моделью три тысячи строк;
    # любая ветка перехватила бы раньше. Умение, до которого не доходит дело, — не умение.
    #
    # ⚠️ В ГРУППЕ ТОЛЬКО КОГДА ПОЗВАЛИ. Владелец 22.08 (#1246): «неужели ты не понял, что ему
    # не стоит лезть, когда его не просят? Я написал робот — и он залез». Поэтому в группе
    # нужен либо зов по имени, либо ответ на моё же сообщение. В личке звать не нужно.
    try:
        _вс = _ВИДЕО_ССЫЛКА.search(text) if text else None
        # 🔴 23.08.2026, #1346: «ссылку скинул, должен был видео скинуть — че не работает».
        # На двери стояло ТРИ замка: ссылка + слово-просьба + зов. Он открыл один и не
        # получил даже отказа — молчание двери неотличимо от поломки.
        # ГОЛАЯ ССЫЛКА — ЭТО И ЕСТЬ ПРОСЬБА. Сообщение, где кроме ссылки (и зова по имени)
        # ничего нет, значит ровно одно: «на, возьми». Требовать сверху слова «скачай» —
        # второй замок на двери, уже запертой первым. А вот если слова ЕСТЬ, а корня-просьбы
        # среди них нет («смотрите какой ролик…»), — не лезем: человек делится, не заказывает.
        _голая = False
        if _вс:
            _ост = _ВИДЕО_ССЫЛКА.sub(' ', text)
            _ост = re.sub(r'@\w+|ботяр\w*|botyara', ' ', _ост, flags=re.I)
            _ост = re.sub(r'[^0-9A-Za-zА-Яа-яЁё]+', '', _ост)
            _голая = len(_ост) <= 3
        if _вс and (_ВИДЕО_ПРОСЬБА.search(text) or _голая):
            _в_группе = getattr(update.effective_chat, 'type', '') in ('group', 'supergroup')
            _позвали = True
            if _в_группе:
                _отв = getattr(update.message, 'reply_to_message', None)
                _мне = bool(_отв and getattr(getattr(_отв, 'from_user', None), 'is_bot', False))
                _низ = text.lower()
                # Имя бота спрашиваем У САМОГО БОТА: своей константы с ним в файле нет, а
                # выдуманное имя переменной — это мёртвая ветка, которая молча не сработает.
                _ник = (getattr(getattr(context, 'bot', None), 'username', '') or '').lower()
                # 🔴 ВЛАДЕЛЬЦУ ЗВАТЬ НЕ НУЖНО. Его #1246 («не лезь, когда не просят») держит
                # группу для всех остальных — им зов по-прежнему обязателен, залить чат чужими
                # роликами нечем. Но #1346 — тоже его слово, и оно про него самого.
                _позвали = _мне or ('ботяр' in _низ) or ('botyara' in _низ) \
                    or bool(_ник and ('@' + _ник) in _низ) or _хозяин(update)
            if _позвали:
                _урл = _вс.group(0).rstrip('.,);]')
                _ждём = None
                try:
                    _ждём = await update.message.reply_text('🎬 Качаю видео…')
                except Exception:
                    pass
                _путь, _опис, _беда = await asyncio.get_event_loop().run_in_executor(
                    None, _скачать_видео_по_ссылке, _урл)
                if _путь:
                    # Подпись — ОПИСАНИЕ ПОСТА, как и просили: «скачай и описание подставь».
                    # Ссылку добавляем в конец: по ней видно, откуда взято, и её можно открыть.
                    _подпись = (_опис or '').strip()
                    if len(_подпись) > 820:
                        _подпись = _подпись[:817] + '…'
                    _подпись = (_подпись + ('\n\n' if _подпись else '') + _урл)[:1024]
                    try:
                        with open(_путь, 'rb') as _ф:
                            await context.bot.send_video(
                                update.effective_chat.id, video=_ф, caption=_подпись,
                                reply_to_message_id=update.message.message_id,
                                supports_streaming=True,
                                read_timeout=180, write_timeout=180, connect_timeout=60)
                        try:
                            if _ждём:
                                await _ждём.delete()
                        except Exception:
                            pass
                        # Отметка для видеомоста: этот запрос МЫ уже закрыли, дублировать
                        # его через Muslim Live не нужно (см. _НАШЕ_ВИДЕО_ОТДАНО).
                        _отметить_наше_видео(update.effective_chat.id, update.message.message_id)
                        # 🇷🇺 #1367 + #1379. Перевод описания — ТОЛЬКО когда попросили
                        # словом «переведи». По умолчанию: видео + описание как в оригинале
                        # + ссылка. «Переводить лишний раз не надо» — его слово, дословно.
                        await _перевод_описания(update, context, _опис, text)
                        # 🎙 #1348: «просил скачивать видео с озвучкой русским переводом
                        # сразу». Дубляж в боте есть с заявки #714, но его ветка ждёт
                        # ВЛОЖЕНИЕ — до скачанного по ссылке она не доходила никогда.
                        # Зову здесь: ролик уже у человека, озвучка идёт добавкой следом.
                        await _озвучить_скачанное(update, context, _путь, text)
                    except Exception as _e:
                        _txt = ('🎬 Видео скачал, а отправить не смог: %s' % str(_e)[:180])
                        try:
                            if _ждём:
                                await _ждём.edit_text(_txt)
                            else:
                                await update.message.reply_text(_txt)
                        except Exception:
                            pass
                    finally:
                        try:
                            import shutil as _sh
                            _sh.rmtree(os.path.dirname(_путь), ignore_errors=True)
                        except Exception:
                            pass
                else:
                    # Отказ говорит ПРИЧИНУ. Закон владельца #635: «если он что-то не может, он
                    # говорит: я пока не могу, но…» — а не «сбой на моей стороне» без объяснения.
                    _txt = '🎬 Не смог скачать: %s' % (_беда or 'причина неизвестна')
                    # 🔴 ОБР-1545, владелец: «я же сказал, что можно пересылкой в Muslim Live
                    # решать вопрос». Он прав, и вот в чём была моя недоделка: запасной путь
                    # есть — видеомост подхватывает ровно тогда, когда своя качалка не смогла, —
                    # но при отказе бот о нём МОЛЧАЛ. Умение, о котором не сказано в тот
                    # момент, когда оно нужно, для человека всё равно что отсутствует.
                    # Говорим о нём ТОЛЬКО когда он выключен и только владельцу: включение
                    # пишет в публичный канал, это его решение, и посторонним эта команда ни к
                    # чему.
                    try:
                        if (update.effective_user and update.effective_user.id == OWNER_ID
                                and not (_вм_настройки() or {}).get('вкл')):
                            _txt += ('\n\n💡 Есть запасной путь: пересылка в Muslim Live — '
                                     'там ссылку заберёт чужая качалка, а видео вернётся сюда. '
                                     'Он выключен (сам пишет в публичный канал). '
                                     'Включить: «видеомост вкл».')
                    except Exception:
                        pass
                    try:
                        if _ждём:
                            await _ждём.edit_text(_txt)
                        else:
                            await update.message.reply_text(_txt)
                    except Exception:
                        pass
                return
    except Exception as _e:
        try:
            print('видео по ссылке: перехват упал — %s' % str(_e)[:200])
        except Exception:
            pass

    # 🔴 19.08.2026. Команда «модель» стоит ЗДЕСЬ, первой строкой после разбора текста.
    # Она уже стояла ниже — и владелец четырежды писал её впустую: между началом обработчика
    # и тем местом три с половиной тысячи строк, и любая ветка чата выходит раньше. Я всё это
    # время объяснял причину то очередью, то памятью сервера, то анонимной подписью — а дело
    # было в очерёдности. Приказ владельца обязан разбираться прежде всего прочего, иначе он
    # не приказ, а пожелание, зависящее от того, кто перехватит раньше.
    # 🔴 20.08.2026, 01:04, ПОЙМАНО НА ЖИВОМ. Владелец написал в джамаате «Переключись обратно
    # на облачный дипсик опенкод» — и НИЧЕГО не переключилось: команда ждала слова «модель»
    # ПЕРВЫМ, а он сказал по-человечески. Фраза ушла Лингу как обычный вопрос, тот вежливо
    # ответил, и владелец остался в уверенности, что переключился, — хотя говорил всё с той же
    # моделью. Хуже отказа: отказ виден, а это нет.
    #
    # Урок в этом файле УЖЕ ЗАПИСАН, обращение #497: имя «ботяра» искалось только в начале
    # строки, «а человек говорит как человек — дай, ботяра; ботяра, глянь». Я прочитал этот
    # разбор сегодня, разбирая соседний код, и не применил к команде, стоящей строкой выше.
    #
    # Ловим намерение, а не заклинание. Условия жёсткие нарочно: должен быть И глагол
    # переключения, И название канала — чтобы «а что за модель у дипсика» осталось вопросом
    # к помощнику, а не молча меняло ему движок.
    _низ_мод = (text or '').strip().lower()
    # 🔴 04.09.2026. Владелец: «локалки смс не пропускает бот, сделай что-то». Смена
    # «ЛОКАЛКИ 12» нашла и доказала: его сообщение «Локалки, кстати spark 2.5 … маленькая
    # МОДЕЛЬ, ТЫ её так и не протестил?» не попало НИ В ОДНУ линию. Она обошла все семь
    # очередей — сообщения нет нигде; оно не задержалось, а исчезло.
    # Причина здесь, строкой ниже: ветка-угадайка видит слово «модель», обращение «ты» и
    # вопросительный знак, решает, что это команда о модели, подменяет `text` на «модель»
    # и выходит с `return`. Обращение к ДРУГОЙ сессии съедалось молча.
    # Правило, которое из этого следует: ИМЯ ЛИНИИ В НАЧАЛЕ СТРОКИ СИЛЬНЕЕ ЛЮБОЙ ДОГАДКИ.
    # Ответить можно на случайное сообщение, а имя пишут осознанно — и адресат назван прямо.
    # Имя берём ТОЛЬКО с начала и только целым словом: «спроси у локалки» в середине фразы
    # адресатом не является (тот же капкан подстроки, что у дорог роутера, Ф-217 ⑦).
    _зов_линии = bool(re.match(r'^\s*(?:локалк\w*|гермес\w*|клод\w*|технадзор\w*|'
                               r'советник\w*|фэйбл\w*|fable\w*)\b', _низ_мод))
    _зовут_модель = _низ_мод.startswith('модель')
    if not _зовут_модель and not _зов_линии and is_owner(update) and len(_низ_мод) <= 120:
        _есть_глагол = re.search(r'переключ|верни|вернись|поставь|смени|переведи\s+(?:на|в)\b', _низ_мод)
        _есть_канал = re.search(r'облак|дипсик|deepseek|опенкод|opencode|ling|линг|квен|qwen', _низ_мод)
        if _есть_глагол and _есть_канал:
            _куда = ('облако' if re.search(r'облак|дипсик|deepseek|опенкод|opencode', _низ_мод)
                     else '')
            if not _куда:
                # 🔴 ЗДЕСЬ Я ЧУТЬ НЕ ПОВТОРИЛ БЕДУ, О КОТОРОЙ ПРЕДУПРЕЖДАЕТ СОСЕДНИЙ КОД.
                # Первый мой вариант брал профиль по началу имени — и на «поставь ling-q3-262k»
                # выбирал ling-ad-1m: у полудюжины профилей первое слово «ling», а перебор шёл
                # по алфавиту. Поймал собственной проверкой до выкатки. В _модель_команда об
                # этом написано прямым текстом: «Похожее не подставляем: подмена соседним
                # профилем — ровно тот случай, когда владелец выбрал одного Линга, а говорил
                # со старым и не заметил».
                # Поэтому: узнаём ТОЛЬКО полное имя профиля. Назвали коротко («на линг») —
                # намерение ясно, а выбор нет: показываем список и даём выбрать самому.
                # Молча угадать хуже, чем переспросить: угаданное неотличимо от выбранного.
                # 20.08.2026: ищем ТЕМ ЖЕ разрешателем, что и сама команда (_профиль_найти) —
                # иначе «переключись на орниз» и «модель орниз» понимались бы по-разному, и
                # мы получили бы две мерки одного имени. Сюда отдаём хвост фразы без глагола.
                _хвост = re.sub(r'^.*?(?:переключ\w*|верни\w*|поставь|смени|переведи)\s*'
                                r'(?:меня\s+)?(?:обратно\s+)?(?:на|в)?\s*', '', _низ_мод)
                _т2, _к2 = _профиль_найти(_хвост or _низ_мод,
                                          _реестр_моделей().get('местные') or {})
                if _т2:
                    _куда = _т2
                if not _куда:
                    text = 'модель'          # покажет список, ничего не переключая
                    _зовут_модель = True
                    print('команда модель узнана, но профиль назван неточно: «%s» — '
                          'показываю список' % _низ_мод[:60])
            if _куда:
                text = 'модель ' + _куда
                _зовут_модель = True
                print('команда модель узнана по-человечески: «%s» → «%s»'
                      % (_низ_мод[:60], text))

    # 🔴 23.08.2026, #911 и #922. Ветка выше ловит ПРИКАЗ («переключись на дипсик»), а ВОПРОС
    # («ты умеешь переключать модели?», «ты какая модель?») в неё не попадает: нет ни глагола
    # переключения, ни названия канала. Вопрос уходил языковой модели, у которой нет ни реестра
    # профилей, ни права переключать, — и она отвечала «не умею». Помощник сам занёс этот отказ
    # в дыры умения, дважды за один вечер, при живой команде в этом же файле.
    # Половину класса вылечили 20.08, вторая половина стояла нетронутой — тот самый случай,
    # когда «починили случай, а не класс» (З-40).
    #
    # ⚠️ Условия нарочно узкие: спрашивать должны ПРО НЕГО. «А что за модель у дипсика» —
    # разговор, а не команда, и он обязан остаться разговором. Поэтому либо прямое обращение
    # («ты», «у тебя») в вопросе, либо связка «умеешь + переключать». Ответ показывает шапку
    # «🎛 Модель помощника» — если я всё же понял не то, это видно с первой строки, а не молча.
    if not _зовут_модель and not _зов_линии and is_owner(update) and 0 < len(_низ_мод) <= 160:
        _м_модель = 'модел' in _низ_мод
        _м_про_него = re.search(r'\bты\b|\bтебя\b|\bтебе\b|\bу\s+теб|\bсебя\b', _низ_мод)
        _м_умение = re.search(r'умеешь|умеет|можешь|можел|сможешь|способен|можно\s+ли', _низ_мод)
        _м_смена = re.search(r'переключ|смен|поменя|перейти|перекл', _низ_мод)
        # Вопросное слово ищем ГДЕ УГОДНО, не только в начале: «у тебя какая модель стоит»
        # — вопрос без знака вопроса и без вопросительного зачина. Ослабить не страшно,
        # потому что настоящий заслон здесь другой — обращение ПРО НЕГО (_м_про_него).
        _м_вопрос = ('?' in _низ_мод) or re.search(
            r'\b(кака\w*|како\w*|что\s+за|кто\s+ты|скажи)', _низ_мод)
        if _м_модель and ((_м_умение and _м_смена) or (_м_про_него and _м_вопрос)):
            text = 'модель'
            _зовут_модель = True
            print('вопрос о модели узнан по-человечески: «%s»' % _низ_мод[:60])

    if _зовут_модель and is_owner(update):
        _мчасти = text.strip().split(None, 1)
        if _мчасти[0].lower() == 'модель':
            _мимя = (_мчасти[1].strip() if len(_мчасти) > 1 else '')
            try:
                await _модель_команда(update, _мимя)
            except Exception as _e:
                print('команда модель упала: %s' % str(_e)[:200])
                try:
                    await _мсообщ(update).reply_text('🔧 Команда сорвалась: %s' % str(_e)[:150])
                except Exception:
                    pass
            return

    # 🎬 #1147: «Видеомост вкл» — помощник отвечал «не могу» при живой команде. Её вызов
    # лежал ВНУТРИ блока команды «раг», то есть сработать мог только на «раг видеомост вкл».
    # Ставлю здесь по той же причине, по какой здесь стоит «модель»: приказ владельца не
    # должен ждать своей очереди среди трёх тысяч строк.
    # Проверку хозяина не дублирую — `_вм_команда` делает её сама и на чужое возвращает None.
    try:
        _вм_ид = getattr(getattr(update, 'effective_user', None), 'id', 0) or 0
        _вм_отв = _вм_команда(text, int(_вм_ид))
    except Exception as _е:
        print('команда видеомост: %s' % str(_е)[:150])
        _вм_отв = None
    if _вм_отв is not None:
        await _мсообщ(update).reply_text(_вм_отв)
        return

    # 📖 ПРОВОДКА РАССЫЛКИ (#1416). Команда стоит ЗДЕСЬ по той же причине, по которой сюда
    # переехал видеомост: этой ночью выяснилось, что его вызов лежал внутри чужого блока и
    # включить его было нельзя вовсе. Умение без дороги — не умение.
    try:
        _рас_ид = getattr(getattr(update, 'effective_user', None), 'id', 0) or 0
        if await _рас_команда(update, text, int(_рас_ид)):
            return
    except Exception as _ер:
        print('команда рассылки: %s' % str(_ер)[:150])

    # 🛡 #178: осмотр сообщений новичков на рекламу. Стоит РАНО и ничего не решает сам —
    # только считает приметы и, если сошлись, зовёт владельца с кнопками. Ни одной ветки
    # ниже не трогает: свой возврат не делает, исключения глотает у себя.
    try:
        await спам_осмотр(update, context, text)
    except Exception:
        pass

    # 🎬 #234/#235/#239: ролик по ПРОСЬБЕ ЧЕЛОВЕКА, а не по волшебному слову.
    # 🔴 Владелец, #239: «сто раз тебе говорю, не надо мне говорить КАК ПОЗВАТЬ. Он ИИ,
    # сам должен квалифицировать волю». Первая моя версия ждала слово «видео» СТРОГО первым
    # — то есть я выучил человека под свой разбор, вместо того чтобы разобрать его речь.
    # Его же настоящая просьба («Сделай видео из этого озвучь сам классно… для ютуб шортса
    # видео бахни скинь сюда») под тот разбор НЕ ПОПАДАЛА ВОВСЕ.
    # Теперь узнаём намерение: делательный глагол рядом со словом про ролик, в любом порядке
    # и в любом месте фразы. Прошедшее время не берём («он сделал видео вчера» — это рассказ,
    # а не просьба), и «покажи/пришли видео» тоже: там просят готовое, а не сделать.
    try:
        _вм = _хочет_ролик(text)
        if _вм and update.effective_user and update.effective_user.id == OWNER_ID:
            _исх = _вм
            if len(_исх) < 20 and update.message.reply_to_message:
                _r = update.message.reply_to_message
                _исх = ((_r.text or _r.caption or '')).strip()
            if len(_исх) < 20:
                await _мсообщ(update).reply_text(
                    'Дай текст: «видео <текст>» либо ответь этим словом на сообщение, '
                    'из которого делать ролик. Из двух слов ролика не выйдет.')
                return
            _папка = tempfile.mkdtemp(prefix='shorts_')
            try:
                async def _ход(с):
                    try:
                        await _мсообщ(update).reply_text(с)
                    except Exception:
                        pass
                _путь, _отчёт = await сделать_видео(_исх, _папка, _ход)
                if not _путь:
                    await _мсообщ(update).reply_text('🎬 Не получилось: %s.' % _отчёт)
                else:
                    with open(_путь, 'rb') as _f:
                        await context.bot.send_video(update.effective_chat.id, _f,
                                                     caption=_отчёт[:1000],
                                                     supports_streaming=True)
            finally:
                try:
                    shutil.rmtree(_папка, ignore_errors=True)
                except Exception:
                    pass
            return
    except Exception as _e:
        try:
            await _мсообщ(update).reply_text('🎬 Сорвалось на середине: %s' % str(_e)[:200])
        except Exception:
            pass
        return

    # 📗 ССЫЛКА НА МАКТАБУ ШАМИЛЯ — РАСПОЗНАТЬ И ОТВЕТИТЬ ДЕЛОМ
    #
    # Слово владельца 18.08.2026: «если сюда скинут такие ссылки на Мактаба Шамиля, ты должен
    # их распознавать, и соответствующую страницу у нас в приложении ссылку кидать, и кидать
    # соответствующий текст с переводом сюда».
    #
    # Переводить номера не нужно и НЕЛЬЗЯ выдумывать: id книги у Шамили и у нас ОДИН И ТОТ ЖЕ,
    # страница прямая (это уже выяснено и записано у «Страницы в Мактабе», #74). Значит ссылка
    # в приложение строится из самого адреса, без догадок.
    #
    # Стоит ДО помощника намеренно: иначе ссылка ушла бы модели, та пересказала бы её своими
    # словами, и человек получил бы пересказ вместо страницы. Здесь всё точное: текст из
    # Мактабы, перевод нашим переводчиком, ссылка собрана из чисел адреса.
    # 🔴 Слово владельца 18.08.2026 (#851): «к ссылкам Мактаба добавь также ссылки с Сунна
    # ком и апптурас». Адреса разные, а книга за ними одна и та же: у Шамили и у turath
    # НОМЕР КНИГИ ОДИН, отличается только вид адреса. Поэтому не заводим второй обработчик,
    # а расширяем разбор (З-33): один вход — три написания одного и того же.
    #   shamela.ws/book/2170/1687      → книга 2170, страница 1687
    #   app.turath.io/book/2170?page=1687 → то же самое
    # Сунна.ком устроен иначе: это не страница книги, а НУМЕРОВАННЫЙ ХАДИС, и отвечать на
    # него надо хадисом из нашей базы, а не страницей. Его ловим отдельным выражением.
    _шам = _сун = None
    try:
        _шам = re.search(r'(?:shamela' + chr(92) + r'.ws|app' + chr(92) + r'.turath' + chr(92) + r'.io)'
                         r'/book/(' + chr(92) + r'd{1,7})'
                         r'(?:/(' + chr(92) + r'd{1,6})|[?&][^ ]*?page=(' + chr(92) + r'd{1,6}))?',
                         text or '', re.I)
        if not _шам:
            _сун = re.search(r'sunnah' + chr(92) + r'.com/([a-z]+)(?:/(' + chr(92) + r'd{1,4}))?'
                             r'[:/](' + chr(92) + r'd{1,6})', text or '', re.I)
    except Exception:
        _шам = _сун = None
    if _шам:
        # 🔴 «Технадзор, зачем он влезает?» — сказано через двадцать минут после выкатки, и
        # сказано справедливо. Я поставил ответ на ЛЮБУЮ такую ссылку в ЛЮБОМ чате: в общине
        # на тысячу человек Мактабой делятся каждый день, и бот полез бы в каждый такой
        # разговор. Это ровно то, за что сегодня же был разбор про надзор в чужих чатах, —
        # и я повторил ошибку в новом умении через полдня после того, как её чинил.
        #
        # Правило простое: в личку владельца отвечаем всегда, в группе — ТОЛЬКО когда позвали:
        # ответом на сообщение бота либо обращением к нему по имени. Молча вклиниваться в
        # чужой разговор нельзя, даже с полезным.
        _личка_ш = (getattr(update.effective_chat, 'type', '') == 'private')
        _звали_ш = False
        try:
            _от_ш = update.message.reply_to_message
            _звали_ш = bool(_от_ш and getattr(_от_ш, 'from_user', None)
                            and _от_ш.from_user.is_bot)
        except Exception:
            _звали_ш = False
        if not _звали_ш:
            _звали_ш = bool(re.search(r'ботяр|\bбот\b|технадзор|муслимун|@muslimoontt_bot',
                                      text or '', re.I))
        # 🔴 «Клод, почему ты лично выполняешь, если ассистент должен выполнить?» (#854).
        # Справедливо, и это поправка к предыдущей. Я закрыл ответ в группах, чтобы бот не
        # лез в чужой разговор, — и закрыл заодно СЛУЧАЙ ВЛАДЕЛЬЦА: он бросил ссылку в общине,
        # бот промолчал, и исполнять пришлось мне руками. А умение затевалось ровно затем,
        # чтобы делал бот.
        # Разводим два случая: ссылка ОТ ВЛАДЕЛЬЦА — это просьба, отвечаем всегда;
        # ссылка от постороннего в группе — чужой разговор, молчим, пока не позвали.
        try:
            _хозяин_ш = is_owner(update)
        except Exception:
            _хозяин_ш = False
        if not (_личка_ш or _звали_ш or _хозяин_ш):
            _шам = _сун = None
    if _сун:
        # СУННА.КОМ — это не страница книги, а нумерованный хадис. Значит и отвечать надо
        # хадисом из НАШЕЙ базы: тем же путём, каким работает «источник <сборник> <номер>».
        # Слуги у них и у нас почти совпадают; где расходятся — сводим здесь, одним местом.
        _СУН_КОД = {'bukhari': 'bukhari', 'muslim': 'muslim', 'abudawud': 'abudawud',
                    'tirmidhi': 'tirmidhi', 'nasai': 'nasai', 'ibnmajah': 'ibnmajah',
                    'malik': 'malik', 'ahmad': 'ahmad', 'darimi': 'darimi',
                    'nasaikubra': 'nasaikubra', 'bulugh': '', 'riyadussalihin': '',
                    'adab': 'adabmufrad', 'shamail': ''}
        _скод = _СУН_КОД.get((_сун.group(1) or '').lower(), '')
        _сном = _сун.group(3)
        if not _скод:
            try:
                await _мсообщ(update).reply_text(
                    'Этот сборник с sunnah.com у нас отдельной книгой не заведён — '
                    'ответить его хадисом не могу. Назовите сборник и номер словами, '
                    'поищу по нашим сводам.',
                    reply_to_message_id=update.message.message_id)
            except Exception:
                pass
            return
        try:
            _сар, _сру, _сяз, _соц = await asyncio.get_event_loop().run_in_executor(
                None, lambda: (get_ahmad_hadith(_сном) if _скод == 'ahmad'
                               else get_hadith(_скод, _сном)))
        except Exception as _ес:
            _сар = _сру = ''
        if not (_сар or _сру):
            try:
                await _мсообщ(update).reply_text(
                    '%s №%s у нас не нашёлся — возможно, номер за пределами нашего издания. '
                    'Это не «нет доступа»: я смотрел в своей базе.' % (NAMES.get(_скод, _скод), _сном),
                    reply_to_message_id=update.message.message_id)
            except Exception:
                pass
            return
        _сссыл = 'https://t.me/muslimoontt_bot/app?startapp=r_%s_%s' % (_скод, _сном)
        _стело = ('📖 <b>%s, №%s</b>' % (esc(NAMES.get(_скод, _скод)), esc(str(_сном)))
                  + chr(10) + chr(10)
                  + '<blockquote expandable>%s</blockquote>' % esc((_сар or '')[:2200]))
        if _сру:
            _стело += (chr(10) + chr(10) + '<b>Перевод:</b>' + chr(10)
                       + '<blockquote expandable>%s</blockquote>' % esc(_сру[:2200]))
        _стело += (chr(10) + chr(10) + '📱 <a href="%s">Открыть в приложении</a>'
                   ' — цепь передатчиков, оценки критиков, тахридж' % _сссыл)
        try:
            await _мсообщ(update).reply_text(_стело[:4000], parse_mode='HTML',
                                            disable_web_page_preview=True,
                                            reply_to_message_id=update.message.message_id)
        except Exception:
            pass
        return
    if _шам:
        _шбид = _шам.group(1)
        _шстр = int(_шам.group(2) or _шам.group(3) or 1)
        _ст_ш = None
        try:
            _ст_ш = await update.message.reply_text(
                '📗 Открываю страницу %s книги %s в Мактабе…' % (_шстр, _шбид),
                reply_to_message_id=update.message.message_id)
        except Exception:
            pass
        try:
            _стрн = await asyncio.get_event_loop().run_in_executor(
                None, lambda: turath_page(_шбид, _шстр))
        except Exception as _еш:
            _стрн = {'error': str(_еш)[:120]}
        _штекст = ((_стрн or {}).get('text') or '').strip()
        if not _штекст:
            _прич = (_стрн or {}).get('error') or 'страница пуста'
            try:
                await (_ст_ш.edit_text if _ст_ш else update.message.reply_text)(
                    '📗 Страницу %s книги %s достать не вышло: %s.' % (_шстр, _шбид, _прич)
                    + chr(10) + 'Это не «нет доступа» — Мактаба сейчас не отозвалась либо '
                      'номер страницы за пределами книги.')
            except Exception:
                pass
            return
        _шмета = (_стрн or {}).get('meta') or {}
        _шкнига = str(_шмета.get('book_name') or '').strip() or ('книга %s' % _шбид)
        _шчист = re.sub(r'<[^>]+>', ' ', _штекст)
        _шчист = re.sub(r'[ ' + chr(92) + r't]{2,}', ' ', _шчист).strip()
        # Перевод — нашим переводчиком, а не пересказом модели: страница книги пересказу
        # не подлежит. Длинную режем, чтобы влезла в сообщение и не стоила лишнего.
        _шпер = ''
        try:
            _шпер = await asyncio.get_event_loop().run_in_executor(
                None, lambda: translate_matn(_шчист[:2500], src='shamela:%s:%s' % (_шбид, _шстр)))
        except Exception as _еп:
            _шпер = ''
        _шссыл = 'https://t.me/muslimoontt_bot/app?startapp=b_%s_%s' % (_шбид, _шстр)
        _тело_ш = ('📗 <b>%s</b> · страница %s' % (esc(_шкнига), _шстр) + chr(10) + chr(10)
                   + '<blockquote expandable>%s</blockquote>' % esc(_шчист[:2600]))
        if _шпер:
            _тело_ш += (chr(10) + chr(10) + '<b>Перевод:</b>' + chr(10)
                        + '<blockquote expandable>%s</blockquote>' % esc(_шпер[:2600]))
        else:
            _тело_ш += (chr(10) + chr(10) + '<i>Перевод сейчас не собрался — текст выше настоящий, '
                        'перевод повторю по просьбе.</i>')
        _тело_ш += (chr(10) + chr(10) + '📱 <a href="%s">Открыть эту же страницу в приложении</a>'
                    % _шссыл)
        try:
            await (_ст_ш.edit_text if _ст_ш else update.message.reply_text)(
                _тело_ш[:4000], parse_mode='HTML', disable_web_page_preview=True)
        except Exception:
            try:
                await _мсообщ(update).reply_text(_тело_ш[:4000], parse_mode='HTML',
                                                disable_web_page_preview=True)
            except Exception:
                pass
        return


    # 🎙 ДУБЛЯЖ ВИДЕО (заявка #714): «видео озвучь переводом на русский, добавь русские
    # субтитры, а оригинал аудио оставь чуть приглушённым».
    # Стоит ПЕРЕД голосовым блоком и перед DSOC намеренно. Иначе видео с подписью «озвучь»
    # ушло бы в помощника: тот расшифровал бы запись, ответил про неё текстом и озвучил
    # СВОЙ ответ — то есть сделал бы похожее на просьбу и не то, о чём просили.
    try:
        _вид = getattr(update.message, 'video', None)
        _вид_ответ = None
        if _вид is None:
            _пв = update.message.reply_to_message
            _вид = getattr(_пв, 'video', None) if _пв else None
            _вид_ответ = _пв.message_id if (_пв and _вид is not None) else None
        _хочет_дубляж = bool(_вид is not None and text
                             and re.search(r'озвуч|дубляж|дублируй|переозвуч', text, re.I)
                             and re.search(r'перевод|переведи|русск|дубляж', text, re.I))
    except Exception:
        _вид, _вид_ответ, _хочет_дубляж = None, None, False
    if _хочет_дубляж:
        if not is_owner(update):
            # Дубляж стоит денег (Whisper + перевод) и минут работы сервера. Открывать его
            # чату на тысячу человек без слова владельца я не вправе — но и молчать нельзя.
            await _мсообщ(update).reply_text(
                '🎙 Озвучить видео переводом я умею, но пока только по просьбе владельца: '
                'на каждое такое видео уходят платные распознавание и перевод. Скажите ему — '
                'откроет всем одной строкой.')
            return
        _громкость = 0.15
        _мгр = re.search(r'оригинал\D{0,12}(\d{1,3})\s*%', text or '', re.I)
        if _мгр:
            _громкость = max(0.0, min(1.0, int(_мгр.group(1)) / 100.0))
        _ст_д = await update.message.reply_text(
            '🎙 Взял видео в работу. Это не быстро: распознать речь, перевести, наговорить '
            'и свести — несколько минут.', reply_to_message_id=_вид_ответ)
        _папка_д = os.path.join('/tmp', 'dub_%s' % update.message.message_id)
        try:
            os.makedirs(_папка_д, exist_ok=True)
            _исх = os.path.join(_папка_д, 'исходник.mp4')
            try:
                _фв = await context.bot.get_file(_вид.file_id)
                await _фв.download_to_drive(_исх)
            except Exception as _ев:
                # У Telegram потолок скачивания ботом — 20 МБ. Говорим это прямо, а не
                # «что-то пошло не так»: человек тогда знает, что делать (прислать короче).
                await _ст_д.edit_text(
                    '🔴 Не смог скачать видео: %s\nЧаще всего дело в размере — бот может '
                    'забрать у Telegram файл не больше 20 МБ. Пришлите кусок покороче или '
                    'сожмите.' % str(_ев)[:150])
                return

            async def _ход(т):
                try:
                    await _ст_д.edit_text(т)
                except Exception:
                    pass

            _гот, _отч, _срт_ф = await дубляж_видео(_исх, _папка_д, _ход, _громкость)
            if not _гот:
                await _ст_д.edit_text('🔴 Озвучка не собралась: %s' % _отч)
                if _срт_ф and os.path.exists(_срт_ф):
                    # Перевод уже сделан и оплачен — отдать его файлом дешевле и честнее,
                    # чем выбросить и заставить платить за него второй раз.
                    try:
                        with io.open(_срт_ф, 'rb') as _фс:
                            await context.bot.send_document(
                                update.effective_chat.id, _фс, filename='perevod_ru.srt',
                                caption='📝 Русские субтитры к этому видео — перевод собрался, '
                                        'подвела только сборка.',
                                reply_to_message_id=_вид_ответ or update.message.message_id)
                    except Exception:
                        pass
                return
            try:
                with io.open(_гот, 'rb') as _фг:
                    await context.bot.send_video(
                        update.effective_chat.id, _фг, caption=_отч[:1000], parse_mode='HTML',
                        reply_to_message_id=_вид_ответ or update.message.message_id,
                        supports_streaming=True)
                await _ст_д.delete()
            except Exception as _ео:
                await _ст_д.edit_text(
                    '🎙 Собрал, но отправить не вышло: %s\n%s' % (str(_ео)[:150], _отч[:600]))
            if _срт_ф and os.path.exists(_срт_ф):
                try:
                    with io.open(_срт_ф, 'rb') as _фс:
                        await context.bot.send_document(
                            update.effective_chat.id, _фс, filename='perevod_ru.srt',
                            caption='📝 Субтитры отдельным файлом — в кадр они не легли.')
                except Exception:
                    pass
        except Exception as _едд:
            try:
                await _ст_д.edit_text('🔴 Дубляж сорвался: %s' % str(_едд)[:250])
            except Exception:
                pass
        finally:
            # Ролик, дорожки и десятки mp3 занимают место; в /tmp у Railway его немного.
            try:
                shutil.rmtree(_папка_д, ignore_errors=True)
            except Exception:
                pass
        return

    # 🎤 ГОЛОСОВОЕ/АУДИО. Стоит ПЕРЕД разбором DSOC, и это принципиально: у голосового нет
    # текста, значит до разбора обращения оно не доживёт — сперва расшифровка, потом решаем.
    #  • слышно «DSOC …» → это к ассистенту, и отвечаем ГОЛОСОМ (спросили голосом — отвечай так же);
    #  • иначе → заявка #630: ищем оригинал хадиса в нашей базе.
    # Владельческий поток «голосовая заявка» в личке не трогаем — он про другое и работает давно.
    _голосом_просили = False
    try:
        _гол = update.message.voice or update.message.audio or update.message.video_note
    except Exception:
        _гол = None
    # Ответили словом «хадис» на ЧУЖОЕ (или своё старое) голосовое → разбираем ТО сообщение и
    # вешаем ответ на него же. Единственный способ дотянуться до записи, которой в текущем
    # сообщении нет: истории чата боту не видно, а вот на что ответили — видно всегда.
    if _гол is None and text and re.match(r'^\s*(хадис|найди хадис|что за хадис|оригинал)\s*[?!.]*\s*$',
                                          text.strip(), re.I):
        try:
            _пред = update.message.reply_to_message
            _гол = (_пред.voice or _пред.audio or _пред.video_note) if _пред else None
            if _гол is not None:
                await аудио_в_хадис(update, context, _гол.file_id, "",
                                    отвечать_на=_пред.message_id)
                return
        except Exception as _e:
            try:
                await _мсообщ(update).reply_text("🔴 Не смог разобрать то голосовое: %s" % str(_e)[:200])
            except Exception:
                pass
            return
    if _гол is not None:
        _расш = None
        try:
            _пф = await context.bot.get_file(_гол.file_id)
            _пп = os.path.join("/tmp", "in_%s.ogg" % update.message.message_id)
            await _пф.download_to_drive(_пп)
            _расш = await asyncio.get_event_loop().run_in_executor(None, transcribe_audio, _пп)
            try:
                os.remove(_пп)
            except Exception:
                pass
        except Exception:
            _расш = None
        # 🔴 05.08.2026. Было: «любое голосовое, кроме обращения к помощнику, — это поиск
        # хадиса». Владелец спросил голосом «ты голосовые сообщения понимаешь?» и получил
        # «такого хадиса в базе нет». Умолчание стояло не у того: помощник понимает больше,
        # значит всё неопределённое — ему, а в поиск хадиса уходит лишь то, где хадис ЯВНО
        # слышен: арабская речь или прямые слова о хадисе и передаче.
        _про_хадис = False
        if _расш:
            _н = _расш.lower()
            _про_хадис = bool(re.search(r'[\u0621-\u064A]{6,}', _расш)) or any(
                с in _н for с in ('хадис', 'передал', 'рассказал нам', 'сообщил нам',
                                  'сказал посланник', 'пророк сказал', 'со слов'))
        # 🔴 ЗОВ ВЛАДЕЛЬЦА #50 (06.08.2026): «не влазить». В группе бот лез в КАЖДОЕ голосовое —
        # качал, расшифровывал и при неудаче отвечал «не разобрал речь» человеку, который его не
        # звал. Разговор чужой, бот в нём лишний; хуже того, ответ приходил именно тогда, когда
        # бот НЕ справился, — то есть влезал, чтобы сообщить о собственной неудаче.
        # Теперь в группе отвечаем на голосовое, ТОЛЬКО когда к боту обратились: ответом на его
        # сообщение, обращением в подписи или обращением слышно в самой речи. Расшифровку не
        # отменяем — иначе пропадёт возможность позвать помощника голосом; молчим именно ответом.
        _группа = getattr(update.effective_chat, "type", "") != "private"
        _звали = True
        if _группа:
            try:
                _пред = update.message.reply_to_message
                _звали = bool(_пред and getattr(_пред, 'from_user', None)
                              and _пред.from_user.id == context.bot.id)
            except Exception:
                _звали = False
            if not _звали:
                _звали = parse_dsoc(update.message.caption or '') is not None
            if not _звали and _расш:
                _звали = parse_dsoc(_расш) is not None
            if not _звали:
                return                       # чужой разговор — молчим совсем, даже об ошибке
        # 🔴 Владелец 11:22: «почему он реагирует на то, что я же его не вызывал?»
        # Здесь стояло «или НЕ про хадис» — то есть ЛЮБОЕ голосовое, в котором не узнали
        # просьбу о хадисе, уходило помощнику. Владелец переслал в чат чужую аудио-лекцию —
        # и помощник полез её разбирать за деньги подписки.
        # Молчание — поведение по умолчанию. Отвечает тот, кого позвали, а не тот, кто
        # услышал. «Не понял, о чём речь» — не повод вступать в разговор.
        _позвали_голосом = bool(_расш and parse_dsoc(_расш) is not None)
        if not _позвали_голосом and _расш:
            # …и обращение в подписи к самому голосовому тоже считается вызовом
            _позвали_голосом = parse_dsoc(update.message.caption or '') is not None
        if not _позвали_голосом and update.message.reply_to_message is not None:
            try:   # …и ответ на реплику самого помощника
                _пм = update.message.reply_to_message.from_user
                _позвали_голосом = bool(_пм and _пм.id == context.bot.id)
            except Exception:
                pass
        # Пересланное чужое сообщение помощника не касается вовсе, даже если переслал владелец:
        # переслать — значит показать, а не спросить.
        if getattr(update.message, 'forward_origin', None) is not None and not _позвали_голосом:
            _позвали_голосом = False
        if _позвали_голосом:
            text = _расш.strip()                  # дальше отработает разбор DSOC
            _голосом_просили = True
        elif _группа:
            try:
                await аудио_в_хадис(update, context, _гол.file_id, update.message.caption or "")
            except Exception as _e:
                try:
                    await _мсообщ(update).reply_text("🔴 Сбой на разборе аудио: %s" % str(_e)[:200])
                except Exception:
                    pass
            return

    # 🔊 «ближайший час дублируй голосом все ответы» (#22, #25). Ловим ЗДЕСЬ — после расшифровки
    # голосового и до разбора DSOC: команду одинаково можно и написать, и сказать вслух, а если
    # пропустить её сюда, она уедет в модель и вернётся вежливым «хорошо, буду» вместо режима.
    # Только владельцу: озвучка каждого ответа — его личная просьба, а не общая настройка чата.
    # «читай голосом 3», «читай Эммой», «голос 5» — владелец выбрал из присланных проб (#26/#28).
    # Ловим ЗДЕСЬ, до модели: иначе выбор уедет в разговор и вернётся вежливым «хорошо, буду»,
    # а голос останется прежним — ровно то, что происходило у него два дня.
    if text and is_owner(update):
        # Две формы: «голосом 3» и просто «читай Эммой» — вторая живее, так и говорят.
        # Ошибиться она не даст: если названное не совпало ни с одним голосом, голос_выбрать
        # вернёт None и фраза уйдёт дальше как обычная («читай хадис 5» не перехватится).
        _вг = re.match(r'^(?:читай\s+)?голос(?:ом)?\s+(.+)$', text.strip(), re.I) \
            or re.match(r'^читай\s+(\S+)\s*$', text.strip(), re.I)
        if _вг:
            _расп = голос_выбрать(_вг.group(1))
            if _расп:
                await _мсообщ(update).reply_text(_расп)
                await сказать_голосом(update, _расп, context)    # сразу слышно, что закрепилось
                return
    if text and is_owner(update):
        _голсек = голос_режим_разобрать(text)
        if _голсек is not None:
            _расписка = голос_режим_задать(update.effective_chat.id, _голсек)
            await _мсообщ(update).reply_text(_расписка)
            if _голсек:      # включили — тут же показываем голосом, что режим ЖИВОЙ, а не обещан
                await сказать_голосом(update, _расписка, context)
            return

    # ═══════════════════════════════════════════════════════════════════════════════
    #  🟩 DSOC — прямой разговор с DeepSeek через подписку OpenCode. 05.08.2026.
    # ═══════════════════════════════════════════════════════════════════════════════
    # Стоит ПЕРЕД разбором «ботяры»: обращение прямое и однозначное, перехватывать его
    # другим правилам незачем.
    # 🎬 ВИДЕО ОТ ВЛАДЕЛЬЦА — ловим и запоминаем (обращения #341/#343)
    #
    # Владелец: «перешли просто видео, убрал адресата и описание, и скачай».
    # Чужой файл взять нельзя — Telegram на пересылку того поста отвечает «Message to forward
    # not found»: приветственные боты СВОИ посты через время удаляют, и к моему приходу его
    # уже нет. А вот присланное САМИМ владельцем бот получает целиком.
    # Поэтому: любое видео из его лички запоминаем сразу — не файлом, а его номером у
    # Telegram (file_id). По этому номеру мы можем слать ролик сколько угодно раз, ничего не
    # скачивая и не храня у себя.
    try:
        _вид = (getattr(update.message, 'video', None)
                or getattr(update.message, 'animation', None)
                or getattr(update.message, 'video_note', None))
        if _вид and _хозяин(update) and getattr(update.effective_chat, 'type', '') == 'private':
            _fid = getattr(_вид, 'file_id', '')
            _сек = int(getattr(_вид, 'duration', 0) or 0)
            _data_put('privet_video.json',
                      {'file_id': _fid, 'секунд': _сек, 'когда': _now_msk(),
                       'вид': ('кружок' if getattr(update.message, 'video_note', None)
                               else 'видео')},
                      'приветственный ролик от владельца')
            await _мсообщ(update).reply_text(
                '🎬 Ролик принял и запомнил (%d сек). Теперь он уходит новичкам вместе с '
                'приветствием — сам файл я не храню, шлю по номеру у Telegram.\n'
                'Заменить — просто пришли другой.' % _сек)
            return
    except Exception:
        pass

    # 📸 СНИМОК ПРИВЕТСТВИЙ (ОБР-295/296). Сразу после входа человека приветственные боты
    # пишут свои посты, а через время удаляют. Пересылка их калечит — режет кнопки и
    # вложения, — и я на этом дважды показал владельцу не тот макет. Поэтому снимаем ЗДЕСЬ,
    # в момент появления: со ссылками, кнопками и признаком вложения.
    try:
        _лов = _ЛОВИМ_ПРИВЕТ.get(getattr(update.effective_chat, 'id', 0))
        if _лов and time.time() < _лов['до']:
            _от = getattr(update.effective_user, 'is_bot', False)
            # 🔴 ОБРАЩЕНИЕ ВЛАДЕЛЬЦА #409 (11.08.2026): «мои слова „ты хочешь…" как вообще
            # связаны? Я с человеком общаюсь другим, зачем ты это смс выделил».
            #
            # Он прав, и причина третья за день из одного корня. Снимок брал всё, что писали
            # БОТЫ в окне после входа. А когда владелец пишет от имени канала, отправителем
            # Telegram ставит служебного @Channel_Bot — и тот, разумеется, бот. Его личный
            # разговор с человеком попадал в снимок как «приветственный пост».
            # Признак различения тот же, что уже применён дважды сегодня: у сообщения от чата
            # или канала выставлено sender_chat. Настоящий приветственный бот пишет от себя,
            # без него.
            if getattr(update.message, 'sender_chat', None):
                _от = False
            _тк = (getattr(update.message, 'text', None)
                   or getattr(update.message, 'caption', None) or '')
            if _от and _тк:
                _кн = []
                _мк = getattr(update.message, 'reply_markup', None)
                for _ряд in (getattr(_мк, 'inline_keyboard', None) or []):
                    for _б in _ряд:
                        _кн.append('%s → %s' % (getattr(_б, 'text', ''),
                                                getattr(_б, 'url', '') or 'callback'))
                _лов['посты'].append({
                    # 🔴 #418: номер сообщения нужен, чтобы ПОСЛЕ бана убрать приветствия
                    # чужих ботов. Без него мы знаем, что они написали, но не знаем что убирать.
                    'смс': getattr(update.message, 'message_id', 0),
                    'чат': getattr(update.effective_chat, 'id', 0),
                    'кто': (getattr(update.effective_user, 'first_name', '') or '')[:40],
                    'текст': _тк[:1500], 'кнопки': _кн,
                    'вложение': bool(getattr(update.message, 'video', None)
                                     or getattr(update.message, 'photo', None)
                                     or getattr(update.message, 'animation', None)),
                    'сущности': [getattr(_э, 'type', '') for _э
                                 in (getattr(update.message, 'entities', None) or [])],
                })
        elif _лов:
            # окно закрылось — отдаём владельцу ровно то, что видели.
            # 🔴 ОБРАЩЕНИЕ #421 (11.08.2026): «ты удаляешь приветственное слово, но я сказал
            # удалять и двое других смс, которые приходят» — и показал приветствие бота-капчи
            # «нажмите кнопку ниже в течение 5 мин».
            # Причина, почему чужие не убирались: снимок ЗАБЫВАЛ всё, едва закрывалось окно в
            # 90 секунд. А банят через минуты — к тому времени номера чужих сообщений уже
            # стёрты, и убирать было нечего. Окно короткое правильно (боты здороваются сразу),
            # но ПАМЯТЬ для уборки нужна дольше самого окна. Держим её два часа: снимок
            # владельцу уже ушёл, остаются только номера.
            # ⚠️ Снимок отдаётся РОВНО ОДИН РАЗ. Раньше эту роль играло удаление записи:
            # отдали — забыли. Теперь запись живёт дальше (в ней номера для уборки), и без
            # отдельной пометки снимок уходил бы владельцу на КАЖДОЕ следующее сообщение в
            # чате — два часа подряд. Поймал это на себе, перечитав свою же правку: чинил
            # спам в чате и чуть не завёл спам в личке.
            _уже_отдан = bool(_лов.get('отдан'))
            _лов['до_уборки'] = time.time() + 7200
            _лов['отдан'] = True
            for _к, _з in list(_ЛОВИМ_ПРИВЕТ.items()):
                if _з.get('отдан') and time.time() > float(_з.get('до_уборки') or 0):
                    _ЛОВИМ_ПРИВЕТ.pop(_к, None)
            if _лов['посты'] and not _уже_отдан:
                _куски = ['📸 <b>СНИМОК ПРИВЕТСТВИЙ</b> — вошёл(ла) %s\n'
                          'Снято в момент появления: с кнопками и вложениями, как есть.'
                          % html.escape(_лов['кто'])]
                for _i, _п in enumerate(_лов['посты'], 1):
                    _куски.append(
                        '\n<b>Пост %d</b> (от «%s»%s)\n<pre>%s</pre>%s'
                        % (_i, html.escape(_п['кто']),
                           ', с вложением' if _п['вложение'] else '',
                           html.escape(_п['текст'][:900]),
                           ('\nкнопки: ' + html.escape('; '.join(_п['кнопки'])))
                           if _п['кнопки'] else '\nкнопок нет'))
                try:
                    await context.bot.send_message(OWNER_ID, '\n'.join(_куски)[:4000],
                                                   parse_mode='HTML',
                                                   disable_web_page_preview=True)
                except Exception:
                    pass
    except Exception:
        pass
    # 🔴 ЗОВ ТЕХНАДЗОРА ЛОВИТСЯ ПЕРВЫМ, ДО ВСЕХ ПРОЧИХ ПУТЕЙ.
    # 05.08.2026: владелец написал «передай технадзору…» — и ответил ему Groq: «я этого не
    # умею». Честно, но не по адресу: передать было некому, потому что до меня это не дошло.
    # Слово-ключ ловилось только внутри разбора помощника, то есть если разговор с ним уже
    # шёл. Обращение ко мне не должно зависеть от того, разговаривал ли владелец перед этим
    # с кем-то ещё: ключ есть — дверь открывается.
    # Ответил НА МОЁ сообщение — значит спрашивает меня, какими бы словами и когда бы то ни
    # было. 05.08.2026: это правило у меня уже было, но лежало ВНУТРИ разбора помощника — а
    # туда сообщение без слова DSOC не доходит. Правило работает не там, где записано, а там,
    # где проверяется. Поднимаю в самое начало.
    # Мерка «чьё это дело» — по СОДЕРЖАНИЮ. Заведена 26.08.2026 для продолжения разговора
    # по последнему голосу: там нет ни зова по имени, ни отметки ответом, и решает одно
    # время — из-за чего вопрос владельца помощнику попадал ко мне (он: «я тебя не звал»).
    # Признаки не новые: ровно те, что ниже описаны для ветки ответа (#116). Второй набор
    # завёл бы второе мнение о том же вопросе.
    def _чьё_дело(_т):
        _н = (_т or '').strip().lower()
        if not _н:
            return ''
        _моё = bool(re.search(
            r'клод|технадзор|разработчик|почини|исправ|сломал|не работает|не пашет|'
            r'выговор|прецедент|баг|ошибк|деплой|версия|обеспечь|научи|дай возможность|'
            r'закон|правило|промт|почему ты |разберись|настро', _н))
        _его = bool(re.search(
            r'\b(аят|коран|сура|хадис|карточк|цеп[ьи]|тахкик|переведи|перевод|'
            r'озвучь|голос|найди|поиск|скажи|расскажи|объясни|перескажи|'
            r'источник|мактаба|книг|слово|тахридж)', _н))
        if _моё:
            return 'клод'          # прямой зов и моя работа старше всего
        if _его:
            return 'помощник'
        return ''

    _мой_ли_ответ = False
    _ответ_сессии = ''          # #269/#271/#272: ответили сообщению ДРУГОЙ сессии — чьё оно
    _автор_ответа = ''
    try:
        if _хозяин(update) and update.message.reply_to_message:
            _цт = (getattr(update.message.reply_to_message, 'text', None)
                   or getattr(update.message.reply_to_message, 'caption', None) or '')
            # Спрашиваем РЕЕСТР, а не буквы: сообщение сессии могло уйти без подписи.
            _автор = автор_чей(getattr(update.effective_chat, 'id', 0),
                               update.message.reply_to_message.message_id, _цт)
            _автор_ответа = _автор or ''
            if _автор and _автор not in ('клод', 'помощник'):
                _ответ_сессии = _автор
            _мой_ли_ответ = (_автор == 'клод' or '🧠 Клод' in _цт
                             or 'Технадзор:' in _цт[:120]) and not re.match(
                r'^\s*(спасибо|благодарю|понял|поняла|ок|окей|ага|хорошо|принял|ясно|\+|👍)'
                r'\s*[!.)]*\s*$', (text or '').strip().lower())
            # 🔴 08.08.2026, обращение #116. Владелец: «я ранее говорил закон, что если я ответом
            # отвечаю технадзору, то это технадзору. Но ЭТО НЕ ПАНАЦЕЯ. Надо чтобы DSOC оценивал,
            # и если очевидно, что это не ему, — он не передаёт, а сам отвечает. Я могу сам
            # обратиться, если что. Очевидно, что я не технадзору хотел эту мелочь».
            # Повод: он ответил на мой пост словами «скинь рандомный аят без огласовок» — обычная
            # просьба, которую помощник выполняет за секунду. Вместо этого она ушла ко мне
            # обращением, и человек ждал технадзора ради одного аята.
            # Правило: ответ на моё сообщение — лишь ПРИЗНАК адресата, а не доказательство.
            # Ко мне идёт то, что умею только я: починки, поломки, возможности, прямой зов.
            # Всё остальное — работа помощника, и он берёт её сам.
            if _мой_ли_ответ:
                _т_ниже = (text or '').strip().lower()
                _ко_мне_явно = bool(re.search(
                    r'клод|технадзор|разработчик|почини|исправ|сломал|не работает|не пашет|'
                    r'выговор|прецедент|баг|ошибк|деплой|версия|обеспечь|научи|дай возможность|'
                    r'закон|правило|промт|почему он |почему ты |разберись', _т_ниже))
                # Просьба, которую помощник заведомо исполняет сам, — не мой хлеб.
                # ⚠️ Замыкающей границы \b тут БЫТЬ НЕ ДОЛЖНО: это основы, а не слова целиком.
                # С ней «карточку» не совпадало с «карточк» — за основой стоит буква, границы
                # нет, и просьба уходила ко мне. Та же ловушка, что с именами критиков сегодня.
                _его_дело = bool(re.search(
                    r'\b(аят|коран|сура|хадис|карточк|цеп[ьи]|тахкик|переведи|перевод|'
                    r'озвучь|голос|найди|поиск|скажи|расскажи|объясни|перескажи|'
                    r'источник|мактаба|книг|слово|тахридж)', _т_ниже))
                # 🔴 10.08.2026, обращение #262. Владелец: «Сделай что если я отвечаю тебе —
                # то тебе и идёт ответ». Это ОТМЕНЯЕТ смягчение из #116, где он же просил
                # не гонять ко мне мелочь и разрешил помощнику брать её самому.
                # Почему исполняю новое, а не спорю старым: он ответил на МОЙ пост про модели,
                # помощник счёл это своим делом и полез выяснять у него доступы к API — то есть
                # человек говорил со мной, а отвечал ему кто-то другой. Предсказуемость тут
                # дороже экономии: ответ на моё сообщение идёт мне, и точка.
                # Одно исключение оставлено, и оно его же: если он ЯВНО зовёт помощника по
                # имени («Ботяра, …»), это ему — иначе позвать помощника ответом на мой пост
                # стало бы невозможно вовсе.
                _зовёт_помощника_явно = bool(re.match(
                    r'^\s*(?:ботяр\w*|dsoc|дсос|помощник)\b', _т_ниже))
                if _зовёт_помощника_явно:
                    _мой_ли_ответ = False
    except Exception:
        _мой_ли_ответ = False

    # ─────────────────────────────────────────────────────────────────────────
    # 🔴 10.08.2026, обращения #269 / #271 / #272 / #274. ОТВЕТ СООБЩЕНИЮ ДРУГОЙ СЕССИИ.
    # Владелец: «почему ассистенту уходит смс, если я локалки выделил?» и «опять ассистент
    # отвечает вместо того, чтобы регистрацию написать обращения о том, что передаётся».
    # Здесь три требования разом, и все три исполняются в этом блоке:
    #   ① ответ уходит ТОЙ сессии, чьё сообщение он отметил, а не тому, кто первым увидел;
    #   ② у передачи есть НОМЕР — иначе «передаю» это слово, а не запись (обращение #273:
    #      «он говорит передаю, но не пишет номер обращения — значит он меня обманывает?»);
    #   ③ расписка приходит СРАЗУ, чтобы владелец не сидел в тишине и не гадал, дошло ли.
    # Помощник в этот разговор не вмешивается: ответ адресован не ему.
    #
    # 🔴 10.08.2026, обращение #353 («Локалки, че думаешь <ссылка>»). Оно легло в очередь
    # ТЕХНАДЗОРА, хотя владелец назвал адресата первым же словом. Разбор: адресат брался
    # только из ОТВЕТА на чьё-то сообщение, а из начала строки узнавались лишь «технадзор»
    # и «клод» — имена рабочих сессий там не значились вовсе. Он же обращается к ним ровно
    # так, как к людям: первым словом. Имя в начале СИЛЬНЕЕ того, кому он ответил: ответить
    # можно на любое подвернувшееся сообщение, а имя пишут осознанно.
    # 🔴 ДОПОЛНЕНО В ТОТ ЖЕ ВЕЧЕР, обращение #368 и разбор ОБР-359. Правило выше я сделал
    # только для «локалки» и «гермес» — и оно тут же не сработало там, где было нужнее всего.
    # Владелец ответил на сообщение сессии «Локалки», а написал «КЛОД, разберись с этим
    # прогревом». Обращение легло в очередь ЛОКАЛОК: имя в начале правило не узнавало, потому
    # что «клод» я в него не внёс — он ведь и так узнавался, но ДРУГОЙ веткой, которая до
    # этого места не доходит. Своё же имя и забыл.
    # Итог для человека: он спросил меня прямо, а через два часа услышал от меня «обращения
    # о прогреве у меня нет ни одного». Правдиво по моим данным и ложно по его вопросу.
    _зов_по_имени = ''
    try:
        _нач = re.match(r'^\s*(локалк\w*|гермес\w*|клод\w*|технадзор\w*)\b',
                        (text or '').strip().lower())
        if _нач:
            _сл = _нач.group(1)
            _зов_по_имени = ('локалки' if _сл.startswith('локалк') else
                             'гермес' if _сл.startswith('гермес') else 'клод')
            _ответ_сессии = _зов_по_имени
    except Exception:
        _зов_по_имени = ''
    if (text and _хозяин(update) and _ответ_сессии
            and not re.match(r'^\s*(?:ботяр\w*|dsoc|дсос|помощник)\b', (text or '').strip().lower())):
        try:
            _чид = getattr(update.effective_chat, 'id', 0)
            _рп = update.message.reply_to_message
            _звать = ПОДПИСИ_СЕССИЙ.get(_ответ_сессии, ('', _ответ_сессии, ''))[1]
            # Зов по имени приходит и БЕЗ ответа на чьё-то сообщение — тогда отмечать нечего.
            # Раньше здесь безусловно читалось `_рп.message_id`, и обращение без ответа
            # свалилось бы в `except` и пропало молча: владелец видит «принято» ни от кого.
            _отм_с = ({'смс': _рп.message_id, 'кто': _звать,
                       'текст': ((getattr(_рп, 'text', None)
                                  or getattr(_рп, 'caption', None) or '')[:1200])}
                      if _рп else {})
            _н = dsoc_позвать_клода(
                _чид, update.message.message_id, text.strip(),
                getattr(update.effective_user, 'first_name', ''),
                отмечено=_отм_с,
                кому=_ответ_сессии)
            # 🔴 17.08.2026. Владелец: «в джамаат ру тоже спам был». Он написал технадзору
            # четыре коротких сообщения подряд — и в чат на тысячу человек ушли ЧЕТЫРЕ
            # расписки «✅ Принято обращение ОБР-NNN…», каждая на пять строк, с пояснением,
            # почему отвечает сессия, а не помощник.
            # Расписка нужна: без неё непонятно, дошло ли слово. Но нужна ОДИН РАЗ на разговор,
            # а не на каждую реплику: со второй она перестаёт сообщать что-либо новое и
            # становится шумом. Пять строк пояснения тем более уместны только в первый раз.
            # Поэтому: первая расписка полная, следующие в течение десяти минут — одной
            # строкой, и только с номером, чтобы на обращение можно было сослаться.
            # #2542: окно тишины теперь общее для всех трёх мест — см. _расписка_принято.
            await _расписка_принято(update, (
                '✅ <b>Принято обращение %s</b> — %s\n'
                '%s\n\n'
                'Отвечает она, не помощник: %s\n'
                'В ответе она укажет, что это ответ на %s.'
                % (код_обращения(_н), _звать, _now_msk(),
                   ('ты назвал её по имени.' if _зов_по_имени
                    else 'ты ответил на её сообщение.'),
                   код_обращения(_н))), _н, _звать)
            await context.bot.send_message(
                LOG_CHAT_ID,
                '📨 <b>ВЛАДЕЛЕЦ %s СЕССИИ «%s»</b> (%s)\n%s'
                % ('ПОЗВАЛ' if _зов_по_имени else 'ОТВЕТИЛ',
                   _звать, код_обращения(_н), (text or '')[:900]), parse_mode='HTML')
        except Exception:
            pass
        return

    # 🔴 08.08.2026, обращение #129 («Клод это че?»). Владелец написал в чат:
    # «Ботяра, воспользуйся рагом Бухари и поищи Барзах. ЕСЛИ НЕ УМЕЕШЬ — запроси навык у
    # технадзора». Обращение было к ПОМОЩНИКУ, а ушло ко мне запиской «записал к сведению»:
    # сработало слово «технадзор» внутри условия.
    # Две поправки: ① позвали по имени помощника — значит это ему, чьё бы имя ни мелькнуло
    # дальше; ② «если не сможешь — обратись к технадзору» это УСЛОВИЕ на будущее, а не зов
    # сейчас. Зовут меня словами «передай технадзору» или обращением с самого начала.
    _зовут_помощника = bool(re.match(r'^\s*(?:ботяр\w*|dsoc|дсос|помощник)\b',
                                     (text or '').strip().lower()))
    _условный_зов = bool(re.search(r'если\s+(?:не|что)\b[^.!?]{0,60}'
                                   r'(?:технадзор|клод)', (text or '').lower()))
    if (text and _хозяин(update) and not _зовут_помощника and not _условный_зов
            and (_мой_ли_ответ or re.search(
                r'(передай|скажи|сообщи)\s+(технадзор|клод|разработчик)|'
                r'^\s*(технадзор|клод)\b', text.strip().lower()))):
        try:
            _чид = getattr(update.effective_chat, 'id', 0)
            _отм = {}
            _рп = update.message.reply_to_message
            if _рп:
                _отм = {'смс': _рп.message_id,
                        # #232: раньше клали ОБРЫВОК имени — по нему человеку не написать.
                        # Кладём его целиком, а называем одним общим правилом.
                        'кто': кто_с_id(getattr(_рп, 'from_user', None), вид='plain') or 'кто-то',
                        'текст': ((getattr(_рп, 'text', None)
                                   or getattr(_рп, 'caption', None) or '')[:1200])}
            # 🔴 З-103 (владелец 06.09.2026): «пропиши закон, что всегда учитывать —
            # если я ответил на какое-либо смс, на какое смс отвечаю».
            # Сюда мы попадаем, когда автора отвеченного сообщения определить НЕ УДАЛОСЬ
            # (реестр помнит последние 600 сообщений чата, подпись в тексте могла не
            # совпасть). Раньше письмо в этом случае молча уходило в линию «клод» — и
            # 06.09 так ко мне попал заказ, адресованный ЛОКАЛКАМ: он ВЫБИРАЛ адресата
            # ответом, а до получателя выбор не доехал.
            # Теперь неизвестность НАЗЫВАЕТСЯ. Получатель видит пометку и переспрашивает,
            # вместо того чтобы браться за чужое.
            _текст_обращения = text.strip()
            # 🔴 06.09.2026, 03:48, «Выговор». Метка кричала и на моё же сообщение:
            # ответ владельца мне даёт _ответ_сессии пустым НАМЕРЕННО (это и значит
            # «письмо идёт Клоду»), а я счёл пустоту незнанием. Пустое поле снова
            # оказалось двузначным: «не знаю чьё» и «моё» выглядели одинаково.
            # Тревога теперь только там, где реестр реально промолчал.
            if _отм and not _ответ_сессии and not _автор_ответа:
                _текст_обращения = ('⚠️ АДРЕСАТ НЕ ОПРЕДЕЛЁН: владелец ответил на сообщение, '
                                    'автора которого нет в реестре. Проверь, твоё ли это, '
                                    'и при сомнении ПЕРЕСПРОСИ.\n\n' + _текст_обращения)
            _н = dsoc_позвать_клода(_чид, update.message.message_id, _текст_обращения,
                                    getattr(update.effective_user, 'first_name', ''),
                                    отмечено=_отм)
            await context.bot.send_message(
                LOG_CHAT_ID,
                "📣 <b>ВЛАДЕЛЕЦ ЗОВЁТ ТЕХНАДЗОРА</b> (%s)\n%s\n"
                "Ответ ждут здесь: https://t.me/c/%s/%s"
                % (код_обращения(_н), text.strip()[:900], str(_чид).replace('-100', ''),
                   update.message.message_id), parse_mode='HTML',
                disable_web_page_preview=True)
            # #273/#275: расписка ВСЕГДА с номером, а если номера нет — прямо об этом.
            # «Передал» без номера непроверяемо, и владелец законно назвал это обманом.
            await _расписка_принято(update, (
                "✅ Принято обращение <b>%s</b> — технадзор Клод. Ответит прямо здесь и "
                "укажет, что это ответ на %s." % (код_обращения(_н), код_обращения(_н))),
                _н, 'технадзору')
        except Exception:
            pass
        return

    # 🔴🔴 ЗАСЛОН. Владелец 06.08.2026: «срочно, почему другие пользуются DSOC!!! Лимиты и
    # полномочия пока не готовы для других. Ты даже получил заявку от другого — то есть ты бы
    # дал доступ к Клоду».
    # ОН ПРАВ ДВАЖДЫ, И ВТОРОЕ СТРАШНЕЕ ПЕРВОГО.
    # Первое: DSOC ходит на ПЛАТНУЮ подписку владельца, и каждый чужой вопрос — его деньги.
    # В чате тысяча человек; достаточно одному написать «DSOC», чтобы повторили остальные.
    # Второе: помощник умеет ПОДАВАТЬ ЗАЯВКИ технадзору. Значит через него посторонний
    # человек мог поставить задачу тому, кто правит код приложения. Это уже не про деньги.
    # ПОЧЕМУ БЕЛЫЙ СПИСОК, А НЕ ЧЁРНЫЙ: чёрный запрещает известных, белый разрешает
    # названных. Когда речь о чужих деньгах и о доступе к разработке, единственный
    # правильный порядок — «нельзя всем, кроме», а не «можно всем, кроме»: в чёрный список
    # нельзя вписать того, кто ещё не появился.
    if parse_dsoc(text) is not None and not dsoc_рубильник():
        # Рубильник опущен: молчим для ВСЕХ, включая владельца — иначе это не рубильник,
        # а пожелание. Владельцу говорим, как поднять; чужим не отвечаем вовсе.
        if _хозяин(update):
            try:
                await _мсообщ(update).reply_text(
                    "🔴 Помощник ВЫКЛЮЧЕН рубильником. Поднять: напиши в рабочий журнал "
                    "или мне в личку «помощник вкл».")
            except Exception:
                pass
        return
    if parse_dsoc(text) is not None:
        _можно, _почему = dsoc_можно(update)
        if not _можно:
            try:
                _кто = update.effective_user
                _имя = кто_с_id(_кто, вид='html')   # #232: имя · @ник · нажимаемый номер
                await context.bot.send_message(
                    OWNER_ID,
                    ('🚫 <b>Не пустил к помощнику</b>' + '\\n\\n' +
                     '<b>Кто:</b> %s' + '\\n' +
                     '<b>Причина:</b> %s' + '\\n' +
                     '<b>Просил:</b> %s' + '\\n\\n' +
                     'Пустить: ответь на его сообщение словами <b>DSOC пусти</b>.' + '\\n' +
                     'Закрыть навсегда: <b>DSOC запрети</b>.')
                    % (_имя, _почему, (text or '')[:200]),
                    parse_mode='HTML')
            except Exception:
                pass
            # Человеку отвечаем вежливо и БЕЗ подробностей: чужому незачем знать
            # ни про списки, ни про подписку, ни про то, у кого просить.
            try:
                await _мсообщ(update).reply_text(
                    'Помощник пока отвечает не всем — идёт настройка. Спасибо за интерес.')
            except Exception:
                pass
            return

    # Владелец правит список прямо в разговоре: ответом на сообщение человека.
    if _хозяин(update) and update.message.reply_to_message is not None:
        # 🔴 08.08.2026, обращение #160: «научи его доступ давать сам, без тебя».
        # Раньше пустить человека можно было единственной формой «DSOC пусти» — и владелец,
        # который так не говорит, каждый раз звал меня. Слово «DSOC» тут лишнее: он отвечает
        # НА СООБЩЕНИЕ ЧЕЛОВЕКА, и это уже однозначно указывает, о ком речь.
        # Теперь понимаем и живую речь: «пусти его», «дай доступ», «допусти», «открой ему»,
        # «закрой», «запрети». Решение по-прежнему принимает ТОЛЬКО владелец и ТОЛЬКО ответом
        # на сообщение того человека — в делах доступа гадать по имени нельзя (П-05).
        _к = re.match(r'^\s*(?:(?:dsoc|дсос)\s+)?'
                      r'(пусти\w*|разреши\w*|допусти\w*|дай\s+доступ|открой\s+ему|открой\s+доступ|'
                      r'запрети\w*|закрой\w*|бань\w*|в\s*белый|в\s*чёрный|в\s*черный)',
                      (text or '').strip(), re.I)
        if _к:
            _ц = update.message.reply_to_message.from_user
            if _ц is None:
                await _мсообщ(update).reply_text('Не вижу, чьё это сообщение — у него нет автора.')
                return
            # 🔴 ОБРАЩЕНИЕ #651. Ответ указывает не всегда на человека. В чате сообщения
            # ходят ЧЕРЕЗ посредников: бот-пересыльщик, анонимный админ, публикация от имени
            # канала. Владелец ответил «Пусти его» человеку — а допуск ушёл боту
            # (@muslimoontt_bot, id 8848392178 в белом списке), человек же остался закрыт и
            # получал «пока отвечаю только владельцу». Обиднее всего, что бот при этом
            # бодро отрапортовал «✅ допущен» — то есть соврал не по злобе, а по невниманию.
            # Молча пускать посредника нельзя: список доступа — не место для догадок (П-05).
            _отвеч = update.message.reply_to_message
            if getattr(_отвеч, 'sender_chat', None) is not None:
                await _мсообщ(update).reply_text(
                    'Это сообщение опубликовано от имени чата или канала, живого человека за '
                    'ним не видно — впустить некого.\n\n'
                    'Назови его ником или номером: «пусти @ник».')
                return
            if getattr(_ц, 'is_bot', False):
                await _мсообщ(update).reply_text(
                    'Ответ указывает на бота (%s), а не на человека — его сообщение шло через '
                    'посредника. Впускать бота смысла нет.\n\n'
                    'Назови человека сам: «пусти @ник» — ник возьму у Telegram.'
                    % кто_с_id(_ц, вид='plain'))
                return
            _имя2 = кто_с_id(_ц, вид='plain')   # #232: имя · @ник · номер (тут разметки нет)
            # #650: ника может не быть вовсе. Пустота на его месте неотличима от «не
            # записали» — поэтому отсутствие пишем словом, чтобы список доступа читался
            # без догадок.
            if '@' not in _имя2:
                _имя2 += ' · ника нет'
            _слово = _к.group(1).lower().replace(' ', '')
            # ⚠️ РЕШАЕМ ПО НАЧАЛУ СЛОВА, А НЕ ПО ТОЧНОМУ СОВПАДЕНИЮ. Прежний список ждал ровно
            # «пусти»/«разреши»/«вбелый»; стоило добавить живые формы — и «дай доступ» упало бы
            # в ветку ИНАЧЕ, то есть ЗАБАНИЛО бы человека вместо того, чтобы впустить.
            # Ошибка молчаливая и обратная по смыслу: владелец сказал «пусти», человек закрыт.
            # Поэтому разрешающие слова перечислены явно, а всё неузнанное НЕ трогает списки
            # вовсе — в правах доступа догадка недопустима.
            _пускаем = _слово.startswith(('пусти', 'разреши', 'допусти', 'дайдоступ',
                                          'откройему', 'откройдоступ', 'вбелый'))
            _закрываем = _слово.startswith(('запрет', 'закр', 'бан', 'вчёрный', 'вчерный'))
            if not _пускаем and not _закрываем:
                await _мсообщ(update).reply_text(
                    'Не понял, впустить или закрыть. Скажи «пусти» или «запрети» — '
                    'ответом на сообщение человека.')
                return
            if _пускаем:
                _n = dsoc_белый_добавить(_ц.id, _имя2)
                await _мсообщ(update).reply_text(
                    '✅ %s допущен к помощнику. В белом списке: %d.' % (_имя2, _n))
            else:
                _n = dsoc_чёрный_добавить(_ц.id, _имя2)
                await _мсообщ(update).reply_text(
                    '⛔ %s закрыт. В чёрном списке: %d.' % (_имя2, _n))
            return

    # 🔴 КРАСНАЯ КНОПКА. Слово владельца в ЛЮБОМ его чате — в личке, в рабочем журнале.
    # Работает ДО всякого разбора: рубильник, до которого нельзя дотянуться в панике,
    # рубильником не является. Пишется коротко, чтобы набиралось одной рукой с телефона.
    if _хозяин(update) and text:
        _рб = re.match(r'^\s*(?:помощник|dsoc|дсос)\s*(выкл|откл|стоп|off|вкл|on)\s*(.*)$',
                       text.strip(), re.I | re.S)
        if _рб:
            _что = _рб.group(1).lower()
            _почему = (_рб.group(2) or '').strip()
            if _что in ('выкл', 'откл', 'стоп', 'off'):
                dsoc_рубильник_поставить(True, 'владелец', _почему)
                await _мсообщ(update).reply_text(
                    '🔴 ПОМОЩНИК ВЫКЛЮЧЕН. Не отвечает никому, включая тебя. '
                    'Деньги подписки больше не тратятся.' +
                    (chr(10) + 'Причина записана: ' + _почему if _почему else '') +
                    chr(10) + 'Поднять: «помощник вкл».')
            else:
                dsoc_рубильник_поставить(False, 'владелец', _почему)
                await _мсообщ(update).reply_text('🟢 Помощник включён и снова отвечает.')
            return

    # Списки — тоже словом, без захода в код: «помощник доступ» покажет, кто допущен.
    if _хозяин(update) and text and re.match(r'^\s*(?:помощник|dsoc|дсос)\s*доступ', text.strip(), re.I):
        _д = dsoc_доступ()
        _им = _д.get('имена') or {}
        def _строкой(_сп):
            return ', '.join('%s (%s)' % (_им.get(str(x), '?'), x) for x in _сп) or '— пусто'
        await _мсообщ(update).reply_text(
            ('🔑 ДОСТУП К ПОМОЩНИКУ' + chr(10) + chr(10) +
             'Состояние: %s' + chr(10) +
             'Белый список: %s' + chr(10) +
             'Чёрный список: %s' + chr(10) +
             'Разрешённые чаты: %s' + chr(10) + chr(10) +
             'Пустить человека: ответь на его сообщение «DSOC пусти».' + chr(10) +
             'Закрыть: «DSOC запрети». Выключить всё: «помощник выкл».')
            % ('🟢 работает' if dsoc_рубильник() else '🔴 ВЫКЛЮЧЕН рубильником',
               _строкой(_д.get('белый') or []), _строкой(_д.get('чёрный') or []),
               ', '.join(str(x) for x in (_д.get('чаты') or [])) or '— пусто'))
        return

    # 🔴🔴 07.08.2026, обращения #4, #30, #50, #66. «Не отвечай туда, где не просят».
    # Владелец сам назвал причину в #66: «это вызвано тем, что от канала ты воспринимаешь
    # на себя». Он прав, и вот механизм.
    # `is_owner()` считает владельцем и того, кто пишет ОТ ИМЕНИ ЕГО КАНАЛА (sender_chat ==
    # OWNER_CHANNEL_ID). Для полномочий это верно: опубликовал он. Но для вопроса «со мной ли
    # говорят» — неверно в корне. Пост в канале обращён к читателям, а не к боту.
    # Дальше срабатывало правило «разговор продолжается»: если помощник отвечал в этом чате
    # за последние 15 минут, любая реплика владельца идёт ему — а признаком «ко мне» служит
    # в том числе простой вопросительный знак. Канал, связанный с группой, сам роняет туда
    # каждый свой пост; в посте почти всегда есть «?». Итог: помощник влезал в чужой разговор
    # и отвечал публикации, которая его не звала.
    # Различаем: НАЗВАЛИ ПО ИМЕНИ из канала — отвечаем (владелец иногда пишет от канала
    # намеренно). Само по себе появление поста разговором с ботом не является НИКОГДА.
    def _из_канала(u):
        """Сообщение пришло публикацией канала, а не репликой человека в чате.

        🔴🔴 07.08.2026, 15:01, ИСПРАВЛЕНИЕ МОЕЙ ЖЕ РЕГРЕССИИ ЗА ЭТО УТРО.
        Утром (A-22) я закрыл помощнику ответы на посты канала — владелец сам показал, что
        беда идёт «от канала». Мерку я взял слишком широкую: ЛЮБОЙ чужой sender_chat.
        А владелец в чате джамаата пишет ОТ ИМЕНИ СВОЕГО КАНАЛА «MUSLIMOON» — и его
        собственные слова стали для помощника публикацией. Он перестал ему отвечать, и
        вместо него отзывался старый ИИ бота: «🤔 Думаю…», «ваше сообщение до меня не дошло»,
        а потом извинение за то, чего не делал. Владелец прислал это со словом «срочно».
        Я чинил одно и сломал соседнее — и сломал ровно то, ради чего чинил.

        Разница, которую надо было увидеть сразу:
        • `is_automatic_forward` — связанный канал САМ уронил свой пост в группу. Никто ни к
          кому не обращался. Это и есть публикация.
        • человек ВЫБРАЛ писать от имени канала — это его речь, просто под другим именем.
          Выбор написать и есть обращение.
        Мерим намерение, а не форму подписи.
        """
        try:
            м = u.message
            if getattr(м, 'is_automatic_forward', False):
                return True          # связанный канал уронил пост в группу обсуждения
            _sc = getattr(м, 'sender_chat', None)
            if not _sc:
                return False
            _ид = getattr(_sc, 'id', None)
            if _ид == getattr(u.effective_chat, 'id', None):
                return False         # анонимный админ — обычный человек
            if OWNER_CHANNEL_ID and _ид == OWNER_CHANNEL_ID:
                return False         # владелец пишет от своего канала — это ОН, а не публикация
            return True              # чужой канал — публикация
        except Exception:
            return False

    _публикация = _из_канала(update)

    _dsoc = parse_dsoc(text)
    # Первая половина слияния (владелец 05.08.2026: «нам ботяра зачем отдельно тогда?»):
    # у ВЛАДЕЛЬЦА слово «ботяра» ведёт к тому же помощнику — с памятью, полкой и вызовами.
    # Двух помощников с разными правилами быть не должно. Чужим бесплатный путь пока оставлен:
    # он их и обслуживает, и не тратит деньги владельца — второй шаг требует его слова.
    # 🔴 08.08.2026, обращение #158. Владелец впустил участника к помощнику — и написал:
    # «мы впустили его, а тот не реагирует, разберись».
    # Причина была здесь: слово «ботяра» вело к помощнику ТОЛЬКО у владельца, остальных
    # уводило на старый бесплатный путь. Оговорка «второй шаг требует его слова» стояла в
    # коде с 05.08 — и слово он теперь сказал, впустив человека поимённо.
    # Значит право говорить с помощником и обращение к нему по имени должны совпадать:
    # допустили человека — «ботяра» работает и у него. Иначе доступ есть на бумаге, а дверь
    # заперта, и человек стучится в тишину (ровно то, что он и увидел).
    if _dsoc is None and text and (_хозяин(update) or dsoc_можно(update)[0]):
        # 🔴 ОБРАЩЕНИЕ #497 (12.08.2026): «у него опять раздвоение. Уничтожь вторую личность»,
        # и показал: «Абу Дауд 203 нейротахкик дай ботяра» → в ответ «🤔 Думаю…», то есть
        # старый общий ИИ, у которого НЕТ ни нашей базы, ни вызовов, ни нейротахкика.
        #
        # Причина оказалась не в правах и не в моделях, а в ОДНОМ ЯКОРЕ РЕГУЛЯРКИ. Имя
        # искалось только В НАЧАЛЕ строки (`^\s*ботяра`), а человек говорит как человек:
        # «дай, ботяра», «ботяра, глянь», «Абу Дауд 203 … дай ботяра». Всё, где имя не первое
        # слово, проваливалось мимо помощника — и отзывалась вторая личность.
        #
        # Ищем имя ГДЕ УГОДНО и вырезаем его из просьбы: помощнику нужен вопрос, а не
        # обращение. Границы слова обязательны — иначе «ботярами» и подобное тоже поймается.
        _мб = re.search(r'(?<![\w])(ботяра|botyara)(?![\w])', text, re.I)
        if _мб:
            _без_имени = re.sub(r'(?<![\w])(ботяра|botyara)(?![\w])', ' ', text, flags=re.I)
            _без_имени = re.sub(r'\s*,\s*,\s*', ', ', _без_имени)   # «дай, ботяра, тахридж»
            _dsoc = re.sub(r'\s{2,}', ' ', _без_имени).strip(' ,:;—-')
    # 🔴 05.08.2026, владелец: «если смс отправил DSOC, то следующее взаимодействие с ним
    # как DSOC идёт». Он ответил на ответ ассистента обычным вопросом — и отозвался СТАРЫЙ
    # ИИ бота (Groq), потому что слова DSOC во втором сообщении не было.
    # Так и должно быть по-человечески: разговор ведут с тем, кто говорил, а не называют
    # собеседника по имени в каждой реплике. Узнаём свои ответы по подписи «— 🟩 DSOC».
    # 🔴 05.08.2026, владелец: «передай технадзору, чтобы другие модели не лезли в диалог».
    # Он разговаривает с помощником, а отвечает то Groq-«ботяра», то общий чат-ИИ — потому что
    # обращение узнавалось только по слову DSOC или по ответу на реплику помощника. Разговор
    # ведут с тем, кто говорил: если владелец только что беседовал с помощником в этом чате,
    # его следующая реплика — тоже помощнику, а не первому, кто откликнется.
    # Явные команды (ботяра, раг, найди хадис, коран, карточка) при этом работают как прежде:
    # человек назвал инструмент прямо, и подменять его выбор нельзя.
    if _dsoc is None and text and is_owner(update):
        try:
            _пос = dsoc_когда_отвечал(getattr(update.effective_chat, 'id', 0))
            _низт = text.strip().lower()
            _явно_другому = _низт.startswith(('ботяра', 'botyara', 'раг ', 'рag ', 'найди хадис',
                                              'коран', 'карточка', 'переведи', 'корень ',
                                              'видео', 'заявка', 'память', 'запомни',
                                              'анонс', '/', 'надзиратель', 'дипсик', 'напоминан', 'кнопки', 'правил',
                                              # «мульти» — своя команда (многократный ответ
                                              # с выбором), её обработчик стоит ниже; без
                                              # этой строки помощник перехватил бы слово
                                              # раньше и ответил обычным одиночным заходом.
                                              'мульти'))
            # 🔴 05.08.2026, владелец: «я тебя не звал, почему ты ответил?». Правило «15 минут
            # всё идёт помощнику» починило одно (чужие модели не влезают) и сломало другое:
            # он стал отвечать и на реплики В СТОРОНУ. Внутри окна он теперь отвечает, только
            # если обратились К НЕМУ: ответом на его сообщение, по имени, вопросом или прямой
            # просьбой. Замечание в сторону остаётся без ответа — молчание тоже бывает
            # правильным ответом.
            _к_нему = False
            try:
                _рп = update.message.reply_to_message
                _рт = ((getattr(_рп, 'text', None) or getattr(_рп, 'caption', None) or '')
                       if _рп else '')
                # 🔴 07.08.2026, поймано на живом отказе 13:16. Владелец ответил на ГОЛОСОВОЕ
                # помощника словами «Вот это голосом скинь» + ссылка — и ему отозвался старый
                # ИИ бота («🤔 Думаю…»), а не помощник.
                # Причина: «к нему ли обращаются» узнавалось по МЕТКЕ В ТЕКСТЕ («🟩 DSOC»,
                # «🧠 Клод»). А у голосового сообщения помощника подпись другая — «🔊 озвучено
                # синтезом · голос …», метки там нет и быть не может. Помощник заговорил
                # голосом — и перестал узнавать ответы самому себе.
                # Мерка была не та. Человеческое правило простое: отвечают ТОМУ, КТО СКАЗАЛ.
                # Смотрим не на текст, а на отправителя: ответил на сообщение бота — значит
                # обратился к нему, какими бы словами и в каком бы виде тот ни говорил.
                _от_бота = False
                try:
                    _ав = getattr(_рп, 'from_user', None) if _рп else None
                    _от_бота = bool(_ав and _ав.id == context.bot.id)
                except Exception:
                    _от_бота = False
                # 🔴 08.08.2026, обращение #113. Владелец кинул в чат ссылку на Instagram —
                # и помощник ей ОТВЕТИЛ, хотя к нему не обращались. Владелец: «пусть разберётся
                # с этим смс, я ведь не обратился к нему».
                # Причина смешная и оттого въедливая: признак «обращаются ко мне» считал
                # вопросительный знак в тексте, а в адресе стоит «?igsh=…». Помощник ответил
                # НА ЗНАК ИЗ ССЫЛКИ. Поэтому вопрос ищем в тексте БЕЗ адресов, а голая ссылка
                # без единого слова обращением не считается вовсе: человек делится, а не спрашивает.
                _без_ссылок = re.sub(r'https?://\S+|t\.me/\S+|www\.\S+', ' ', text or '')
                # «Голая» — значит НИ ОДНОГО слова кроме адреса. Порог «меньше двух» был
                # неверен: «перескажи <ссылка>» — это одно слово и полноценная просьба.
                _голая_ссылка = ('http' in (text or '') and not _без_ссылок.split())
                _к_нему = (not _голая_ссылка) and (
                    _от_бота
                    or '🟩 DSOC' in _рт or '🧠 Клод' in _рт
                    or '?' in _без_ссылок
                    or bool(re.search(r'\b(дай|найди|покажи|скажи|сделай|переведи|'
                                     r'объясни|расскажи|прочитай|прочти|озвучь|проверь|сравни|'
                                     r'перескажи|разбери|разберись|глянь|посмотри|о\s+чём|'
                                     r'вмешайся|убери|забудь|сожми|продолж|вот это|'
                                     r'это\s+голосом|голосом)',
                                     text.strip().lower())))
            except Exception:
                _к_нему = '?' in re.sub(r'https?://\S+', ' ', text or '')
            # `not _публикация` — см. разбор выше: пост канала не продолжает разговор.
            #
            # 🔴 08.08.2026, обращение #168: «технадзор, я его не звал». Помощник проснулся в
            # @jamaat_ru, когда владелец писал не ему. Правило «15 минут всё идёт помощнику»
            # рождалось для ЛИЧКИ, где второго собеседника нет, и молча растеклось на ГРУППУ,
            # где их десятки. В группе признак «обращаются ко мне» тут считал вопросительный
            # знак или глагол вроде «скажи» — а в общем чате вопрос чаще адресован людям, а не
            # боту. Отсюда и «я его не звал».
            # Закон владельца #162 сказан прямо: будит только имя либо ответ, шире не брать.
            # Поэтому окно оставляем ЛИЧКЕ, а в группе помощник просыпается лишь когда его
            # позвали по имени (ветка «ботяра» выше) или ответили на его сообщение (ниже).
            # Лишнее слово помощника в общем чате — не мелочь: там люди, и он влезает в чужой
            # разговор.
            _в_личке = getattr(update.effective_chat, 'type', '') == 'private'
            if (_в_личке and _пос and (time.time() - _пос) < 900 and not _явно_другому
                    and _к_нему and not _публикация):
                _dsoc = text.strip()
            # 🔴 07.08.2026, обращения #53 и #58 («раздвоение личности», «мы же убрали голые
            # ответы моделей — только ассистент отвечает, личность с обвязкой промтом»).
            # В ЛИЧКЕ владельца второй собеседник жив до сих пор: всё, что не команда, уходило
            # в ask_ai_with_memory — голую модель без промта, без полки, без вызовов. Владелец
            # это видел прямо: помощник здоровается «💬 DSOC думает…», а тут вдруг «🤔 Думаю…».
            # Два разных существа под одним именем — он и назвал это раздвоением.
            # В личке собеседник ОДИН, и по умолчанию это помощник; окно в 15 минут ему тут не
            # нужно — с кем ещё владелец разговаривает в своей личной переписке с ботом.
            # Явные команды (бухари 5590, коран 2:255, карточка …) при этом идут своим путём:
            # человек назвал инструмент прямо, подменять его выбор нельзя. Проверку «это
            # команда?» берём ТУ ЖЕ, что стоит ниже у старого ИИ, — чтобы два места не разошлись
            # в понимании того, что считать командой (З-33: не плодить вторую мерку).
            # 🔴 10.08.2026, обращение #301: «я тебе обращение направил, а этот бандит его
            # удержал. Обеспечь, чтобы не было такого».
            # ВОТ ЗДЕСЬ ОНО И УДЕРЖИВАЛОСЬ. Правило ниже говорит: в личке собеседник один, и
            # это помощник. Когда его писали, так и было. Сегодня в ту же личку пишут
            # технадзор и рабочие сессии — десятками сообщений, — и «собеседник один» стал
            # неправдой. Владелец продолжал разговор со мной обычной фразой, без обращения по
            # имени, и его слова забирал помощник: формально по правилу, а по сути — перехват.
            # Чиню тем же реестром авторства: по умолчанию отвечает ТОТ, КТО ГОВОРИЛ ПОСЛЕДНИМ.
            # Позвали помощника по имени — он и ответит; иначе продолжается начатый разговор.
            _пг = _ПОСЛЕДНИЙ_ГОЛОС.get(str(getattr(update.effective_chat, 'id', 0)) or '')
            _разговор_с_сессией = bool(
                _пг and _пг[0] and _пг[0] not in ('помощник',)
                and (time.time() - _пг[1]) < 45 * 60
                and not re.match(r'^\s*(?:ботяр\w*|dsoc|дсос|помощник)\b',
                                 (text or '').strip().lower())
                # 🔴 26.08.2026. Одного «я говорил последним» мало: сорок пять минут после
                # моего сообщения владелец мог писать о чём угодно, в том числе помощнику.
                # Так его вопрос про ИИ стал моим обращением, и он ответил: «Я тебя не звал».
                # Явное дело помощника не забираем, даже если последним говорил я.
                and _чьё_дело(text) != 'помощник')
            if (_dsoc is None and not _явно_другому and not _публикация
                    and not _разговор_с_сессией
                    and getattr(update.effective_chat, 'type', '') == 'private'
                    and not _это_команда_бота(text)):
                _dsoc = text.strip()
            elif _разговор_с_сессией and _dsoc is None and _хозяин(update) and text:
                # Продолжение разговора с сессией — записываем ей, с номером и распиской.
                _кому2 = _пг[0]
                _звать2 = ПОДПИСИ_СЕССИЙ.get(_кому2, ('', _кому2, ''))[1]
                _н2 = dsoc_позвать_клода(
                    getattr(update.effective_chat, 'id', 0), update.message.message_id,
                    text.strip(), getattr(update.effective_user, 'first_name', ''),
                    кому=_кому2)
                # #2542, ИМЕННО ЭТА ветка и двоила: владелец отвечает сессии (расписка выше),
                # пишет следом ещё раз — и сюда приходил полный текст заново, мимо окна тишины.
                await _расписка_принято(update, (
                    '✅ Принято обращение <b>%s</b> — %s.\n'
                    'Это продолжение разговора с ней: она говорила последней.\n'
                    'Нужен помощник — начни словом «Ботяра».'
                    % (код_обращения(_н2), _звать2)), _н2, _звать2)
                return
        except Exception:
            pass

    if _dsoc is None and text and not _публикация:
        try:
            _пред = update.message.reply_to_message
            _пт = (getattr(_пред, "text", None) or getattr(_пред, "caption", None) or "") if _пред else ""
            # 🔴 08.08.2026, З-40 (чинить класс, а не случай). Ровно эту беду разобрали 07.08
            # в ветке владельца выше: «к нему ли обращаются» узнавалось по МЕТКЕ В ТЕКСТЕ
            # («🟩 DSOC»), а у голосового ответа помощника подпись другая — метки там нет и
            # быть не может. Вывод тогда записали верный: отвечают ТОМУ, КТО СКАЗАЛ, значит
            # смотреть надо на отправителя, а не на текст. Но применили его в ОДНОМ месте, а
            # здесь — общая дверь для всех, включая участников чата, — осталась старая мерка.
            # То есть участник, ответивший на голосовое или картинку помощника, стучался в
            # тишину. Теперь и тут по отправителю.
            _ответ_боту = False
            try:
                _ав = getattr(_пред, 'from_user', None) if _пред else None
                _ответ_боту = bool(_ав and _ав.id == context.bot.id)
            except Exception:
                _ответ_боту = False
            if _ответ_боту or "🟩 DSOC" in _пт or "— 🟩" in _пт:
                _dsoc = text.strip()
        except Exception:
            pass
    if _dsoc is not None:
        # 🔴 05.08.2026, ошибка B-004: «cannot access local variable 'chat_id'».
        # Перенося блок наверх, я не заметил, что chat_id вычисляется НИЖЕ по ходу handle(),
        # и здесь его ещё нет. Питон в таких случаях не берёт глобальную переменную, а честно
        # падает: имя уже «занято» присваиванием ниже, значит оно местное и пока пустое.
        # Урок: перенося код, проверяй не только условия НАД ним, но и то, чем он пользуется —
        # переменные тоже имеют своё «место рождения».
        _chat = getattr(update.effective_chat, 'id', None)
        chat_id = _chat if _chat is not None else getattr(update.message.chat, 'id', 0)
        # Владелец ответил «да» на предложение DSOC подать заявку — подаём. Стоит ЗДЕСЬ, а не
        # выше: chat_id рождается строкой ранее, и обращаться к нему до этого нельзя (ошибка
        # B-004 уже была ровно об этом).
        if _dsoc and chat_id in DSOC_ЗАЯВКА_ЖДЁТ and _dsoc.strip().lower().rstrip("!.") in (
                "да", "давай", "передай", "подавай", "ага", "ок", "хорошо", "да, передай"):
            _куда, _текст = DSOC_ЗАЯВКА_ЖДЁТ.pop(chat_id)
            try:
                if _куда == "помощник":
                    _rid = dsoc_заявка_помощнику(_текст, "владелец")
                    await _мсообщ(update).reply_text(
                        "📓 Записал в журнал помощника — <b>%s</b>:\n%s"
                        % (код_помощнику(_rid), _текст), parse_mode='HTML')
                else:
                    _rid = req_add("🟩 [DSOC] " + _текст)
                    # Заявки мини-аппа исторически просто числа — их вид не меняем (#275),
                    # но называем ЯВНО «заявка приложения №», чтобы не слить с обращениями.
                    await _мсообщ(update).reply_text(
                        "📨 Передал технадзору — <b>заявка приложения №%d</b>:\n%s"
                        % (_rid, _текст), parse_mode='HTML')
            except Exception as _e:
                await _мсообщ(update).reply_text("🔴 Не смог записать: %s" % str(_e)[:150])
            return

        if not OPENCODE_KEY:
            await _мсообщ(update).reply_text(
                "🔑 Ключ OpenCode боту не выдан.\n"
                "Добавь на Railway переменную OPENCODE_ZEN_API_KEY и передеплой — "
                "и DSOC заработает.")
            return
        if not _dsoc:
            await _мсообщ(update).reply_text(
                "Я на связи. Пиши: DSOC <что сделать>.\n"
                "Помню весь наш разговор в этом чате (до миллиона токенов, дальше ужимаю сам).\n"
                "Ответом на любое сообщение — возьму его в работу вместе с вопросом.")
            return

        # 👁 ВЛОЖЕНИЯ: скриншот и файл — читаем ДО того, как думать.
        # Владелец общается скриншотами, это его главный способ показать проблему.
        # Помощник, который не видит скрин, отвечает на догадку о нём — и человек видит,
        # что с ним говорят мимо. Смотрим и в само сообщение, и в отмеченное ответом:
        # скрин чаще присылают ответом на него, а не подписью.
        _влож = []
        for _м in (update.message, update.message.reply_to_message):
            if _м is None:
                continue
            try:
                if getattr(_м, "photo", None):
                    _ф = await context.bot.get_file(_м.photo[-1].file_id)
                    _био = io.BytesIO()
                    await _ф.download_to_memory(out=_био)
                    _вид = await dsoc_глаза(_био.getvalue(), (_м.caption or "").strip())
                    if _вид:
                        _влож.append("=== ЧТО НА ПРИСЛАННОМ СКРИНШОТЕ ===" + chr(10) + _вид)
                    else:
                        _влож.append("(скриншот прислан, но прочитать его не вышло — "
                                     "зрячая модель недоступна)")
                _док = getattr(_м, "document", None)
                if _док is not None:
                    _ф2 = await context.bot.get_file(_док.file_id)
                    _био2 = io.BytesIO()
                    await _ф2.download_to_memory(out=_био2)
                    _имя2 = _док.file_name or "файл"
                    # Файл со звуком внутри — к ушам, остальное к рукам. Различаем и по имени,
                    # и по mime: Telegram у записи с телефона имени часто не даёт вовсе.
                    _мт = (getattr(_док, "mime_type", "") or "").lower()
                    if (os.path.splitext(_имя2)[1].lower() in DSOC_СЛЫШИМЫЕ
                            or _мт.startswith(("audio", "video"))):
                        _влож.append(await dsoc_уши(_био2.getvalue(), _имя2))
                    else:
                        _влож.append(await dsoc_руки(_био2.getvalue(), _имя2))
                # 🔴 Обращение #54. Запись, ПРИЛОЖЕННАЯ к вопросу помощнику (голосовое с
                # подписью, кружок, mp3, видео), до него не доходила вовсе: расшифровка жила
                # только в ветке «прислали голосовое ОТДЕЛЬНЫМ сообщением». Выходило, что
                # человек показал запись и спросил о ней, а помощник отвечал на один вопрос,
                # не подозревая, что рядом что-то лежит. Худший вид глухоты — незаметная.
                # ⚠️ У ТЕКУЩЕГО сообщения голосовое/аудио/кружок уже расшифрованы ВЫШЕ (там
                # из них сделан сам текст вопроса) — брать их сюда значит расшифровать второй
                # раз: лишний вызов Whisper и то же самое, сказанное в промте дважды.
                # Видео выше не разбирается вовсе, поэтому его берём и у текущего сообщения.
                if _м is update.message:
                    _зв = getattr(_м, "video", None)
                else:
                    _зв = (getattr(_м, "voice", None) or getattr(_м, "audio", None)
                           or getattr(_м, "video", None) or getattr(_м, "video_note", None))
                if _зв is not None:
                    _ф3 = await context.bot.get_file(_зв.file_id)
                    _био3 = io.BytesIO()
                    await _ф3.download_to_memory(out=_био3)
                    _имя3 = (getattr(_зв, "file_name", None)
                             or ("запись.mp4" if getattr(_м, "video", None)
                                                 or getattr(_м, "video_note", None)
                                 else "запись.ogg"))
                    _влож.append(await dsoc_уши(_био3.getvalue(), _имя3))
            except Exception as _ев:
                _влож.append("(вложение не открылось: %s)" % str(_ев)[:120])
        if _влож:
            # 🔴 23.08.2026, #634/#771/#1301: «что сказано в этой записи» → «не умею».
            # Когда разбор вложения не удавался, в промт уходило ИЗВИНЕНИЕ в скобках вместо
            # содержимого — и модель могла ответить только извинением. Человек читал это как
            # «бот не умеет», а помощник заносил себе дыру в умении, хотя умение есть и не
            # сработала конкретная дверь. Не зовём модель на пустоту: говорим причину сами.
            _вышло = [к for к in _влож if not _вложение_не_вышло(к)]
            if not _вышло:
                _беды = ' '.join((к or '').strip() for к in _влож)[:400]
                # 🔴 05.09.2026, владелец: «убери это смс, постоянно выплывает». Он прав:
                # файл больше двадцати мегабайт бот скачать не может — это предел самого
                # Телеграма, а не наша поломка. Кричать красным кружком о чужом правиле, да ещё
                # на каждый файл, — шум (З-82: красный кружок значит беду, а не «так устроено»).
                if 'too big' in _беды.lower() or 'слишком велик' in _беды.lower():
                    await _мсообщ(update).reply_text(
                        'Файл больше 20 МБ — столько Телеграм боту не отдаёт. '
                        'Пришлите покороче или расскажите словами.')
                else:
                    await _мсообщ(update).reply_text(
                        '🔴 Вложение до меня дошло, а разобрать его не вышло: %s'
                        % (_беды or 'причина неизвестна'))
                return
            # Модель ДОЛЖНА знать, что слушать и смотреть ей не нужно: содержимое уже извлечено.
            # Без этой строки она, увидев слова «запись» и «видео», нередко начинает с оговорки
            # «я не умею работать со звуком» — и правда обращается в свою противоположность.
            _шапка = ('=== ВЛОЖЕНИЯ УЖЕ РАЗОБРАНЫ ЗА ТЕБЯ ===' + chr(10)
                      + 'Ниже — готовая расшифровка звука и описание кадров. Слушать и '
                        'смотреть тебе не нужно и нечем: работай с этим текстом как с '
                        'обычным. НЕ пиши, что не умеешь работать со звуком или видео — '
                        'это неправда, разбор уже сделан.' + chr(10))
            _dsoc = (_шапка + chr(10) + chr(10).join(_вышло) + chr(10) + chr(10)
                     + "=== ЧЕЛОВЕК ПРОСИТ ===" + chr(10) + _dsoc)

        # 🧩 «ВМЕШАЙСЯ В ДИАЛОГ» — восстановить нить вокруг отмеченного сообщения.
        if re.search(r'вмеша|вмеща|разбери\s+диалог|что тут происходит', _dsoc.lower()):
            _пред = update.message.reply_to_message
            if not _пред:
                await _мсообщ(update).reply_text(
                    "🧩 Отметь сообщение, в диалог вокруг которого нужно вмешаться, — иначе я не "
                    "знаю, о каком разговоре речь. В чате их идёт несколько сразу.")
                return
            глубже = bool(re.search(r'глубже|подробн|шире', _dsoc.lower()))
            окно = лента_окно(chat_id, _пред.message_id, 15 if глубже else 5)
            # 🔴 ВЫГОВОР ВЛАДЕЛЬЦА 06.08.2026. Здесь бот отказывался работать словами
            # «соседних сообщений у меня нет, это сообщение старше моей ленты» — и был НЕПРАВ.
            # Владелец ОТМЕТИЛ сообщение ответом, а Telegram кладёт отмеченное прямо в запрос,
            # в reply_to_message. Текст был у бота В РУКАХ: он держал его и одновременно
            # говорил, что у него ничего нет, — потому что смотрел только в свою ленту и не
            # заглянул в то, что ему подали.
            # ПРАВИЛО: сперва берём пришедшее ВМЕСТЕ С ЗАПРОСОМ, потом достраиваем лентой.
            # Отказывать можно, только когда текста нет НИГДЕ.
            def _взять_текст(м):
                if not м:
                    return ''
                т = (getattr(м, 'text', None) or getattr(м, 'caption', None) or '').strip()
                if not т and getattr(м, 'voice', None):
                    т = '(голосовое сообщение)'
                return т

            подано, _цепь, _ш = [], _пред, 0
            while _цепь is not None and _ш < 4:      # ответ на ответ — тоже нить разговора
                _т = _взять_текст(_цепь)
                if _т:
                    try:
                        _а = _цепь.from_user
                        _кто = (_а.first_name or _а.username or '?') if _а else 'канал'
                    except Exception:
                        _кто = '?'
                    if getattr(_цепь, 'forward_origin', None) is not None:
                        _кто += ' (переслано)'
                    подано.insert(0, {'i': _цепь.message_id, 'кто': _кто, 'т': _т})
                _цепь = getattr(_цепь, 'reply_to_message', None)
                _ш += 1

            if подано:
                _ид = set(з['i'] for з in подано)
                окно = подано + [з for з in (окно or []) if з.get('i') not in _ид]

            if not окно:
                await _мсообщ(update).reply_text(
                    '🧩 В отмеченном сообщении нет текста, который я мог бы разобрать — '
                    'ни подписи, ни цитаты. Пришли текстом или отметь сообщение с текстом.')
                return
            свод = полка_взять('ПОЛКА-18') or '(свод правил ещё не заведён)'
            беседа = "\n".join("[%s] %s: %s" % (з['i'], з['кто'], з['т']) for з in окно)
            задача = (
                "ВМЕШАЙСЯ В ДИАЛОГ. Вот кусок беседы из чата; отмеченное сообщение — №%s.\n\n"
                "%s\n\n=== СВОД ПРАВИЛ ПРОЕКТА ===\n%s\n\n"
                "Сделай ровно четыре вещи, каждую с заголовком:\n"
                "1. О ЧЁМ РАЗГОВОР — в двух предложениях, чтобы человек понял без чтения.\n"
                "2. СВЕРКА С ПРАВИЛАМИ — что здесь сказано согласно своду, а что ему "
                "противоречит. Ссылайся на конкретное правило.\n"
                "3. ОЦЕНКА — по существу: где верно, где ошибка, чего не хватает. Без "
                "вежливого тумана.\n"
                "4. ЧЕГО НЕТ В СВОДЕ — если разговор вскрыл правило, которого в своде нет, "
                "сформулируй его одной строкой. Нечего добавить — так и скажи.\n"
                % (_пред.message_id, dsoc_обезличить(беседа)[:9000], свод[:4000]))
            реплики = dsoc_память(chat_id)
            реплики.append({"role": "user", "content": задача})
            _ст = await update.message.reply_text("🧩 Восстанавливаю диалог (%d сообщений)…"
                                                  % len(окно))
            ответ, _вх, _вых = await asyncio.get_event_loop().run_in_executor(
                None, dsoc_запрос,
                [{"role": "system", "content": dsoc_системный()}] + dsoc_чистые(реплики[-40:]))
            if not ответ:
                await _ст.edit_text("🧩 Не вышло разобрать — модель промолчала.")
                await dsoc_неудача(context.bot, chat_id, _dsoc, '', 'вмешательство: пустой ответ')
                return
            реплики.append({"role": "assistant", "content": ответ, "t": time.time()})
            DSOC_ПАМЯТЬ[chat_id] = реплики
            dsoc_сохранить(силой=True)
            dsoc_расход_записать(dsoc_стоимость(_вх, _вых))
            _кл = "%d_%d" % (chat_id, int(time.time()))
            try:
                _сн = _data_get(DSOC_СНИМКИ_ФАЙЛ, {}) or {}
                _сн[_кл] = list(реплики)[-160:]
                _data_put(DSOC_СНИМКИ_ФАЙЛ, {k: v for k, v in list(_сн.items())[-8:]},
                          'снимок перед решением о контексте')
            except Exception:
                pass
            _хвост = ("\n\n<blockquote expandable>вход %d · выход %d ток · %s</blockquote>"
                      % (_вх, _вых, dsoc_остаток_строкой()))
            try:
                await _ст.edit_text(dsoc_в_html(ответ[:3300]) + _хвост, parse_mode='HTML',
                                    disable_web_page_preview=True)
            except Exception:
                await _ст.edit_text(ответ[:3800])
            # Судьба контекста — решает владелец, а не я за него.
            await _мсообщ(update).reply_text(
                "🧩 Что сделать с этим разбором в памяти разговора?",
                reply_markup=_КЛ([[_КБ("💾 Сохранить", callback_data="ctx:keep:" + _кл),
                                   _КБ("🗜 Сжать", callback_data="ctx:squeeze:" + _кл),
                                   _КБ("✂️ Убрать", callback_data="ctx:drop:" + _кл)]]))
            return

        # ✂️ ТОЧЕЧНАЯ ЧИСТКА КОНТЕКСТА ПО ОТМЕЧЕННОМУ СООБЩЕНИЮ.
        # Заявка владельца, потерянная 05.08.2026 (её «приняла» Gemini и никому не передала):
        # «уметь вмешиваться в диалог по выделенному сообщению… и предлагать удаление его
        # части». Показать пальцем проще, чем описывать словами, что именно выкинуть.
        if is_owner(update) and re.search(
                r'(убери|удали|выкинь|забудь)\b.*(контекст|это|эту|отсюда)|^забудь это$',
                _dsoc.strip().lower()):
            реплики = dsoc_память(chat_id)
            снимок = list(реплики)
            убрано, что_убрал = 0, ''
            _пред = update.message.reply_to_message
            _цель = ((getattr(_пред, 'text', None) or getattr(_пред, 'caption', None) or '')
                     if _пред else '')
            if _цель:
                # Отмеченное сообщение: ищем его в памяти по началу текста — совпадения
                # «слово в слово» не будет, у ответов помощника снизу приклеена подпись.
                ключ = ' '.join(_цель.split())[:60]
                новые = [р for р in реплики
                         if ключ and ключ not in ' '.join((р.get('content') or '').split())]
                убрано = len(реплики) - len(новые)
                что_убрал = 'отмеченное сообщение'
                реплики = новые
            else:
                if len(реплики) >= 2:
                    реплики = реплики[:-2]
                    убрано, что_убрал = 2, 'последняя пара «вопрос-ответ»'
            if not убрано:
                await _мсообщ(update).reply_text(
                    "🤔 Не нашёл этого в памяти разговора — возможно, оно туда и не попадало. "
                    "Отметь именно ту реплику, которую надо выкинуть.")
                return
            DSOC_ПАМЯТЬ[chat_id] = реплики
            dsoc_сохранить(силой=True)
            try:
                _кл = "%d_%d" % (chat_id, int(time.time()))
                _сн = _data_get(DSOC_СНИМКИ_ФАЙЛ, {}) or {}
                _сн[_кл] = снимок[-160:]
                _data_put(DSOC_СНИМКИ_ФАЙЛ, {k: v for k, v in list(_сн.items())[-8:]},
                          "снимок перед точечной чисткой")
                await _мсообщ(update).reply_text(
                    "✂️ Убрал из памяти разговора: %s (%d реплик).\n"
                    "Осталось %d токенов переписки. Забытое не вернуть иначе — держи кнопку."
                    % (что_убрал, убрано, dsoc_размер(реплики)),
                    reply_markup=_КЛ([[_КБ("↩️ Вернуть как было",
                                           callback_data="dsocback:" + _кл)]]))
            except Exception:
                await _мсообщ(update).reply_text("✂️ Убрал: %s (%d реплик)." % (что_убрал, убрано))
            return

        # Владелец пометил ответ помощника неудачным — записываем с цитатой того ответа.
        if is_owner(update) and _dsoc.strip().lower().rstrip('!.') in (
                'неудача', 'не то', 'плохой ответ', 'мимо', 'не ответил'):
            _пред = update.message.reply_to_message
            _цитата = (getattr(_пред, 'text', None) or getattr(_пред, 'caption', None) or '') if _пред else ''
            _н = await dsoc_неудача(context.bot, chat_id, '(помечено владельцем вручную)',
                                    _цитата, 'владелец: ответ не годится')
            await _мсообщ(update).reply_text(
                "🔻 Записал как неудачу №%s — с цитатой того ответа. Разберу и превращу в "
                "знание, правку или выговор." % _н)
            return

        # ⚡ ОПЕРАТИВНЫЙ КАНАЛ: владелец через помощника зовёт живого технадзора.
        # Срабатывает по ПРЯМОМУ слову, а не по догадке — иначе обычные вопросы утонут в очереди.
        # 🔴 16.08.2026, ОБР-657. Владелец прислал голосовое и попросил «объясни по русски
        # че тут» — и это подняло технадзора обращением «срочно». В его просьбе нет ни одного
        # тревожного слова. Сработало слово ВНУТРИ РАСШИФРОВКИ: «этот вопрос неправильно
        # стоит» → «неправ». Расшифровка вложения подставляется в _dsoc выше (блок «=== ЧЕЛОВЕК
        # ПРОСИТ ===»), и признак срочности мерился по ней заодно с просьбой.
        # Это не мелочь: так любая запись, где кто-то сказал «ошибка», «почему», «передай»,
        # «не работает», заводит мне срочное обращение из ничего, а настоящий зов тонет среди
        # них. Судим по СЛОВАМ ВЛАДЕЛЬЦА, а не по содержимому того, о чём он спрашивает:
        # прислать чужую запись со словом «ошибка» — не значит позвать технадзора.
        _его_слова = _dsoc
        _метка_просьбы = '=== ЧЕЛОВЕК ПРОСИТ ===' + chr(10)
        if _метка_просьбы in _его_слова:
            _его_слова = _его_слова.split(_метка_просьбы, 1)[1]
        _низ_зов = _его_слова.lower()
        _прямо = any(_низ_зов.startswith(с) or (' ' + с + ' ') in (' ' + _низ_зов + ' ')
                     for с in DSOC_ЗОВ_КЛОДА)
        _тревожно = any(с in _низ_зов for с in DSOC_ПРИЗНАКИ_СРОЧНОГО)
        # Ответ НА СООБЩЕНИЕ ТЕХНАДЗОРА — обращение к нему. Ответить на чью-то реплику —
        # обычный способ обратиться именно к нему; требовать при этом ещё и назвать его по
        # имени значит выдумывать обряд на ровном месте.
        # Оговорка владельца принята: не всякий ответ есть просьба. Короткая вежливость
        # («спасибо», «понял», «ок») зовом не считается — дёргать по ней живого человека
        # незачем. Ошибка здесь дёшева в одну сторону и дорога в другую: лишний зов стоит мне
        # строки в ленте, пропущенный — молчания в ответ на просьбу.
        try:
            _цель = update.message.reply_to_message
            _цт = ((getattr(_цель, 'text', None) or getattr(_цель, 'caption', None) or '')
                   if _цель else '')
            if ('🧠 Клод' in _цт or 'Технадзор' in _цт[:80]) and not re.match(
                    r'^\s*(спасибо|благодарю|понял|поняла|ок|окей|ага|хорошо|принял|ясно|'
                    r'отлично|супер|👍|\+)\s*[!.)]*\s*$', _низ_зов):
                _прямо = True
        except Exception:
            pass
        if is_owner(update) and (_прямо or _тревожно):
            _отм = {}
            try:
                _р = update.message.reply_to_message
                if _р:
                    _отм = {'смс': _р.message_id,
                            'кто': кто_с_id(getattr(_р, 'from_user', None), вид='plain') or 'кто-то',   # #232
                            'текст': ((getattr(_р, 'text', None)
                                       or getattr(_р, 'caption', None) or '')[:1200])}
            except Exception:
                _отм = {}
            _н = dsoc_позвать_клода(chat_id, update.message.message_id, _dsoc,
                                    getattr(update.effective_user, 'first_name', ''),
                                    отмечено=_отм)
            try:
                await context.bot.send_message(
                    LOG_CHAT_ID,
                    "📣 <b>ВЛАДЕЛЕЦ ЗОВЁТ ТЕХНАДЗОРА</b> (обращение #%s)\n%s\n%s\n"
                    "Ответ ждут здесь: https://t.me/c/%s/%s"
                    % (_н, (_dsoc or '')[:900],
                       ("\n<b>Отмечено им:</b> «%s» — %s\nhttps://t.me/c/%s/%s\n"
                        % ((_отм.get('текст') or '')[:400].replace('<', '&lt;'),
                           (_отм.get('кто') or '').replace('<', '&lt;'), str(chat_id).replace('-100', ''),
                           _отм.get('смс'))) if _отм.get('текст') else '',
                       str(chat_id).replace('-100', ''), update.message.message_id),
                    parse_mode='HTML', disable_web_page_preview=True)
            except Exception:
                pass
            if _прямо:
                _расписка = ("📣 Передал технадзору — обращение #%s. Он ответит прямо здесь, "
                             "ответом на это сообщение." % _н)
                await _мсообщ(update).reply_text(_расписка)
                # Спросил голосом — и расписку слышит голосом. Правило владельца «отвечаю
                # голосом по умолчанию» относится ко ВСЕМ ответам, а не только к длинным:
                # ранние ветки молчали, и выходило, будто правило работает через раз.
                if _голосом_просили or голос_режим_включён(chat_id):
                    await сказать_голосом(update, _расписка, context)
                return
            # Тревожный признак без прямого зова: technadzor уведомлён, но разговор НЕ обрываем —
            # помощник отвечает как обычно. Иначе на каждое «почему» человек получал бы вместо
            # ответа расписку о передаче.


        # 🟡 К СВЕДЕНИЮ: всё остальное, что владелец пишет помощнику, я тоже вижу — но
        # отвечать не обязан. Пока настраиваем, полная видимость дороже тишины.
        # 🔴 05.08.2026, владелец: «это баг какой-то, ты делаешь какой к сведению, это что?»
        # Он спросил помощника про хадис — и получил канцелярскую расписку вместо ответа.
        # Расписку я приделал ко ВСЕМУ, что он пишет, а надо было — только к тому, что
        # адресовано МНЕ. Обычный вопрос помощнику не моё дело, лезть туда с номерком незачем.
        _мне_ли = bool(re.search(r'технадзор|клод|разработчик|передай|исправ|почему не|баг|'
                                 r'не работает|сломал', _низ_зов))
        if is_owner(update) and _мне_ли and not (_прямо or _тревожно):
            try:
                _нс = dsoc_позвать_клода(chat_id, update.message.message_id, _dsoc,
                                         getattr(update.effective_user, 'first_name', ''),
                                         важность="к сведению")
                # 🔴 05.08.2026, владелец: «ты должен такие вещи регистрировать как обращения
                # же, с номером?» Он прав: раньше «к сведению» уходило ко мне молча, и со
                # стороны это выглядело так, будто сказанное пропало. Номер видят оба — и он,
                # и я; спросить «а что с номером таким-то» теперь можно про ЛЮБОЕ его слово.
                if _нс:
                    await _мсообщ(update).reply_text(
                        "📝 Записал технадзору к сведению — №%s (ответа не требует)." % _нс)
            except Exception:
                pass

        реплики = dsoc_память(chat_id)
        # Ответил на чьё-то сообщение — оно идёт в дело вместе с вопросом. Владелец:
        # «могу также ему добавить, отметив ответом, другое чужое смс — и он учитывает».
        цитата = ""
        try:
            r = update.message.reply_to_message
            если_текст = (getattr(r, "text", None) or getattr(r, "caption", None)) if r else None
            if если_текст:
                кто = (getattr(getattr(r, "from_user", None), "first_name", "") or "кто-то")
                # Сообщение технадзора — не реплика собеседника, а УКАЗАНИЕ. Владелец просил
                # различать это прямо: «бот должен квалифицировать смс от технадзора как
                # прямое обращение». Иначе помощник обсуждает указание вместо того, чтобы его
                # исполнять.
                if "🧠 Клод" in если_текст or "Технадзор" in если_текст[:80]:
                    цитата = ("\n\n[УКАЗАНИЕ ТЕХНАДЗОРА — это не мнение собеседника, а как "
                              "поступать. Прими к исполнению, не спорь и не пересказывай]:\n%s"
                              % если_текст[:4000])
                else:
                    цитата = "\n\n[Сообщение, на которое отвечают — от %s]:\n%s" % (кто, если_текст[:4000])
        except Exception:
            pass

        реплики.append({"role": "user", "content": _dsoc + цитата})
        if dsoc_размер(реплики) > DSOC_СЖИМАТЬ_ОТ:
            # Владелец: «удаление части точно ненужного контекста автоматом — дело хорошее, но
            # тогда мне в рабочий журнал должно приходить уведомление с кнопкой, если надо
            # вернуть обратно». Он прав: автоматика хороша ровно до тех пор, пока она на глазах
            # и обратима. Молча ужимать чужую память — то же, что молча выбрасывать чужие бумаги.
            _до = dsoc_размер(реплики)
            _снимок = list(реплики)
            реплики = dsoc_ужать(реплики)
            DSOC_ПАМЯТЬ[chat_id] = реплики
            # #125: сжатие — это ПОТЕРЯ, а не рутина. Владельцу в личку и в рабочий журнал,
            # не в архивный чат: про убавление надо знать сразу, а не когда заглянешь.
            try:
                await журнал_контекста(
                    context.bot, "сжата память разговора в чате %s" % chat_id,
                    "было %d токенов, стало %d — ужато %d"
                    % (_до, dsoc_размер(реплики), _до - dsoc_размер(реплики)),
                    убыло=True, почему="набралось больше %d токенов" % DSOC_СЖИМАТЬ_ОТ)
            except Exception:
                pass
            try:
                _кл = "%d_%d" % (chat_id, int(time.time()))
                _сн = _data_get(DSOC_СНИМКИ_ФАЙЛ, {}) or {}
                _сн[_кл] = _снимок[-160:]
                _data_put(DSOC_СНИМКИ_ФАЙЛ, {k: v for k, v in list(_сн.items())[-8:]},
                          "снимок памяти до сжатия")
                await context.bot.send_message(
                    LOG_CHAT_ID,
                    "🗜 <b>Разговор помощника сжат</b>\n"
                    "было %d ток → стало %d ток (свернул середину, начало и последние реплики "
                    "целы).\nЕсли свернулось нужное — верну целиком одной кнопкой."
                    % (_до, dsoc_размер(реплики)),
                    parse_mode="HTML",
                    reply_markup=_КЛ([[_КБ("↩️ Вернуть как было",
                                           callback_data="dsocback:" + _кл)]]))
            except Exception:
                pass

        # Пустое сообщение, которое будем ДОПИСЫВАТЬ на глазах — владелец просил, чтобы
        # было видно, как набирается ответ, а не ждать молча.
        # 🔴🔴🔴 ЕДИНСТВЕННАЯ ДВЕРЬ. Владелец 11:18: «ты не сделал, он отвечает всем!!!»
        # Он прав. Мой первый заслон стоял на слове «DSOC» — а в помощника ведёт ЕЩЁ ОДИН путь:
        # ответ на его же сообщение. Кто угодно отвечает боту — и разговор идёт, слова «DSOC»
        # там нет. Я закрыл одну калитку и доложил, что двор заперт.
        # УРОК ТОТ ЖЕ, ЧТО С ФИЛЬТРОМ СЕКРЕТОВ УТРОМ: проверку ставят не на входах, которых
        # много и о которых легко забыть, а в ЕДИНСТВЕННОМ месте, через которое проходит всё.
        # Здесь такое место — прямо перед обращением к платной модели.
        if not dsoc_рубильник():
            if _хозяин(update):
                try:
                    await _мсообщ(update).reply_text('🔴 Помощник выключен рубильником. Поднять: «помощник вкл».')
                except Exception:
                    pass
            return
        _можно_дальше, _пч = dsoc_можно(update)
        if not _можно_дальше:
            # 🔴 06.08.2026, владелец: «в джамаате ассистент — там бардак».
            # Заслон я поставил верно, а вот ОТКАЗ сделал болтливым: он срабатывал на КАЖДОЕ
            # обращение. Один человек пишет пять раз — пять отказов ему в ленту и пять
            # уведомлений «🚫 Не пустил» владельцу в личку. Причём приманку создал я сам:
            # мой пост от лица бота собрал ответы, а ответ боту — это тоже путь к помощнику.
            # Отказ — сообщение ОДНОРАЗОВОЕ по смыслу: человеку сказали «пока нельзя», он
            # это услышал. Повторять то же самое на каждую реплику — не вежливость, а шум,
            # и в общем чате он раздражает сильнее самого запрета.
            # Держим час: один отказ человеку и одно уведомление владельцу, дальше молчим.
            _ид_к = getattr(update.effective_user, 'id', 0) or 0
            _тепер = time.time()
            _молч = DSOC_ОТКАЗ_СКАЗАН.get(_ид_к, 0)
            if _тепер - _молч < DSOC_ОТКАЗ_МОЛЧАТЬ:
                return
            DSOC_ОТКАЗ_СКАЗАН[_ид_к] = _тепер
            try:
                _кт = update.effective_user
                _им = кто_с_id(_кт, вид='html')   # #232: имя · @ник · нажимаемый номер
                await context.bot.send_message(
                    OWNER_ID,
                    ('🚫 <b>Не пустил к помощнику</b>' + chr(10) + chr(10) +
                     '<b>Кто:</b> %s' + chr(10) +
                     '<b>Причина:</b> %s' + chr(10) +
                     '<b>Просил:</b> %s' + chr(10) + chr(10) +
                     'Пустить: ответь на его сообщение «DSOC пусти».')
                    % (_им, _пч, (text or '')[:200]),
                    parse_mode='HTML')
            except Exception:
                pass
            # 🔴 25.08.2026. ЗАМЕЧАНИЕ ПРИНИМАЕМ ОТ ЛЮБОГО, даже когда к помощнику не пускаем.
            # Повод: участник группы принёс разбор настоящего дефекта («косой танвин заменяется
            # на круг, аят 2:2»), а бот ответил ему «спасибо за интерес» и отправил восвояси.
            # Замечание оказалось верным. Доступ к ИИ — по разрешению, но отчёт о поломке от
            # этого отчётом быть не перестаёт: его надо принять, передать и сказать человеку
            # правду. Указ владельца ОБР-1520/1523.
            _это_замечание = False
            try:
                _это_замечание = _похоже_на_замечание(text)
            except Exception:
                _это_замечание = False
            if _это_замечание:
                try:
                    await context.bot.send_message(
                        OWNER_ID,
                        ('💡 <b>ЗАМЕЧАНИЕ ОТ ПОСТОРОННЕГО</b> — принято, не отшито'
                         + chr(10) + chr(10) +
                         '<b>Кто:</b> %s' + chr(10) +
                         '<b>Дословно:</b> %s' + chr(10) + chr(10) +
                         'Технадзору: проверить и вынести приговор — годное исполнить, '
                         'негодное отметить необоснованным (журнал СОВЕТЫ_И_РЕКОМЕНДАЦИИ).')
                        % (_им, (text or '')[:900]),
                        parse_mode='HTML')
                except Exception:
                    pass
            try:
                await _мсообщ(update).reply_text(
                    ('Замечание принял и передал — спасибо, что сказали. Разберём и ответим.'
                     if _это_замечание else
                     'Пока отвечаю только владельцу — идёт настройка и бета-тест. '
                     'Но если увидите ошибку — напишите прямо сюда, такое я принимаю от любого.'))
            except Exception:
                pass
            return
        
        # 🔴 07.08.2026. Владелец просил ЭТО НЕ РАЗ: «вникни в диалог», «обеспечь, чтобы
        # ты прочёл все сообщения, касающиеся конкретного диалога».
        # Что было: на «вникни в диалог» помощник отвечал «не вижу того объяснения в текущем
        # контексте, напиши заново» (#726202). То есть просил владельца повторяться вместо
        # того, чтобы пойти и прочитать. Ровно тот же порок, за который в тот же день получил
        # выговор В-68 и технадзор.
        #
        # ПОЧЕМУ НЕ ДАВАТЬ ЛЕНТУ ВСЕГДА: она идёт в контекст на КАЖДЫЙ ответ, и лишняя сотня
        # сообщений — это токены за каждое слово помощника. Слово владельца: «лента целиком —
        # лишняя трата токенов, надо обеспечить возможность читать любое смс когда надо».
        #
        # ЗНАЧИТ — ПО ПРИЗНАКУ. Человек сам говорит, когда ему нужен разговор, а не одна
        # реплика: «вникни в диалог», «выше», «я объяснял», «помнишь». На эти слова берём
        # окно вокруг, в остальных случаях не берём ничего.
        try:
            _зовут_вникнуть = re.search(
                r'вникни|вникай|в\s*диалог|выше\s|раньше\s|я\s+(?:тебе\s+)?(?:объясн|говор|писал)'
                r'|помнишь|как\s+я\s+сказал|перечитай|прочит',
                (_dsoc or ''), re.I) is not None
        except Exception:
            _зовут_вникнуть = False
        # 🔴 07.08.2026, обращения #64 и #65. Владелец: «30 сообщений — откуда цифра? Бот имеет
        # достаточно сильную модель, чтобы вникнуть и очертить РЕАЛЬНОЕ начало диалога. Очертить
        # количество участников, их позиции и доводы. Ограничение 30 меня не устраивает».
        # Он прав дважды, и вторая беда была хуже первой.
        #
        # ① ОКНО БРАЛОСЬ НЕ ВОКРУГ ТОГО СООБЩЕНИЯ. Центром стоял `update.message.message_id` —
        #    то есть РЕПЛИКА ВЛАДЕЛЬЦА «вникни», а не сообщение, НА КОТОРОЕ он ответил. Он
        #    показывает пальцем на разговор часовой давности, а помощник читает вокруг самого
        #    пальца. Отсюда «не вижу того объяснения»: он смотрел не туда.
        # ② ЖЁСТКИЕ 30. Число ниоткуда: у разговора нет обязанности укладываться в тридцать
        #    реплик. Берём заведомо шире и поручаем ГРАНИЦЫ САМОЙ МОДЕЛИ — она читает и говорит,
        #    где нить началась и кем ведётся. Это и просил владелец: не отрезать по счётчику,
        #    а понять.
        # Потолок всё же есть (120 реплик): лента идёт в контекст, и «весь чат» — это плата за
        # каждое слово помощника. Но 120 против 30 — это разница между обрывком и разговором,
        # и границу внутри них проводит модель, а не арифметика.
        if _зовут_вникнуть:
            try:
                _ч = getattr(update.effective_chat, 'id', None)
                # Центр — ОТМЕЧЕННОЕ сообщение, если владелец на него ответил; иначе своё.
                _отм_м = getattr(update.message, 'reply_to_message', None)
                _н = (getattr(_отм_м, 'message_id', None)
                      or getattr(update.message, 'message_id', 0))
                _рядом = [x for x in (ЧАТ_ЛЕНТА.get(_ч) or [])
                          if abs((x.get('i') or 0) - _н) <= 200]
                # ⚠️ Отбираем БЛИЖАЙШИЕ К ОТМЕЧЕННОМУ, а не последние по времени. Первый вариант
                # у меня резал `[-120:]` — и на старом сообщении окно уезжало к свежим репликам,
                # выбрасывая ровно то, на что показывал владелец. Поймано проверкой до выкатки:
                # центр 726100, а в окне оказалось 726180…726299. Это воспроизвело бы жалобу
                # «не вижу того, на что я показал» в новом виде.
                _окно = sorted(sorted(_рядом, key=lambda x: abs((x.get('i') or 0) - _н))[:120],
                               key=lambda x: (x.get('i') or 0))
                if _окно:
                    _разговор = chr(10).join('#%s %s: %s' % (x.get('i'), x.get('кто'),
                                                             (x.get('т') or '')[:400])
                                             for x in _окно)
                    _задача = (
                        'РАЗГОВОР ВОКРУГ ОТМЕЧЕННОГО СООБЩЕНИЯ #%s (тебя попросили в него '
                        'вникнуть). Ниже %d реплик — это СЫРЬЁ, а не готовый круг: границы '
                        'проводишь ТЫ, читая, а не по счётчику.\n'
                        'Прежде чем отвечать, определи сам:\n'
                        '• где нить НАЧАЛАСЬ (номер сообщения) и чем — назови первое по сути;\n'
                        '• где она сейчас, и продолжается ли;\n'
                        '• КТО участвует, сколько их, и какова позиция и доводы каждого;\n'
                        '• что именно относится к делу, а что — соседний разговор.\n'
                        'Если начало осталось за пределами данных — так и скажи прямо, назвав '
                        'самое раннее, что видишь. Не проси повторить то, что можешь прочесть.\n'
                        '%s' % (_н, len(_окно), _разговор))
                    реплики = list(реплики) + [{'role': 'system', 'content': _задача}]
            except Exception:
                pass
        # 🔴 ЗАЯВКА №499. Владелец ответил на чужое сообщение с иснадом и написал: «найди эту
        # цепочку и дай свой нейротахкик». Помощник этого иснада НЕ ВИДЕЛ: отмеченное сообщение
        # подтягивалось только по словам-приметам («вникни», «выше», «я объяснял») — а тут ни
        # одной из них нет. Показывают пальцем словом «эту», и палец указывает на цитату.
        # Берём отмеченное сообщение ВСЕГДА, когда владелец отвечает: это одна реплика, не лента,
        # и стоит она копейки против целого промта. Разница с окном разговора именно в размере —
        # ленту из 120 реплик по-прежнему берём только по признаку.
        try:
            _отм = getattr(update.message, 'reply_to_message', None)
            _отм_т = ''
            if _отм is not None:
                _отм_т = ((getattr(_отм, 'text', None) or getattr(_отм, 'caption', None) or '')).strip()
            if _отм_т:
                _чей = 'неизвестно кто'
                try:
                    _а = getattr(_отм, 'from_user', None)
                    if _а is not None:
                        _чей = (getattr(_а, 'full_name', None) or getattr(_а, 'first_name', None)
                                or ('id' + str(getattr(_а, 'id', ''))))
                except Exception:
                    pass
                реплики = list(реплики) + [{'role': 'system', 'content': (
                    'СООБЩЕНИЕ, НА КОТОРОЕ ТЕБЕ ОТВЕТИЛИ (автор: %s). Слова «эту», «этот», '
                    '«это» в просьбе показывают именно на него — работай с ним, а не проси '
                    'повторить:\n%s' % (_чей, _отм_т[:2500]))}]
        except Exception:
            pass
        шапка = "💬 DSOC думает…"
        # 🔴 20.08.2026, B-008. Владелец спросил «Ботяра ты какая модель сейчас» — и не
        # получил НИЧЕГО: в 00:10 телеграмный вызов упал с «Timed out», обработчик умер на
        # первой же отправке, и вопрос погиб до первого слова. Одна сетевая икота съела слово
        # владельца целиком — как у реестра обращений (#285), и лечение то же: пробуем ещё
        # раз, прежде чем сдаться. Второй провал подряд — уже не икота, пусть падает в
        # журнал ошибок как раньше: тихо глотать оба было бы хуже.
        try:
            живое = await update.message.reply_text(шапка)
        except Exception:
            await asyncio.sleep(2)
            живое = await update.message.reply_text(шапка)
        начало = time.time()
        # 🔴 #853, слово владельца: «долго думает. Надо хотя бы писать, что именно делает, а то
        # просто тупо думает вечность». Он прав: пока модель не ответила ни словом, шапка стояла
        # НЕПОДВИЖНО. Со стороны неотличимо от зависшего бота — и человек не знает, ждать ему
        # или переспрашивать.
        # Часы в шапке уже были, но включались ПОЗЖЕ, на вызовах к базе. Самое долгое место —
        # первое размышление модели — оставалось немым. Заводим тикающую подпись здесь: она
        # называет дело и время, а после полуминуты прямо говорит, что модель размышляет.
        # 🔴 20.08.2026. Отсчёт советовал «спросите ещё раз» уже через полторы минуты — мерка
        # облачная, а местная модель на ноутбуке над настоящим вопросом честно думает три
        # (замер 20.08: 47 062 токена промта → 181,9 с). Совет переспросить, поданный посреди
        # исправной работы, толкает владельца оборвать её и решить, что бот сломан. Слова
        # отсчёта обязаны знать, КТО отвечает.
        try:
            _мест_имя = _выбор_прочитать()
            _мест_идёт = bool(_мест_имя and (_реестр_моделей().get('местные') or {}).get(_мест_имя))
        except Exception:
            _мест_имя, _мест_идёт = '', False

        async def _тикать():
            try:
                while True:
                    await asyncio.sleep(4)
                    _прошло = int(time.time() - начало)
                    if _мест_идёт:
                        _хвост = ('' if _прошло < 20 else
                                  ' · вопрос ушёл на твой ноутбук' if _прошло < 60 else
                                  ' · %s читает вопрос целиком, это 2–4 минуты' % _мест_имя
                                  if _прошло < 300 else
                                  ' · дольше обычного; не ответит — сам уйду в облако')
                    else:
                        _хвост = ('' if _прошло < 30 else
                                  ' · модель размышляет, ответ будет длинным'
                                  if _прошло < 90 else
                                  ' · размышление затянулось; если через минуту не отвечу — спросите ещё раз')
                    try:
                        await живое.edit_text('💬 Читаю вопрос и собираю ответ… %d с%s'
                                              % (_прошло, _хвост))
                    except Exception:
                        pass
            except asyncio.CancelledError:
                pass
        _тик = asyncio.ensure_future(_тикать())
        собрано, последняя_правка, вх, вых = "", 0.0, 0, 0
        # 🔴 20.08.2026, сессия DSOC 1. Владелец переключал помощника на местного Линга, бот
        # подтверждал — и отвечал облаком. Накануне это чинили в ask_opencode, назвав его
        # «главным путём ответа». ОН ИМ НЕ БЫЛ: разговор в чате идёт ОТСЮДА, прямым потоком
        # на OPENCODE_URL с моделью ИЗ КОНСТАНТЫ — мимо dsoc_канал, dsoc_запрос и
        # ask_opencode разом. Выбор владельца сюда не доходил вовсе, и переключение второй
        # день подряд оставалось настоящим и бесполезным одновременно.
        # Урок тот же и уже записанный: заводя новый путь, проведи через него ВСЕ двери.
        # Дверей тут четыре, а провели три — и промахнулись ровно той, через которую он
        # говорит с помощником каждый день.
        #
        # ПОЧЕМУ НЕ ПОТОКОМ. Местная модель отвечает не по прямой связи, а через очередь
        # заданий: ноутбук сам забирает работу (#948). Потока там нет и быть не может,
        # ответ приходит целиком — и печать по словам на это время заменяет тикающая шапка.
        _чем_отвечал, _окно_модели = OPENCODE_MODEL + ' · облако', DSOC_ОКНО
        _местная_ответила = False
        _чтение_с = _письмо_с = 0.0     # порознь: сложенные, они врут — см. подпись ответа
        try:
            _выб = _выбор_прочитать()
            _проф = (_реестр_моделей().get('местные') or {}).get(_выб) if _выб else None
            if _проф:
                _ид_з = задание_положить(
                    _выб, ([{"role": "system", "content": dsoc_системный()}]
                           + dsoc_чистые(реплики[-60:])), МЕСТНЫЙ_ВЫВОД_МАКС, 0.4)
                # Ждать НАДО в отдельном потоке. задание_ждать спит в цикле, и на общей нити
                # оно заморозило бы весь бот — включая дверь /api/rabota, через которую
                # работник и приходит за этим самым заданием. Ожидание задушило бы то, чего
                # ждёт; на этом уже спотыкалась «проба».
                _гот = await asyncio.get_event_loop().run_in_executor(
                    None, lambda: задание_ждать(_ид_з, МЕСТНОЕ_ЖДАТЬ))
                if _гот and (_гот.get('текст') or '').strip():
                    собрано = _гот['текст'].strip()
                    вх, вых = _гот.get('вход') or 0, _гот.get('выход') or 0
                    _чтение_с = float(_гот.get('чтение') or 0)
                    _письмо_с = float(_гот.get('письмо') or 0)
                    _местная_ответила = True
                    _окно_модели = int(_проф.get('окно') or 0)
                    # Подписью служит ИМЯ ПРОФИЛЯ, а не то, чем модель представилась: она
                    # называет себя полным путём к файлу на ноутбуке владельца, а путям в
                    # общем чате не место (З-77). Но расхождение не прячем: просили одно,
                    # ответило другое — так и говорим.
                    _кто_с = str(_гот.get('кто') or '')
                    _чем_отвечал = _выб + ' · твой ноутбук'
                    # 🔴 20.08.2026, обращение владельца #1027 («что за подпись,
                    # несоответствующая в действительности»). Сверка брала первый кусок имени
                    # профиля ДО дефиса — у «ornith15-q4-262k» это «ornith15», склейка имени с
                    # версией. Модель себя так не зовёт: в файле она «Ornith-1.5-35B-Q4_K_M»,
                    # и куска «ornith15» там нет. Под совершенно верным ответом появилась бы
                    # тревога «просили одно, ответила другая» — то есть заслон от подмены сам
                    # начал бы кричать о подмене, которой не было. У «qwen3.6-35b-262k» та же
                    # ловушка: первый кусок «qwen3.6».
                    # Сравниваем БУКВЕННУЮ часть, без цифр версии: «ornith», «qwen», «ling».
                    # Заслон от этого не слабеет — настоящее расхождение (просили ornith,
                    # ответил ling) ловится ровно как прежде.
                    _корень = re.sub(r'[^a-zа-яё]', '', _выб.split('-')[0].lower())
                    if _кто_с and _корень and _корень not in _кто_с.lower():
                        _чем_отвечал += ' ⚠️ просили %s, ответила другая' % _выб
                else:
                    # 🔴 20.08.2026. Здесь стоял безусловный сброс выбора, и он был неправ.
                    # Сброс задуман для случая «ноутбук выключен»: не отвечает — не ври
                    # владельцу, что говоришь с Лингом. Но он срабатывал и когда машина ЖИВА
                    # и считает, а не дождались МЫ. Тогда получалось наказание за собственное
                    # нетерпение: владелец переключался заново, не понимая, почему слетело.
                    # Различаем по тому, ВЗЯЛИ ли работу.
                    if задание_взято(_ид_з):
                        print('DSOC-чат: «%s» взяла работу, но не вернула за %d с — '
                              'иду в облако, выбор НЕ сбрасываю' % (_выб, МЕСТНОЕ_ЖДАТЬ))
                    else:
                        print('DSOC-чат: работу для «%s» никто не забрал — иду в облако '
                              'и сбрасываю выбор' % _выб)
                        _выбор_записать('')
        except Exception as _ем:
            print('DSOC-чат, выбор модели: %s' % str(_ем)[:150])
        try:
            if not _местная_ответила:
                # 🔴 Здесь стоял свой, короткий системный промт — а рядом жила функция
                # dsoc_системный() со списком команд, и её никто не звал. Ассистент поэтому не знал
                # ни одной нашей команды, хотя весь смысл затеи был в том, чтобы он их подсказывал.
                тело = {"model": _облачная_сейчас(),
                        "messages": ([{"role": "system", "content": dsoc_системный()}]
                                     + dsoc_чистые(реплики[-60:])),
                        # 🔴 06.08.2026, владелец: «у нас же лимит выходных ответа не врезан?
                        # Он 384 000 минимум для дипсика опенкод же». Он прав: здесь стояло 8000 —
                        # число, взятое с потолка, при разрешённых сервером 393 216. Рядом всё это
                        # время лежала константа DSOC_ВЫВОД_МАКС с настоящим потолком, и её никто
                        # не звал. Из-за этого длинные разборы обрывались на середине, и выглядело
                        # это как «модель не дописала», хотя резали её мы.
                        # max_tokens — это ПОТОЛОК, а не задание: модель останавливается, когда
                        # сказала всё. Высокий потолок ничего не стоит, а низкий режет по живому.
                        "max_tokens": DSOC_ВЫВОД_МАКС, "temperature": 0.4, "stream": True}
                _кл, _имя_кл = opencode_ключ()      # ← сюда уходит основной расход помощника
                opencode_отметить(_имя_кл)
                # 🔴 03.09.2026. Здесь стоял СИНХРОННЫЙ запрос с потоковым чтением, а рядом,
                # в том же цикле, — асинхронная правка сообщения (живая печать ответа).
                # Пока библиотека ждала следующий кусок от модели, событийный цикл СТОЯЛ: бот
                # не отвечал НИКОМУ — ни в чате, ни по своим дверям, — и так десятки секунд,
                # всё время ответа. Отсюда и жалобы «бот завис», хотя он просто ждал модель.
                # Нашлось не глазами, а разбором кода: 37 таких мест, и это самое горячее.
                # Лечим не отказом от потока (живая печать — ценность), а разделением ролей:
                # ЧИТАЕТ отдельный поток и складывает куски в очередь, а событийный цикл их
                # разбирает и правит сообщение. Никто никого не держит.
                _оч_кусков = asyncio.Queue()
                _цикл_с = asyncio.get_event_loop()

                def _качать_поток(_к=_кл, _т=тело, _о=_оч_кусков, _ц=_цикл_с):
                    try:
                        _отв = requests.post(OPENCODE_URL, json=_т, stream=True, timeout=600,
                                             headers={"Content-Type": "application/json",
                                                      "Authorization": "Bearer " + _к})
                        for _стр in _отв.iter_lines(decode_unicode=False):
                            _ц.call_soon_threadsafe(_о.put_nowait, _стр)
                    except Exception as _е:
                        _ц.call_soon_threadsafe(_о.put_nowait, ('__беда__', str(_е)[:200]))
                    finally:
                        _ц.call_soon_threadsafe(_о.put_nowait, None)   # знак конца

                _чтение = _цикл_с.run_in_executor(None, _качать_поток)
                # 🔴 05.08.2026: было decode_unicode=True — и владелец получил «ÐÐµÑÐµÐ²Ð¾Ð´»
                # вместо «Перевод». В этом режиме библиотека берёт кодировку из заголовка ответа,
                # а поток событий её не объявляет — и русские байты молча разбираются как латиница.
                # И модель, и сеть отработали безупречно: испортилось на последнем шаге, у нас.
                # Лечение: не доверять угадыванию, разбирать байты самим и всегда в utf-8.
                while True:
                    сырое = await _оч_кусков.get()
                    if сырое is None:          # поток кончился
                        break
                    if isinstance(сырое, tuple) and сырое and сырое[0] == '__беда__':
                        print('поток помощника оборвался: %s' % сырое[1])
                        break
                    if not сырое:
                        continue
                    строка = сырое.decode("utf-8", "replace") if isinstance(сырое, bytes) else сырое
                    if not строка.startswith("data: "):
                        continue
                    кусок = строка[6:]
                    if кусок == "[DONE]":
                        break
                    try:
                        j = json.loads(кусок)
                    except Exception:
                        continue
                    вы = (j.get("choices") or [{}])[0]
                    д = (вы.get("delta") or {}).get("content")
                    if д:
                        # Первый же кусок ответа гасит тикающую подпись: иначе она затрёт то,
                        # что модель уже пишет. Подпись нужна ровно до первого слова, дальше
                        # человек видит сам ответ и часы ему не нужны.
                        if _тик is not None and not _тик.done():
                            try:
                                _тик.cancel()
                            except Exception:
                                pass
                        собрано += д
                    u = j.get("usage") or {}
                    вх = u.get("prompt_tokens") or вх
                    вых = u.get("completion_tokens") or вых
                    # правим сообщение не чаще чем раз в 2,5 секунды: Telegram ругается на
                    # частые правки, а глазу и так довольно
                    # Владелец: «печатает слишком резко, нельзя ли по словам». Было раз в 2,5 с
                    # и целым куском — оттого рывками, да ещё и обрыв посреди слова. Теперь чаще и
                    # ровно по границе слова. Чаще 1 с нельзя: Telegram отвечает 429 на частые
                    # правки. Облаку это почти ничего не стоит — правка сообщения не считает
                    # токенов, платит только Telegram своим лимитом.
                    if собрано and time.time() - последняя_правка > 1.1:
                        последняя_правка = time.time()
                        видно = собрано[-3900:]
                        _п = видно.rfind(" ")
                        if _п > 40:
                            видно = видно[:_п]        # не показывать полслова
                        try:
                            await живое.edit_text(видно + " ▌")
                        except Exception:
                            pass
        except Exception as e:
            # ПОДСТРАХОВКА (владелец 05.08.2026: «может, на резерв поставишь API ключи, они
            # подстрахуют?»). Молчание вместо ответа — худший исход. Отвечаем с бесплатных
            # каналов и ЧЕСТНО пишем, что отвечал резерв: подменять исполнителя молча нельзя.
            собрано = ''
            # ПОРЯДОК РЕЗЕРВА (владелец 05.08.2026). Первым — Gemini: у него тоже миллион
            # контекста, то есть он один заменяет OpenCode без потерь. Остальные бесплатные
            # держат 128 тысяч — этого всё равно вдвадцатеро больше нашего разговора, так что
            # беседа доедет целиком. Платный DeepSeek — последним, он дороже и не длиннее.
            _вся_беседа = "\n".join(
                ("%s: %s" % ('владелец' if р.get('role') == 'user' else 'ты',
                             (р.get('content') or '')[:1500]))
                for р in dsoc_чистые(реплики[-40:]))
            _запрос_рез = (_вся_беседа[-90000:] + "\n\nОтветь на последнюю реплику владельца.")
            # 🚨 ТРЕВОГА ПРИ ПЕРВОЙ ЖЕ ПОДМЕНЕ (слово владельца 05.08.2026: «отметку делай
            # сразу, тревогу»). Подмена спасает разговор — и именно поэтому о ней надо
            # кричать: молчаливая подмена это когда всё «работает», а счёт растёт из другого
            # кармана и никто не знает почему.
            _чем_ответили = ''
            try:
                await context.bot.send_message(
                    LOG_CHAT_ID,
                    "🚨 <b>OPENCODE НЕ ОТВЕТИЛ — ушли на резерв</b>\n"
                    "причина: %s\nчат: %s · время: %s\n"
                    "Сейчас отвечает платный DeepSeek API (наш), при его отказе — бесплатные."
                    % (str(e)[:200], chat_id, _now_msk()), parse_mode='HTML')
            except Exception:
                pass
            try:
                # ② наш платный DeepSeek — та же семья моделей, ответ не просядет
                _рез = await asyncio.get_event_loop().run_in_executor(
                    None, lambda: (ask_deepseek(_запрос_рез[:60000], dsoc_системный(), 1500)
                                   if DEEPSEEK_API_KEY else None))
                _чем_ответили = 'платный DeepSeek API (наш)'
                if not _рез or str(_рез).startswith('⚠️'):
                    # ③ бесплатные, Gemini первым — у него тоже миллион контекста
                    _рез = await asyncio.get_event_loop().run_in_executor(
                        None, lambda: (ask_gemini(_запрос_рез, dsoc_системный())
                                       if GEMINI_API_KEY else None))
                    _чем_ответили = 'Gemini (бесплатный)'
                if not _рез or str(_рез).startswith('⚠️'):
                    _рез = await asyncio.get_event_loop().run_in_executor(
                        None, lambda: ask_ai(_запрос_рез[:60000], dsoc_системный(), True, 1500))
                    _чем_ответили = 'бесплатная цепочка'
                if _рез and not str(_рез).startswith('⚠️'):
                    # Курсив звёздочкой, не тегом: всё из `собрано` идёт через dsoc_в_html,
                    # который экранирует угловые скобки (тот же класс, что A-45).
                    собрано = (re.sub(r'⚡ \*Модель:\*.*|🆓.*|📊 осталось.*', '', _рез).strip()
                               + '\n\n⚠️ *Отвечал резерв — %s. OpenCode не отозвался (%s).*'
                               % (_чем_ответили, str(e)[:80].replace('*', '')))
            except Exception:
                собрано = ''
            if not собрано:
                try:
                    await живое.edit_text(
                        "🔴 Не ответил ни OpenCode, ни резерв: %s" % str(e)[:200])
                except Exception:
                    pass
                await dsoc_неудача(context.bot, chat_id, _dsoc, '', 'молчат все каналы')
                return
            try:
                await живое.edit_text(собрано[:3800], parse_mode='HTML')
            except Exception:
                try:
                    await живое.edit_text(re.sub(r'<[^>]+>', '', собрано)[:3800])
                except Exception:
                    pass
            реплики.append({"role": "assistant", "content": собрано, "t": time.time()})
            DSOC_ПАМЯТЬ[chat_id] = реплики
            dsoc_сохранить(силой=True)
            return

        # Страховка: подпись гаснет при ЛЮБОМ исходе, даже если модель не сказала ни слова.
        # Тикающая подпись, пережившая свой разговор, правила бы чужое сообщение вечно.
        if _тик is not None and not _тик.done():
            try:
                _тик.cancel()
            except Exception:
                pass
        # ── ИНСТРУМЕНТЫ: модель просит данные — идём и приносим. ДО ТРЁХ КРУГОВ ──────
        # Один круг оказался мало: по короткому прозвищу «аль-Амаш» база не нашла, модель
        # разумно решила попробовать полное имя — а выполнять её второй вызов было уже некому,
        # и черновик уехал владельцу. Поиск редко укладывается в один заход.
        _старт_дсок = time.time()
        for _круг in range(3):
            _вз = re.search(r'ВЫЗОВ\s*:\s*(.+)$', собрано or '', re.M)
            if not _вз:
                break
            # 🔴 08.08.2026, обращение #118. Владелец: «почему он долго думает? Дописывай там,
            # изменяя, что именно уходит время, на что он грузит что-то или что. Но не раскрывай
            # кухни». Раньше сюда выводилась СЫРАЯ строка вызова — «ВЫЗОВ: аят 2:255». Это и есть
            # кухня: имя внутреннего механизма, которое человеку ничего не говорит и знать его
            # незачем. А главное — по ней не понять, отчего ждёшь: строка не менялась ни через
            # десять секунд, ни через сто.
