    if is_owner(update) and text.lower() in ("дипсик всем выкл", "дипсик выкл всем", "ии всем выкл", "ии только мне", "дипсик только мне", "ии публично выкл", "публичный ии выкл"):
        _AI_PUBLIC_OFF = True; _save_ai_gate()
