    if is_owner(update) and text.lower() in ("дипсик всем вкл", "дипсик вкл всем", "ии всем вкл", "ии публично вкл", "публичный ии вкл", "дипсик всем включи"):
        _AI_PUBLIC_OFF = False; _save_ai_gate()
