        # а гадать в правилах достоверности нельзя.
        if re.match(r'^правил[оа]\b', _tl):
            _пт = text.strip()[7:].strip()
            _сп_п = _data_get(ПРАВИЛА_ДОСТ_ФАЙЛ, []) or []
            if not _пт or _tl.strip() in ('правила', 'правило'):
                if not _сп_п:
                    await _мсообщ(update).reply_text(
                        'Ваших правил достоверности пока нет ни одного.\n'
                        'Добавить: «правило <текст>» — попадёт в приложение, в раздел '
                        '«📜 Наука хадиса», отдельным блоком «Правила владельца».')
                else:
                    _из_п = ['📜 <b>Ваши правила достоверности</b> (%d):' % len(_сп_п), '']
                    for _п in _сп_п[-15:]:
                        _из_п.append('<b>%s.</b> %s <i>(%s)</i>'
                                     % (_п.get('n'), esc(_п.get('t') or ''), _п.get('d') or ''))
                    _из_п.append('')
                    _из_п.append('Убрать: «правило убрать <номер>».')
                    await _мсообщ(update).reply_text(chr(10).join(_из_п), parse_mode='HTML')
                return
            _му = re.match(r'^убрать\s+(\d+)$', _пт, re.I)
            if _му:
                _н_у = int(_му.group(1))
                _ост = [_п for _п in _сп_п if int(_п.get('n') or 0) != _н_у]
                if len(_ост) == len(_сп_п):
                    await _мсообщ(update).reply_text('Правила №%d нет.' % _н_у)
                    return
                _data_put(ПРАВИЛА_ДОСТ_ФАЙЛ, _ост, 'правило достоверности №%d убрано' % _н_у)
                await _мсообщ(update).reply_text('Правило №%d убрано.' % _н_у)
                return
            _н_п = max([int(_п.get('n') or 0) for _п in _сп_п], default=0) + 1
            _сп_п.append({'n': _н_п, 'd': _now_msk(), 't': _пт[:4000]})
            _data_put(ПРАВИЛА_ДОСТ_ФАЙЛ, _сп_п, 'правило достоверности №%d' % _н_п)
