    async def search(r):
        # dorar-поиск: initData в заголовке X-Init-Data или в query (?initData=...); гейт = вход в приложение
        user = verify_init_data(r.headers.get('X-Init-Data') or r.query.get('initData'))
        if not feature_allowed('app', user):
            return _deny('app')
        if not rate_ok('search:' + _uid(user, r)):
            return _ratelimited()
        try:
            q = (r.query.get('q') or '')[:200]
            res = await loop.run_in_executor(None, search_hadith, q) if q else []
            # None = источник не пустил. Отдаём это ОТДЕЛЬНЫМ полем, а не пустым списком:
            # приложение должно уметь сказать человеку правду, а не «ничего не найдено».
            if res is None:
                # 🔴 03.09.2026. Прогнал ВСЕ читающие двери API живыми запросами: из шестнадцати
                # мертва ровно одна — эта. Dorar.net закрылся для роботов (403), и дверь честно
                # говорила «источник не ответил» — но человеку от честности не легче, он видит
                # пустой поиск. При этом рядом, в /api/wide, уже работает sunnah.one: тот же
                # вопрос отдаёт 71 находку, да ещё с оценкой достоверности и тахриджем.
                # Второго поиска не завожу (З-33) — веду эту дверь к тому же живому источнику
                # и честно говорю, ЧЕЙ ответ отдаём: приложение показывает это человеку.
                try:
                    _зап = await loop.run_in_executor(None, wide_search, q, 1)
                    _сп = (_зап or {}).get('data') or []
                    if _сп:
                        return _cors(web.json_response(
                            {'results': _сп, 'источник': 'sunnah.one',
                             'почему': 'dorar.net закрыт для роботов (403) — искали у соседа'}))
                except Exception as _ез:
                    print('search → запасной sunnah.one: %s' % str(_ез)[:150])
                return _cors(web.json_response(
                    {'results': [], 'источник': 'не ответил',
                     'почему': 'dorar.net закрыт для роботов (403), запасной источник тоже молчит'}))
            return _cors(web.json_response({'results': res}))
        except Exception as e:
            return _cors(web.json_response({'results': [], 'error': str(e)}))

