    async def narrator_ai(r):
        # ИИ-справка о равии (кто это + оценка учёных + источник), с накоплением; гейт — нейро (тратит ключ)
        d = await _body(r)
        user = verify_init_data(d.get('initData'))
        if not feature_allowed('neuro', user):
            return _deny('neuro')
        if not rate_ok('rijalai:' + _uid(user, r), limit=12, window=120):
            return _ratelimited()
        name = (d.get('name') or '').strip()[:80]
        if len(name) < 3:
            return _cors(web.json_response({'bio': '', 'cached': False}))

        # ── СВОД ПО НАШИМ ДАННЫМ (владелец 26.07.2026) ──────────────────────────────────────
        # Было: модели передавалось ТОЛЬКО ИМЯ, и она писала по своей памяти — мимо нашей базы.
        # На снимке владельца свод цитировал Яхью аль-Каттана и Ибн Махди, которых в карточке нет.
        # Владелец: «развернуть к нашим данным — вот это другое дело. Строго в пределах наших
        # сведений собирает и говорит обобщённо, сохраняя источники, и перевод делая сразу».
        # Теперь клиент присылает свидетельства из карточки, и модель ТОЛЬКО обобщает их.
        свид = d.get('св') or []
        куски, метки = [], []
        for с in свид[:40]:
            try:
                учёный = str(с[0] or '')[:40]
                оценка = str(с[1] or '')[:70]
                книга = str(с[4] or '')[:40] if len(с) > 4 else ''
                if учёный or оценка:
                    куски.append('%s: «%s»%s' % (учёный, оценка, (' [' + книга + ']') if книга else ''))
                    метки.append(книга)
            except Exception:
                continue

        # Отпечаток данных в ключе кэша: владелец верно заметил — «это всё ломать будет, когда
        # ты будешь вносить правки в карточки». Поправили свидетельства → отпечаток другой →
        # свод пересчитается сам. Без этого накопитель хранил бы обобщение вчерашнего бардака.
        отпеч = hashlib.md5(('|'.join(куски)).encode('utf-8')).hexdigest()[:10] if куски else 'nodata'
        ключ_кэша = name + '#' + отпеч

        cached = await loop.run_in_executor(None, rijal_ai_get, ключ_кэша)
        if cached:
            await loop.run_in_executor(None, usage_log, user, "равий-ИИ", False, len(name), "", "")
            return _cors(web.json_response({'bio': cached, 'cached': True, 'наши': bool(куски)}))

        if куски:
            sysm = ("Ты знаток науки о передатчиках хадисов (الجرح والتعديل). Тебе дают СПИСОК СВИДЕТЕЛЬСТВ "
                    "учёных о равии из нашей базы. Обобщи ИМЕННО ИХ и ничего больше.\n"
                    "СТРОГО ЗАПРЕЩЕНО: добавлять учёных, оценки, книги или сведения, которых НЕТ в списке. "
                    "Ничего не добавляй по своей памяти — даже если знаешь. Твоё знание тут не нужно, нужен разбор данных.\n"
                    "ЧТО НАПИСАТЬ по-русски, 4-7 строк, без воды:\n"
                    "· к чему клонит большинство (надёжен / правдив / слаб) и СКОЛЬКО учёных за это;\n"
                    "· В ЧЁМ РАСХОДЯТСЯ, если расходятся — кто именно и что сказал;\n"
                    "· каждое имя учёного оставляй как в списке, и рядом в скобках его книгу, если она дана;\n"
                    "· арабские термины давай С ПЕРЕВОДОМ сразу: ثقة (надёжный), صدوق (правдивый), ضعيف (слабый).\n"
                    "Если свидетельств мало — так и скажи, не раздувай.\n"
                    "В конце с новой строки: «📚 Свод по нашей базе: %d свидетельств.»" % len(куски))
            вопрос = "Равий: %s\n\nСВИДЕТЕЛЬСТВА ИЗ НАШЕЙ БАЗЫ:\n%s" % (name, '\n'.join(куски))
        else:
            # Данных нет — честно говорим, что это память модели, а не наша база.
            sysm = ("Ты знаток науки о передатчиках хадисов (الجرح والتعديل والرواة). Дай КРАТКУЮ справку о равии по-русски: "
                    "полное имя; кунья; когда жил/умер (если известно); кем был (сподвижник/таби'/..); и ОЦЕНКА достоверности "
                    "словами имамов (ثقة/صدوق/ضعيف и т.п.) — КТО так оценил и в какой книге. 4-7 строк, без воды. "
                    "В конце с новой строки: «⚠️ В нашей базе свидетельств об этом равии нет — справка собрана ИИ по памяти, "
                    "сверяйте с первоисточниками (الجرح والتعديل، تقريب التهذيب).»")
            вопрос = "Передатчик хадисов: " + name

        bio = await loop.run_in_executor(None, ask_neuro, вопрос, sysm) or ""
        bio = bio.strip()
        if bio and len(bio) > 15:
            await loop.run_in_executor(None, rijal_ai_put, ключ_кэша, bio)
        await loop.run_in_executor(None, usage_log, user, "равий-ИИ", True, len(name), "", "")
        return _cors(web.json_response({'bio': bio, 'cached': False}))

    async def popular(r):
        # 🔥 Популярное: топ запросов (из накопленного searchlog), гейт = вход в приложение
        user = verify_init_data(r.headers.get('X-Init-Data') or r.query.get('initData'))
        if not feature_allowed('app', user):
            return _deny('app')
        j = await loop.run_in_executor(None, _journal_load)
        top = j.get('searches', {}).get('top', {})
        items = sorted(top.items(), key=lambda x: -x[1].get('n', 0))
        out = [{'q': k, 'tab': v.get('tab', ''), 'n': v.get('n', 0)}
               for k, v in items
               if v.get('n', 0) >= 2 and v.get('cnt', 0) > 0 and len(k) <= 28][:15]   # без длинных вставок хадисов
        return _cors(web.json_response({'items': out}))

    async def hit(r):
        # G3: счётчик запусков приложения (тихо; уникальные пользователи по id)
        d = await _body(r)
        user = verify_init_data(d.get('initData'))
        if not rate_ok('hit:' + _uid(user, r), limit=10, window=60):
            return _cors(web.json_response({'ok': False}))
        await loop.run_in_executor(None, app_hit, user)
        return _cors(web.json_response({'ok': True}))

    async def arabus(r):
        # Arabus: корень+значения слова (прокси+кэш arabus.ru); гейт = вход в приложение
        user = verify_init_data(r.headers.get('X-Init-Data') or r.query.get('initData'))
        if not feature_allowed('app', user):
            return _deny('app')
        if not rate_ok('arabus:' + _uid(user, r), limit=40, window=60):
            return _ratelimited()
        w = (r.query.get('word') or r.query.get('q') or '')[:60]
        root = (r.query.get('root') or '')[:20]
        if not w:
            return _cors(web.json_response({'word': '', 'count': 0, 'entries': []}))
        res = await loop.run_in_executor(None, arabus_fetch, w, root)
        # 🔴 №676, слово владельца: «смотри, иудеи и арабское слово вообще не связано… подсказки
        # должны быть толковые». Он прав, и вот отчего так выходит: словарь отдаёт значения
        # ВСЕГО КОРНЕВОГО ГНЕЗДА, а не одного слова. На «شفاء» (исцеление) первым приходит
        # «разговор, беседа» — это от родственного корня, и человеку кажется, что перевод не о том.
        # Различить значения по слову источник не даёт: у них нет арабской формы, только русская
        # строка. Значит честный путь — не молча показывать чужое, а ДОБАВИТЬ то, что у нас
        # выверено: разбор Корана по корням (14 633 слова). Оттуда берём корень слова, его форму
        # и сколько раз оно встречается — и прямо говорим, что список значений относится к гнезду.
        try:
            _рз = await loop.run_in_executor(None, _разбор_слова_корана, w)
            if _рз:
                res = dict(res or {})
                res['разбор'] = _рз
                res['оговорка'] = ('Значения ниже даны для всего корневого гнезда «%s», а не '
                                   'только для этого слова: у словаря нет разбивки по формам. '
                                   'Точен здесь разбор выше — он из нашего разбора Корана.'
                                   % _рз.get('корень', ''))
        except Exception as _ер:
            print('arabus: разбор слова не вышел: %s' % str(_ер)[:120])
        return _cors(web.json_response(res))

    async def backup_push(r):
        # #259/#261: локальный backup_muslimoon.ps1 заливает сюда свежий Muslimoon_RECOVERY.zip,
        # бот пересылает САМ ФАЙЛ в ЖУРНАЛ УВЕДОМЛЕНИЙ (LOG_CHAT) + владельцу в ЛС (приватно — внутри журналы, R42).
        # Аутентификация — общий секрет BACKUP_SECRET (env Railway == локальный .backup_secret).
        if not application:
            return _cors(web.json_response({'error': 'no_app'}, status=503))
        if not BACKUP_SECRET:
            return _cors(web.json_response({'error': 'disabled', 'message': 'BACKUP_SECRET не задан в env Railway'}, status=503))
        try:
            secret = ''; caption = ''; filename = 'Muslimoon_RECOVERY.zip'; data = None
            куда_чат = None; вид = 'документ'
            reader = await r.multipart()
            async for part in reader:
                if part.name == 'secret':
                    secret = (await part.text()).strip()
                elif part.name == 'caption':
                    caption = (await part.text()).strip()
                # 🔴 07.08.2026, обращение #79. Владелец: «я же в ЧАТЕ просил, он должен быть
                # исполнен в чате». Ролик собрался, а отправить его было нечем: эта точка
                # входа всегда слала в две зашитые точки — журнал и личку владельца.
                # Не завожу вторую точку рядом (З-33): она отличалась бы одной строкой, и
                # завтра мы правили бы обе, а послезавтра забыли бы про одну. Расширяю эту:
                # «куда» и «вид». Без них поведение прежнее, до буквы.
                elif part.name == 'чат':
                    try:
                        куда_чат = int((await part.text()).strip())
                    except Exception:
                        куда_чат = None
                elif part.name == 'вид':
                    вид = (await part.text()).strip().lower()
                elif part.name == 'file':
                    filename = part.filename or filename
                    data = await part.read(decode=False)
            if not secret or secret.strip() != (BACKUP_SECRET or '').strip():   # #259: strip обеих сторон — невидимый пробел/перенос в env Railway давал ложный 403
                return _cors(web.json_response({'error': 'auth'}, status=403))
            if not data:
                return _cors(web.json_response({'error': 'no_file'}, status=400))
            if len(data) > 49 * 1024 * 1024:
                return _cors(web.json_response({'error': 'too_big', 'size': len(data)}, status=413))
            # ─────────────────────────────────────────────────────────────────
            # 🔤 ЗАСЛОН ОТ ИЕРОГЛИФОВ. Высочайший указ владельца 10.08.2026:
            # «ты сейчас опять в канал архивный скинул иероглифы… обеспечь, чтобы каждый
            # файл там был проверен… обеспечь, чтобы иероглифы не шли, ужесточи закон,
            # чтобы он исполнялся».
            #
            # ПОЧЕМУ ЗДЕСЬ, А НЕ В ПАМЯТИ ОТПРАВЛЯЮЩЕГО. Правило «класть в текстовый файл
            # отметку кодировки» у меня записано давно, и я его знаю. Но жило оно в голове,
            # а голова забывает — ровно как забыла про пути к файлам 07.08. Значит проверка
            # обязана стоять НА ВЫХОДЕ, там, где файл превращается в сообщение. Мимо этой
            # точки в Telegram не проходит ничего, что шлём мы сами.
            #
            # СУТЬ. Текст в UTF-8 без отметки в начале Telegram и Блокнот читают как cp1251 —
            # владелец видит «РџСЂРёРІРµС‚» вместо «Привет».
            # ⚠️ И обратное: в .json отметку ставить НЕЛЬЗЯ, разборщики о неё спотыкаются.
            # Поэтому решает ТИП файла, а не «поставим везде, хуже не будет».
            try:
                _рас = ('.' + filename.rsplit('.', 1)[-1].lower()) if '.' in filename else ''
                _ГЛАЗАМИ = ('.md', '.txt', '.csv', '.log', '.srt', '.ass', '.tsv', '.ini')
                _МАШИНЕ = ('.json', '.jsonl', '.py', '.js', '.css', '.yml', '.yaml', '.xml',
                           '.html', '.toml')
                _BOM = b'\xef\xbb\xbf'
                if _рас in _ГЛАЗАМИ and not data.startswith(_BOM):
                    _проба = bytes(data[:200000])
                    try:
                        _т = _проба.decode('utf-8')
                        _есть_кир = any('Ѐ' <= с <= 'ӿ' for с in _т)
                    except UnicodeDecodeError:
                        # Не UTF-8 вовсе — скорее всего cp1251. Переводим, иначе иероглифы
                        # будут при любой отметке.
                        try:
                            data = _BOM + bytes(data).decode('cp1251').encode('utf-8')
                        except Exception:
                            pass
                        _есть_кир = False
                    if _есть_кир:
                        data = _BOM + bytes(data)
                elif _рас in _МАШИНЕ and data.startswith(_BOM):
                    data = bytes(data)[len(_BOM):]
            except Exception:
                pass
            kb = round(len(data) / 1024)
            cap = ("📦 БЭКАП Muslimoon · " + (caption or ("свежий " + filename)) + (" (%d КБ)" % kb)) + "\n🗄 Резервная копия (журналы+bot.py+index.html). Приватно (R42) — не пересылать."
            # Названный чат — вместо двух зашитых, и подпись тогда своя: приписка «резервная
            # копия, не пересылать» уместна для бэкапа и нелепа под роликом в общем чате.
            цели = (куда_чат,) if куда_чат else (LOG_CHAT_ID, OWNER_ID)
            подпись = (caption[:1000] if куда_чат else cap[:1000])
            sent = []
            # 🔢 НОМЕРА ПОСТОВ (З-47, 10.08.2026, сессия 70). Раньше ответ говорил только
            # «ушло в такой-то чат» — а по закону доказательство доставки ровно одно: номер,
            # который Telegram присваивает сам при удачной отправке. Без него отправляющий
            # инструмент не мог ни напечатать доказательство, ни записать файл в опись архива,
            # и получалось «отправил» со слов, а не по факту. Возвращаем номера наружу.
            номера = {}
            for chat in цели:
                try:
                    if вид in ('видео', 'video'):
                        # supports_streaming: иначе Telegram отдаёт ролик файлом, и его надо
                        # скачивать, чтобы посмотреть. Для вертикального ролика это убивает
                        # весь смысл — его смотрят на ходу, не скачивая.
                        _м = await app.bot.send_video(chat, video=bytes(data),
                                                              filename=filename, caption=подпись,
                                                              supports_streaming=True)
                    elif вид in ('фото', 'картинка', 'photo', 'image'):
                        # #255: образцы шрифтов и прочие картинки. Именно send_photo, а не
                        # документом: документ надо скачать, чтобы увидеть, а картинку смотрят
                        # прямо в ленте — для голосования это и есть весь смысл.
                        _м = await app.bot.send_photo(chat, photo=bytes(data),
                                                              caption=подпись)
                    elif вид in ('аудио', 'audio'):
                        _м = await app.bot.send_audio(chat, audio=bytes(data),
                                                              filename=filename, caption=подпись)
                    else:
                        _м = await app.bot.send_document(chat, document=bytes(data),
                                                                  filename=filename, caption=подпись)
                    sent.append(chat)
                    try:
                        номера[str(chat)] = _м.message_id
                    except Exception:
                        pass
                except Exception:
                    pass
            return _cors(web.json_response({'ok': bool(sent), 'sent': sent, 'size': len(data),
                                            'filename': filename, 'номера': номера}))
        except Exception as e:
            return _cors(web.json_response({'error': str(e)[:160]}, status=500))

    async def zamenit_fayl(r):
        """Заменить ФАЙЛ в уже опубликованном посте, не создавая второго поста.

        🔴 Высочайший указ владельца 10.08.2026: «если там иероглифы, как например последний
        файл, то ты обязан его исправить, файл перезагрузить в посте — Телеграм это позволяет».

        Он прав и по существу, и по способу. Удалить пост и выложить заново — значит порвать
        ссылки: на архивные посты ссылаются реестр, журналы и другие посты, и все они станут
        указывать в пустоту. Telegram умеет менять вложение НА МЕСТЕ (editMessageMedia) —
        номер поста, дата и ссылки остаются теми же, меняется только содержимое.

        Файл проходит тот же заслон от иероглифов, что и обычная отправка: чинить битую
        кодировку и тут же положить её обратно было бы смешно.
        """
        if not application or not BACKUP_SECRET:
            return _cors(web.json_response({'error': 'disabled'}, status=503))
        try:
            secret = ''; filename = 'file.txt'; data = None
            чат = None; номер = None; подпись = None
            reader = await r.multipart()
            async for part in reader:
                if part.name == 'secret':
                    secret = (await part.text()).strip()
                elif part.name == 'чат':
                    чат = int((await part.text()).strip())
                elif part.name == 'номер':
                    номер = int((await part.text()).strip())
                elif part.name == 'подпись':
                    подпись = (await part.text()).strip()
                elif part.name == 'file':
                    filename = part.filename or filename
                    data = await part.read(decode=False)
            if secret.strip() != (BACKUP_SECRET or '').strip():
                return _cors(web.json_response({'error': 'auth'}, status=403))
            if not data or чат is None or номер is None:
                return _cors(web.json_response({'error': 'нужны чат, номер и файл'}, status=400))
            _BOM = b'\xef\xbb\xbf'
            _рас = ('.' + filename.rsplit('.', 1)[-1].lower()) if '.' in filename else ''
            if _рас in ('.md', '.txt', '.csv', '.log', '.srt', '.tsv', '.ini') \
                    and not data.startswith(_BOM):
                try:
                    if any('Ѐ' <= с <= 'ӿ' for с in bytes(data[:200000]).decode('utf-8')):
                        data = _BOM + bytes(data)
                except UnicodeDecodeError:
                    try:
                        data = _BOM + bytes(data).decode('cp1251').encode('utf-8')
                    except Exception:
                        pass
            from telegram import InputMediaDocument
            м = InputMediaDocument(media=bytes(data), filename=filename,
                                   caption=(подпись or None), parse_mode='HTML')
            await app.bot.edit_message_media(chat_id=чат, message_id=номер, media=м)
            return _cors(web.json_response({'ok': True, 'чат': чат, 'номер': номер,
                                            'размер': len(data)}))
        except Exception as e:
            return _cors(web.json_response({'ok': False, 'error': str(e)[:250]}, status=500))

