# ===== TB-9: уведомление владельцу о ЗАКРЕПЕ в группе/канале, где сидит бот =====
# Сервисное сообщение о закрепе НЕ ловится TEXT/media-фильтрами выше — отдельный хендлер на StatusUpdate.PINNED_MESSAGE.
async def handle_pinned(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        msg = update.effective_message
        pm = getattr(msg, "pinned_message", None) if msg else None
        if not pm:
            return
        ch = update.effective_chat
        if getattr(ch, "type", "") == "private":
            return   # закреп в личке с ботом владельцу не интересен
        title = getattr(ch, "title", None) or (("@" + ch.username) if getattr(ch, "username", None) else str(ch.id))
        body = (pm.text or pm.caption or "").strip() or "(медиа/без текста)"
        if getattr(ch, "username", None):
            link = f"https://t.me/{ch.username}/{pm.message_id}"
        else:   # приватная группа/канал: t.me/c/<внутренний id без -100>/<msg_id>
            _cid = str(ch.id)
            _cid = _cid[4:] if _cid.startswith("-100") else _cid.lstrip("-")
            link = f"https://t.me/c/{_cid}/{pm.message_id}"
        await context.bot.send_message(
            OWNER_ID,
            f"📌 Закреп в «{title}»: {body[:100]}{'…' if len(body) > 100 else ''}\nСсылка: {link}",
            disable_web_page_preview=True)
    except Exception:
        pass
app.add_handler(MessageHandler(filters.StatusUpdate.PINNED_MESSAGE, handle_pinned))
app.add_handler(ChatMemberHandler(track_member, ChatMemberHandler.CHAT_MEMBER))
# ═══ 📋 РЕЕСТР ЧАТОВ БОТА (ОБР-557, слово владельца 13.08.2026) ═══
#
# «Скинь мне список групп/каналов, к которым добавили нашего бота, кликабельными. И присылай
#  мне сразу, когда его добавляют. И облегчи мне механизм блока такого.»
#
# ЧЕГО НЕ БЫЛО. Списка не существовало вовсе: `_seen_chats` — множество В ПАМЯТИ, оно умирало
# при каждом перезапуске контейнера. Бот годами не знал, где он состоит. Уведомление о
# добавлении было, но уходило в служебный чат, куда владелец не смотрит, — то есть механизм
# работал и молчал.
#
# ⚠️ ЧЕСТНОЕ ОГРАНИЧЕНИЕ, КОТОРОЕ НЕЛЬЗЯ ОБОЙТИ: Telegram НЕ ОТДАЁТ боту список чатов, где он
# состоит, — такого запроса в их API нет. Поэтому реестр полон только с момента заведения:
# восстановить прошлое неоткуда, и обещать полный список за прошлое было бы обманом.
РЕЕСТР_ЧАТОВ = "chats_registry.json"


def _ссылка_на_чат(ch):
    """Кликабельная ссылка. У кого есть имя — по имени; у супергрупп без имени — внутренняя."""
    try:
        if getattr(ch, "username", None):
            return "https://t.me/%s" % ch.username
        ид = str(ch.id)
        if ид.startswith("-100"):
            return "https://t.me/c/%s" % ид[4:]
    except Exception:
        pass
    return ""


def _запомнить_чат(ch, статус=""):
    """Записать чат в реестр. Пишем ВСЕГДА — и когда добавили, и когда просто увидели сообщение.

    Реестр важнее одного уведомления: уведомление можно проспать, реестр остаётся."""
    try:
        р = _data_get(РЕЕСТР_ЧАТОВ, None)
        if not isinstance(р, dict):
            р = {}
        к = str(ch.id)
        было = р.get(к) or {}
        р[к] = {
            "имя": ch.title or было.get("имя") or "",
            "тип": ch.type or было.get("тип") or "",
            "ссылка": _ссылка_на_чат(ch) or было.get("ссылка") or "",
            "статус": статус or было.get("статус") or "",
            "впервые": было.get("впервые") or _now_msk(),
            "последнее": _now_msk(),
        }
        if р != было:
            _data_put(РЕЕСТР_ЧАТОВ, р, "реестр чатов: %s" % к)
        return р[к]
    except Exception:
        return {}


_seen_chats = set()
async def _chat_seen(update, context):
    try:
        ch = update.effective_chat
        if ch and ch.id not in _seen_chats:
            _seen_chats.add(ch.id)
            _запомнить_чат(ch, "виден")
            # 🔴 Заявка №9, дословно: «в чём суть такого формата? что я могу понять из него?».
            # Стояла голая строка «Чат/канал: X | id=… | type=channel» — техническая запись без
            # объяснения, зачем она и что с ней делать. Владелец справедливо не понял.
            # Теперь запись говорит ТРИ вещи: что случилось, куда нажать и зачем это вообще пишется.
            _вид = {"channel": "канал", "supergroup": "группу", "group": "группу"}.get(ch.type, "чат")
            _сс = _ссылка_на_чат(ch)
            await context.bot.send_message(
                LOG_CHAT_ID,
                ("📡 <b>Впервые вижу этот %s</b> — «%s»\n%s"
                 "id: <code>%s</code>\n\n"
                 "<i>Записал в реестр чатов: теперь его видно в кабинете и можно "
                 "разрешить, запретить или выйти. Само по себе действий не требует.</i>")
                % (_вид, html.escape(ch.title or "без названия"),
                   (_сс + "\n") if _сс else "", ch.id),
                parse_mode="HTML", disable_web_page_preview=True)
    except Exception:
        pass
async def _bot_member(update, context):
    try:
        ch = update.effective_chat; st = update.my_chat_member.new_chat_member.status
        _запомнить_чат(ch, st)
        info = f"🤖 Бот: {st} в «{ch.title}» (id={ch.id}, {ch.type})"
        добавили = st in ("member", "administrator")
        if добавили and ch.type in ("group", "supergroup", "channel"):
            a = load_access(); ok = a.get("group_open", True) or (str(ch.id) in (a.get("group_wl") or []))
            info += "\n" + ("✅ работает (группы открыты для всех)" if ok else "⛔ НЕ работает тут (режим «только свои группы»)")
            info += f"\n• Разрешить: `группа разреши {ch.id}`\n• Выйти: `покинь {ch.id}`\n• Бан: `бан {ch.id}`"
        await context.bot.send_message(LOG_CHAT_ID, info, parse_mode="Markdown")
        # 🔴 ЛИЧНО ВЛАДЕЛЬЦУ И СРАЗУ — с кнопкой, а не с командой, которую надо набирать руками.
        # Он просил «облегчи механизм блока»: раньше выход требовал скопировать id из служебного
        # чата и написать «покинь -100…». Теперь один тап.
        if добавили:
            try:
                сс = _ссылка_на_чат(ch)
                тело = ("➕ <b>Бота добавили</b> в %s «%s»\n%s\nid: <code>%s</code>"
                        % ("канал" if ch.type == "channel" else "группу",
                           html.escape(ch.title or "без названия"),
                           (сс + "\n") if сс else "", ch.id))
                кл = _КЛ([[_КБ("🚪 Выйти и больше не пускать", callback_data="grp:out:%s" % ch.id)],
                          [_КБ("✅ Оставить", callback_data="grp:ok:%s" % ch.id)]])
                await context.bot.send_message(OWNER_ID, тело, parse_mode="HTML",
                                               reply_markup=кл, disable_web_page_preview=True)
            except Exception:
                pass
    except Exception:
        pass


async def on_grp(update, context):
    """Кнопка под уведомлением: выйти и забанить — одним тапом (ОБР-557)."""
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    try:
        if q.from_user.id != OWNER_ID:
            return
        _, что, ид = q.data.split(":", 2)
        if что == "ok":
            await q.edit_message_text(q.message.text_html + "\n\n✅ Оставлено.", parse_mode="HTML",
                                      disable_web_page_preview=True)
            return
        # ⛔ Выйти И запретить возвращаться. Только выйти мало: добавят снова — и всё сначала,
        # а владелец просил «не допускай его больше туда».
        a = load_access()
        чс = [str(x) for x in (a.get("blacklist") or [])]
        if str(ид) not in чс:
            чс.append(str(ид))
        зам = dict(a.get("ban_notes") or {})
        зам[str(ид)] = "выход по кнопке владельца %s" % _now_msk()
        save_access({"blacklist": чс, "ban_notes": зам})
        ушёл = True
        try:
            await context.bot.leave_chat(int(ид))
        except Exception as e:
            ушёл = False
            подпись = "⚠️ Из чата выйти не вышло (%s), но он ЗАПРЕЩЁН — бот там молчит." % str(e)[:70]
        if ушёл:
            подпись = "🚪 Вышел и запретил. Добавят снова — бот там работать не будет."
        await q.edit_message_text(q.message.text_html + "\n\n" + подпись, parse_mode="HTML",
                                  disable_web_page_preview=True)
    except Exception as e:
        try:
            await context.bot.send_message(OWNER_ID, "⚠️ Кнопка не сработала: %s" % str(e)[:120])
        except Exception:
            pass
app.add_handler(MessageHandler(filters.ChatType.CHANNEL, _chat_seen))
app.add_handler(ChatMemberHandler(_bot_member, ChatMemberHandler.MY_CHAT_MEMBER))
app.add_handler(CallbackQueryHandler(on_grp, pattern=r'^grp:'))   # ОБР-557: кнопка «выйти и запретить»


async def _чат_в_реестр(update, context):
    """Тихо записать чат в реестр при ЛЮБОМ сообщении из группы или канала (ОБР-557).

    🔴 ЗАЧЕМ ОТДЕЛЬНАЯ ВЕТКА, А НЕ ПРАВКА `_chat_seen`. Я сказал владельцу: «как только в
    чате появится сообщение, он тут же окажется в списке» — и это было бы НЕПРАВДОЙ.
    `_chat_seen` подписан только на каналы (`filters.ChatType.CHANNEL`), да и до него дело
    почти не доходит: все обработчики живут в одной группе 0, а `handle` выше ловит любой
    текст первым и останавливает разбор. То есть группы в реестр не попадали бы вовсе.

    Поэтому регистрируем в ОТДЕЛЬНОЙ группе обработчиков (group=9): она разбирается независимо
    от нулевой, ничего у неё не отнимает и никого не подменяет. Это важнее аккуратности: чужой
    обработчик, случайно съевший сообщение группы, сломал бы бота в чатах людей.

    Пишем ОДИН раз на чат за жизнь процесса (`_seen_chats`) — реестр не должен становиться
    источником постоянной записи в ветку данных на каждое сообщение."""
    try:
        ch = update.effective_chat
        if not ch or ch.id in _seen_chats:
            return
        _seen_chats.add(ch.id)
        _запомнить_чат(ch, "виден")
    except Exception:
        pass



# ═══════════════════════════════════════════════════════════════════════════════════════════
# 📖 РАССЫЛКА «АЯТ + ХАДИС ПО ТЕМЕ» (обращение владельца #1416, 24.08.2026)
#
# Владелец дословно: «Кидай случайный аят и хадис из Бухари или Муслима тематически раз в чат.
# Аят не вырывай из контекста».
#
# Собрано из готового: Коран с переводом лежит на боевом, поиск по смыслу над Бухари уже
# работает и подбирает хадис ПО ТЕМЕ аята (не наугад), свёрнутая цитата и расписание есть.
#
# ⛔ ПО УМОЛЧАНИЮ ВЫКЛЮЧЕНО: это автомат, пишущий в чат на тысячу человек. Включает человек
#    командой «рассылка вкл». Перед этим «рассылка образец» присылает пост ЕМУ В ЛИЧКУ —
#    публиковать то, чего он не видел, нельзя.
# ═══════════════════════════════════════════════════════════════════════════════════════════
_РАС_ФАЙЛ = 'rassylka.json'
_РАС_КОРАН = {'ar': None, 'ru': None, 'когда': 0.0}
_РАС_ЧАСТИЦЫ = ('و', 'ف', 'ثم', 'أو', 'أَو', 'وَ', 'فَ')


def _рас_экр(x):
    """Свой экранировщик для этого блока.

    Почему не общий `_esc`: он объявлен ВНУТРИ другой функции и снаружи не виден — pyflakes
    честно сказал «undefined name», и я это увидел до выкатки, а не от людей.
    Почему не `html.escape`: в шапке этого файла записано, что он уже трижды падал здесь с
    NameError. Три знака — всё, что нужно Телеграму, чтобы не сломать разметку."""
    return (str(x or '').replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))


def _рас_настройки(свежо=False):
    """Настройки живут в ветке данных: перезапуск контейнера их не теряет."""
    н = _data_get(_РАС_ФАЙЛ, None)
    if not isinstance(н, dict):
        н = {}
    н.setdefault('вкл', False)
    н.setdefault('минут', 60)
    н.setdefault('чат', JAMAAT_RU_CHAT_ID)
    н.setdefault('былo', [])        # ключи «сура:аят» последних постов — чтобы не повторяться
    return н


def _рас_сохранить(н):
    try:
        _data_put(_РАС_ФАЙЛ, н, 'рассылка: настройки')
    except Exception as e:
        print('рассылка: настройки не сохранились: %s' % str(e)[:120])


def _рас_коран():
    """Коран с переводом — с боевого адреса. В контейнере файлов приложения нет, поэтому
    берём их по сети ОДИН раз и держим в памяти: 6236 аятов, полтора мегабайта."""
    if _РАС_КОРАН['ar'] and _РАС_КОРАН['ru']:
        return _РАС_КОРАН['ar'], _РАС_КОРАН['ru']
    try:
        ар = requests.get(WEBAPP_URL + 'quran.json', timeout=60).json()
        ру = requests.get(WEBAPP_URL + 'quran_ru.json', timeout=60).json()
        if isinstance(ар, list) and isinstance(ру, list) and len(ар) > 6000:
            _РАС_КОРАН['ar'], _РАС_КОРАН['ru'] = ар, ру
            _РАС_КОРАН['когда'] = time.time()
    except Exception as e:
        print('рассылка: Коран не загрузился: %s' % str(e)[:140])
    return _РАС_КОРАН['ar'], _РАС_КОРАН['ru']


def _рас_аят_с_контекстом(былo=()):
    """Случайный аят вместе с его смысловым окружением.

    ⚠️ Разметки «где начинается и кончается мысль» в наших данных НЕТ — есть только аяты.
    Границу определяем правилом, и правило это НАШЕ, не из свода:
      · короткая сура (до 11 аятов) — целиком, это и есть честный контекст;
      · иначе тянем назад, пока аят начинается с соединительной частицы (و ف ثم أو), то есть
        пока он грамматически продолжает предыдущий; и вперёд — пока следующий начинается с
        неё же. Так фраза не обрывается на середине.
    Возвращает (сура, от, до, [(аят, ар, ру)…]) либо None.
    """
    ар, ру = _рас_коран()
    if not ар or not ру:
        return None
    рус = {}
    for з in ру:
        рус[(з.get('s'), з.get('a'))] = з.get('t') or ''
    по_сурам = {}
    for з in ар:
        по_сурам.setdefault(з.get('s'), []).append(з)
    for _ in range(40):                       # несколько попыток обойти уже отправленное
        с = random.randint(1, 114)
        сп = по_сурам.get(с) or []
        if not сп:
            continue
        if len(сп) <= 11:
            от, до = 1, len(сп)
        else:
            i = random.randint(0, len(сп) - 1)
            от = до = i + 1
            while от > 1 and str(сп[от - 1].get('text') or '').lstrip().startswith(_РАС_ЧАСТИЦЫ):
                от -= 1
                if до - от >= 6:
                    break
            while до < len(сп) and str(сп[до].get('text') or '').lstrip().startswith(_РАС_ЧАСТИЦЫ):
                до += 1
                if до - от >= 6:
                    break
        ключ = '%d:%d-%d' % (с, от, до)
        if ключ in (былo or ()):
            continue
        куски = []
        for н in range(от, до + 1):
            куски.append((н, (сп[н - 1].get('text') or '').strip(), (рус.get((с, н)) or '').strip()))
        return с, от, до, куски
    return None


def _рас_хадис_по_теме(текст_ру):
    """Хадис, близкий по СМЫСЛУ к аяту — тем же поиском, что работает у людей.

    ⚠️ Ничего не нашлось выше порога — возвращаем None, и пост не уходит вовсе. Случайный
    хадис под аятом создаёт связь, которой нет; это хуже пропущенного часа."""
    try:
        нашлось, _ = _rag_find_sync(текст_ру[:400], top=3)
    except Exception as e:
        print('рассылка: поиск хадиса сорвался: %s' % str(e)[:140])
        return None
    if not нашлось:
        return None
    return нашлось[0]


def _рас_пояснение(аят_ру, хадис_ру):
    """Короткое пояснение: о чём речь и в чём польза. Строго по данным, без выдумок."""
    сист = ('Ты пишешь короткое пояснение к паре «аят Корана + хадис» для мусульманского чата. '
            'Правила, нарушать нельзя: ① говори ТОЛЬКО о том, что есть в присланных текстах, '
            'ничего не додумывай и не приводи чужих слов; ② два коротких абзаца: сперва «о чём '
            'речь», потом «польза»; ③ без заголовков, без списков, без markdown; ④ всего не '
            'больше 60 слов; ⑤ по-русски, спокойно и просто.')
    зап = 'Аят: %s\n\nХадис: %s' % ((аят_ру or '')[:900], (хадис_ру or '')[:900])
    try:
        о = ask_ai(зап, сист, owner=False, max_tokens=260) or ''
        о = re.sub(r'\n*⚡ \*Модель:.*$', '', о, flags=re.S).strip()
        return о[:700]
    except Exception as e:
        print('рассылка: пояснение не собралось: %s' % str(e)[:120])
        return ''


def _рас_собрать():
    """Готовый пост. Вернёт (текст, ключ) либо (None, причина)."""
    н = _рас_настройки()
    место = _рас_аят_с_контекстом(н.get('былo') or [])
    if not место:
        return None, 'не удалось взять аят (Коран не загрузился?)'
    с, от, до, куски = место
    ключ = '%d:%d-%d' % (с, от, до)
    аят_ру = ' '.join(к[2] for к in куски)
    хад = _рас_хадис_по_теме(аят_ру)
    if not хад:
        return None, 'по теме аята %s хадис не нашёлся выше порога — пост не отправляю' % ключ

    # Имя суры НЕ пишем: списка сур у бота нет, а заводить свою копию рядом с той, что
    # живёт в приложении, нельзя — две копии однажды разойдутся, и подпись начнёт врать
    # (З-33). Ссылка «Коран, 2:255-257» однозначна и без имени.
    где = ('%d:%d' % (с, от)) if от == до else ('%d:%d-%d' % (с, от, до))
    стр = ['📖 <b>Коран, %s</b>' % где, '']
    стр.append(_рас_экр(' '.join(к[1] for к in куски)))
    стр.append('')
    стр.append(_рас_экр(аят_ру))
    стр.append('')
    стр.append('➖➖➖')
    _ст = (хад.get('g') or '').strip()
    стр.append('📗 <b>Сахих аль-Бухари, №%s</b>%s'
               % (_рас_экр(str(хад.get('n') or '?')), (' · ' + _рас_экр(_ст)) if _ст else ''))
    стр.append('')
    if хад.get('a'):
        стр.append(_рас_экр(str(хад['a'])[:900]))
        стр.append('')
    if хад.get('r'):
        стр.append(_рас_экр(str(хад['r'])[:900]))
        стр.append('')
    пояс = _рас_пояснение(аят_ру, хад.get('r') or '')
    if пояс:
        стр.append('<blockquote expandable>💡 ' + _рас_экр(пояс) + '</blockquote>')
    return chr(10).join(стр)[:4000], ключ


async def _рас_отправить(куда=None):
    """Собрать и отправить. Вернёт строку-итог для человека."""
    н = _рас_настройки()
    текст, ключ = await asyncio.get_event_loop().run_in_executor(None, _рас_собрать)
    if not текст:
        return '🔕 ' + str(ключ)
    цель = куда or н.get('чат') or JAMAAT_RU_CHAT_ID
    try:
        await app.bot.send_message(цель, текст, parse_mode='HTML',
                                   disable_web_page_preview=True)
    except Exception as e:
        return '🔴 не отправилось: %s' % str(e)[:180]
    if куда is None:                      # образец в личку историю не засоряет
        н['былo'] = ([ключ] + list(н.get('былo') or []))[:200]
        _рас_сохранить(н)
    return '✅ отправлено (%s)' % ключ


async def _рас_тик(context=None):
    """Часовой удар расписания. Выключено — молча выходим."""
    try:
        н = _рас_настройки()
        if not н.get('вкл'):
            return
        итог = await _рас_отправить()
        if итог.startswith('🔴'):
            print('рассылка: %s' % итог[:200])
    except Exception as e:
        print('рассылка: тик сорвался: %s' % str(e)[:180])


async def _рас_команда(update, text, uid):
    """Команды владельца. Вернёт True, если это была команда рассылки."""
    if uid != OWNER_ID and not (OWNER_ID2 and uid == OWNER_ID2):
        return False
    t = (text or '').lower().strip()
    if not t.startswith('рассылка'):
        return False
    н = _рас_настройки()
    if t in ('рассылка', 'рассылка статус'):
        await _мсообщ(update).reply_text(
            '📖 <b>Рассылка «аят + хадис по теме»</b>\n'
            'Сейчас: <b>%s</b>\n'
            '• раз в <b>%d</b> мин · чат: <code>%s</code>\n'
            '• отправлено мест: %d\n\n'
            'Команды: «рассылка образец» (пришлю сюда, в чат не пойдёт) · «рассылка вкл» / '
            '«рассылка выкл» · «рассылка каждые 30» (минуты)'
            % ('ВКЛЮЧЕНА' if н.get('вкл') else 'выключена', н.get('минут') or 60,
               н.get('чат'), len(н.get('былo') or [])), parse_mode='HTML')
        return True
    if t.startswith('рассылка образец'):
        await _мсообщ(update).reply_text('📖 Собираю образец — аят, хадис по теме и пояснение…')
        итог = await _рас_отправить(куда=update.effective_chat.id)
        if итог.startswith('✅'):
            await _мсообщ(update).reply_text(
                'Вот так это будет выглядеть в чате. Годится — скажите «рассылка вкл».')
        else:
            await _мсообщ(update).reply_text(итог)
        return True
    if t in ('рассылка вкл', 'рассылка включи', 'рассылка on'):
        н['вкл'] = True
        _рас_сохранить(н)
        await _мсообщ(update).reply_text(
            '✅ Рассылка ВКЛЮЧЕНА: раз в %d мин в чат. Выключить — «рассылка выкл».'
            % (н.get('минут') or 60))
        return True
    if t in ('рассылка выкл', 'рассылка выключи', 'рассылка off'):
        н['вкл'] = False
        _рас_сохранить(н)
        await _мсообщ(update).reply_text('✅ Рассылка выключена.')
        return True
    м = re.match(r'^рассылка\s+кажд\w*\s+(\d{1,4})', t)
    if м:
        н['минут'] = max(5, min(1440, int(м.group(1))))
        _рас_сохранить(н)
        await _мсообщ(update).reply_text(
            '✅ Теперь раз в %d мин. (Новый срок вступит в силу при следующем запуске бота — '
            'расписание ставится один раз при старте.)' % н['минут'])
        return True
    return False


# ═══════════════════════════════════════════════════════════════════════════════════════════
# 🎬 ВИДЕОМОСТ (обращение владельца #1128, поправка #1135, 22.08.2026)
#
# Владелец: «если кто-то скинет сюда ссылку с инстаграма, тиктока или ютуба — переслать её в
# Muslim Live; там она упадёт в обсуждение, чужой бот скачает видео». И поправка, которая
# меняет главное: «если я пишу в чате джамаат, то понятно, что в чате джамаат имею в виду» —
# ВИДЕО ВОЗВРАЩАЕТСЯ ТУДА, ОТКУДА ПРИШЛА ССЫЛКА, а не публикуется в Muslim Live.
#
# Своей качалки не заводим: качает чужой бот, уже стоящий в обсуждении. Мы связываем шаги.
# Muslim Live остаётся ТЕХНИЧЕСКИМ перевалочным пунктом: туда уходит временная ссылка и
# оттуда убирается, как только видео доставлено.
#
# ⛔ ПО УМОЛЧАНИЮ ВЫКЛЮЧЕНО. Это автомат, который сам пишет в публичный канал. Включает
#    человек командой «видеомост вкл» — его решение, не моё.
#
# Основу написала линия мини-аппа (сессия 79) и передала готовым куском. Здесь она с моей
# правкой под поправку #1135: цепочка помнит ИСТОЧНИК ссылки (чат и сообщение). Без этого
# вернуть видео «туда, откуда пришло» нечем — у них адресат был жёстко Muslim Live.
# ═══════════════════════════════════════════════════════════════════════════════════════════
_ВМ_ФАЙЛ = 'videomost.json'
_ВМ_ЖДЁМ = {}          # ключ -> {'url','лайв','откуда','смс','когда'}
_ВМ_СРОК = 3600        # час: качалка не ответила — цепочку выбрасываем, чтобы не выложить чужое
# 23.08.2026: добавлены x.com и twitter.com. Владелец шлёт именно их (#1346, #1367), а
# запасного пути для них не было вовсе — в списке стояли только инстаграм, тикток и ютуб.
_ВМ_ССЫЛКА = re.compile(
    r'https?://(?:www\.|m\.|mobile\.)?(?:instagram\.com|instagr\.am|tiktok\.com|vm\.tiktok\.com|'
    r'vt\.tiktok\.com|youtube\.com|youtu\.be|youtube-nocookie\.com|x\.com|twitter\.com)/\S+',
    re.I)

_ВМ_КЭШ = {'когда': 0.0, 'что': None}


def _вм_настройки(свежо=False):
    """Настройки видеомоста. Живут в ветке данных: перезапуск контейнера их не теряет.

    ⚠️ В ПАМЯТИ НА ДВЕ МИНУТЫ. Обработчик стоит на ВСЕХ сообщениях подряд, а чтение ветки
    данных — поход к GitHub. Спрашивать его на каждое сообщение значит утопить бота в сетевых
    запросах на ровном месте."""
    if not свежо and _ВМ_КЭШ['что'] is not None and (time.time() - _ВМ_КЭШ['когда']) < 120:
        return _ВМ_КЭШ['что']
    н = _data_get(_ВМ_ФАЙЛ, None)
    if not isinstance(н, dict):
        н = {'вкл': False, 'чаты': []}
    н.setdefault('вкл', False)
    н.setdefault('чаты', [])
    _ВМ_КЭШ['что'] = н
    _ВМ_КЭШ['когда'] = time.time()
    return н


def _вм_сохранить(н):
    _ВМ_КЭШ['что'] = н
    _ВМ_КЭШ['когда'] = time.time()   # иначе «вкл» не подействовало бы ещё две минуты
    try:
        _data_put(_ВМ_ФАЙЛ, н, 'видеомост: настройки')
    except Exception:
        pass


def _вм_команда(text, uid):
    """Команды владельца. Вернёт текст-ответ либо None (значит это не команда)."""
    if uid != OWNER_ID and not (OWNER_ID2 and uid == OWNER_ID2):
        return None
    t = (text or '').lower().strip()
    if t in ('видеомост', 'видео мост', 'видеомост статус'):
        н = _вм_настройки()
        return ('🎬 Видеомост: %s\n'
                '• слушаю чаты: %s\n'
                '• незакрытых цепочек сейчас: %d\n\n'
                'Команды: «видеомост вкл» / «видеомост выкл» · «видеомост чат +<id>» / «чат -<id>»\n'
                'Пока выключен — ссылки не трогаю и в канал не пишу.'
                % ('ВКЛЮЧЁН' if н['вкл'] else 'выключен',
                   н['чаты'] or 'джамаат и твоя личка', len(_ВМ_ЖДЁМ)))
    if t in ('видеомост вкл', 'видеомост включи', 'видеомост on'):
        н = _вм_настройки()
        н['вкл'] = True
        _вм_сохранить(н)
        return ('✅ Видеомост ВКЛЮЧЁН. Увижу ссылку — отправлю её в Muslim Live, дождусь видео '
                'от качалки и верну ТУДА, ОТКУДА ПРИШЛА ССЫЛКА, ответом на то самое сообщение. '
                'Временный пост в Muslim Live уберу.\n'
                '⚠️ Если бот не админ в @muslimlive с правом публиковать и удалять — скажу '
                'первым же разом, а не промолчу.')
    if t in ('видеомост выкл', 'видеомост выключи', 'видеомост off'):
        н = _вм_настройки()
        н['вкл'] = False
        _вм_сохранить(н)
        return '✅ Видеомост выключен. Ссылки больше не трогаю.'
    m = re.match(r'^видеомост\s+чат\s+([+\-]?)(-?\d+)$', t)
    if m:
        н = _вм_настройки()
        ид = int(m.group(2))
        if m.group(1) == '-':
            н['чаты'] = [x for x in н['чаты'] if int(x) != ид]
        elif ид not in [int(x) for x in н['чаты']]:
            н['чаты'].append(ид)
        _вм_сохранить(н)
        return '✅ Слушаю чаты: %s' % (н['чаты'] or 'джамаат и твоя личка')
    return None


def _вм_убрать_старое():
    try:
        сейчас = time.time()
        for k in [k for k, v in _ВМ_ЖДЁМ.items()
                  if сейчас - float((v or {}).get('когда') or 0) > _ВМ_СРОК]:
            _ВМ_ЖДЁМ.pop(k, None)
    except Exception:
        pass


async def видеомост(update, context):
    """Три роли в одном обработчике — по тому, откуда пришло сообщение."""
    try:
        m = getattr(update, 'effective_message', None)
        if not m:
            return
        чат = int(getattr(m.chat, 'id', 0) or 0)
        # Дешёвое раньше дорогого: не из обсуждения и не похоже на ссылку — настройки даже
        # не спрашиваем. Обработчик висит на КАЖДОМ сообщении, и его цена должна быть нулевой.
        if чат != MUSLIM_CHAT_ID:
            _т = (m.text or m.caption or '')
            if not _т or not _ВМ_ССЫЛКА.search(_т):
                return
            # 🎬 23.08.2026. Основной обработчик теперь сам качает по ссылке и отдаёт видео
            # прямо в ответ — быстрее и без публичного канала. Он идёт РАНЬШЕ (группа 0
            # против нашей 11) и, если справился, оставляет отметку. Видеомост — ЗАПАСНОЙ
            # путь: вступает, когда наша качалка не смогла или её не звали. Без этой уступки
            # на одну ссылку сработали бы оба, и человек получил бы видео дважды.
            try:
                if _наше_видео_уже_отдано(чат, getattr(m, 'message_id', 0)):
                    return
            except Exception:
                pass
        н = _вм_настройки()
        _вм_убрать_старое()

        # ── ③④ видео от качалки в обсуждении ──────────────────────────────────────────────
        if чат == MUSLIM_CHAT_ID:
            # ② копия нашего поста прилетела в обсуждение сама — сшиваем по номеру исходного
            if getattr(m, 'is_automatic_forward', False):
                исх = getattr(m, 'forward_from_message_id', None)
                з = _ВМ_ЖДЁМ.pop('лайв:%s' % исх, None)
                if з:
                    _ВМ_ЖДЁМ[int(m.message_id)] = з
                return
            видео = getattr(m, 'video', None) or getattr(m, 'animation', None)
            отв = getattr(m, 'reply_to_message', None)
            if not (видео and отв):
                return
            з = _ВМ_ЖДЁМ.pop(int(отв.message_id), None)
            if not з:
                return
            # ⑤ ВОЗВРАЩАЕМ ТУДА, ОТКУДА ПРИШЛО (поправка владельца #1135), ответом на то самое
            # сообщение: видео без вопроса, к которому оно относится, в общем чате — загадка.
            _беда = None
            try:
                await context.bot.send_video(з['откуда'], video=видео.file_id,
                                             caption=з['url'][:900],
                                             reply_to_message_id=(з.get('смс') or None),
                                             supports_streaming=True)
            except Exception as e:
                _беда = e
                # Пробуем без привязки: исходное сообщение могли удалить, а видео нужно.
                try:
                    await context.bot.send_video(з['откуда'], video=видео.file_id,
                                                 caption=з['url'][:900],
                                                 supports_streaming=True)
                    _беда = None
                except Exception as e2:
                    _беда = e2
            if _беда is not None:
                # Молчать нельзя: человек ждёт видео, а его не будет.
                for ч in (OWNER_ID, LOG_CHAT_ID):
                    try:
                        await context.bot.send_message(
                            ч, '🎬 Видеомост: видео скачалось, но вернуть в чат %s не вышло.\n'
                               'Причина: %s\nСсылка: %s'
                               % (з['откуда'], str(_беда)[:200], з['url']))
                    except Exception:
                        pass
                return
            # временный пост в Muslim Live убираем ТОЛЬКО после удачной доставки
            try:
                await context.bot.delete_message(MUSLIM_LIVE_CHAT, з['лайв'])
            except Exception as e:
                try:
                    await context.bot.send_message(
                        OWNER_ID, '🎬 Видео доставлено, а временный пост в @muslimlive убрать '
                                  'не смог: %s' % str(e)[:160])
                except Exception:
                    pass
            return

        # ── ① ссылка в разрешённом чате ───────────────────────────────────────────────────
        if not н['вкл']:
            return
        разрешён = (чат == OWNER_ID) or (чат == JAMAAT_RU_CHAT_ID) \
            or (чат in [int(x) for x in н['чаты']])
        if not разрешён:
            return
        мс = _ВМ_ССЫЛКА.search(m.text or m.caption or '')
        if not мс:
            return
        url = мс.group(0).rstrip('.,);]')
        try:
            пост = await context.bot.send_message(MUSLIM_LIVE_CHAT, url,
                                                  disable_web_page_preview=False)
        except Exception as e:
            try:
                await m.reply_text('🎬 Видеомост: не смог отправить ссылку в @muslimlive — %s\n'
                                   'Проверь, админ ли бот в канале.' % str(e)[:200])
            except Exception:
                pass
            return
        # До прихода копии в обсуждение помним по номеру поста канала. ИСТОЧНИК запоминаем
        # здесь и только здесь: позже узнать, откуда пришла ссылка, будет уже негде.
        _ВМ_ЖДЁМ['лайв:%s' % пост.message_id] = {
            'url': url, 'лайв': int(пост.message_id), 'откуда': чат,
            'смс': int(getattr(m, 'message_id', 0) or 0), 'когда': time.time()}
    except Exception as e:
        try:
            print('видеомост:', e)
        except Exception:
            pass


app.add_handler(MessageHandler(filters.ChatType.GROUPS | filters.ChatType.CHANNEL,
                               _чат_в_реестр), group=9)
# Видеомост живёт СВОЕЙ группой обработчиков: он не должен ни перехватывать обычную
# работу бота, ни падать вместе с ней. Своя группа — свой поток исключений.
app.add_handler(MessageHandler(filters.ALL, видеомост), group=11)
async def _on_error(update, context):
    err = str(context.error); print("ERR:", err)
    # 🔴 04.09.2026. Стек НЕ выбрасываем. Раньше в журнал уходило только сообщение, и запись
    # B-011 («'NoneType' object has no attribute 'strip'», четыре раза) оказалась ненаходимой:
    # такая строка может стоять в сотне мест. Единственная улика лежала в `context.error`
    # и мы её сами стирали. Тот же урок, что уже записан: поток ошибок печатать всегда.
    _след_ошибки = ''
    try:
        import traceback as _тб
        _e = context.error
        if _e is not None and getattr(_e, '__traceback__', None) is not None:
            _кадры = _тб.format_tb(_e.__traceback__)[-12:]   # последние 12 — путь до места
            _след_ошибки = ''.join(_кадры)[-2000:]
    except Exception:
        _след_ошибки = ''
    if _след_ошибки:
        try:
            print("ERR-СЛЕД:", _след_ошибки[-600:])
        except Exception:
            pass
    if 'Conflict' in err:  # две копии бота — не спамим, settle сам
        return
    # M338: ошибки БОТА регистрируются в общий журнал с номером B-NNN (B=Bot), с дедупом и существом
    eid = ''
    try:
        cur = _data_get("errors.json", []) or []
        if not isinstance(cur, list): cur = []
        key = ('bot|' + err[:160])
        existing = None
        for e in cur:
            if e.get('key') == key: existing = e; break
        if existing:
            existing['count'] = existing.get('count', 1) + 1
            existing['last_t'] = _now_msk()   # #664 (С67): тот же приём, что в errlog() — время последнего повтора
            eid = existing.get('eid', '')
        else:
            _seq = max([e.get('bseq', 0) for e in cur] or [0]) + 1
            eid = 'B-%03d' % _seq
            try: _where = (update and getattr(update, 'effective_chat', None) and str(update.effective_chat.id)) or 'bot'
            except Exception: _where = 'bot'
            cur.append({'key': key, 'msg': err[:500], 'where': _where, 'ver': 'bot',
                        'stack': _след_ошибки,
                        'uid': '', 'count': 1, 'fixed': False, 'bseq': _seq, 'eid': eid,
                        't': _now_msk()})   # #664 (С67): время первого появления — как в errlog()
            cur = cur[-400:]
        _data_put("errors.json", cur, f"boterr: {err[:40]}")
    except Exception:
        pass
    try:
        await context.bot.send_message(LOG_CHAT_ID, ("🐞 ОШИБКА БОТА %s\n%s\n(в журнале; решить: «ошибка решена %s»)" % (eid or '—', err[:600], eid)) if eid else ("⚠️ Ошибка бота:\n" + err[:700]))
    except Exception:
        pass
app.add_error_handler(_on_error)
_load_ai_gate()   # 🔒 восстановить состояние рубильника публичного ИИ (дефолт — ВЫКЛ для публики)
from telegram import Update as _Upd
app.run_polling(drop_pending_updates=True, allowed_updates=_Upd.ALL_TYPES)
